function buildDemoCreatorOsDashboard() {
  return {
    osType: "pixelforge.creator-os-dashboard",
    status: "alpha",
    activeStationId: "station_sanctuary_arcade",
    summary: "Creator OS unifies the cozy arcade, world builder, AI bench, Porch, Commons, shelf, release workshop, and launchpad into one guided operating layer.",
    stations: [
      { id:"station_shelf", name:"Cartridge Shelf", kind:"library", readiness:86, openLoops:2, primaryAction:"Refresh active shelf cartridge and save profile." },
      { id:"station_world", name:"World Builder Arcade", kind:"creation", readiness:78, openLoops:4, primaryAction:"Turn the current world seed into a finishable starter cartridge." },
      { id:"station_sanctuary_arcade", name:"Sanctuary Arcade", kind:"experience", readiness:83, openLoops:3, primaryAction:"Run a couch quest with AI companion support." },
      { id:"station_commons", name:"Infinite Commons BBS", kind:"sharing", readiness:72, openLoops:5, primaryAction:"Prepare a rights-cleared cartridge pack for a trust circle." },
      { id:"station_release", name:"Release Gate", kind:"release", readiness:69, openLoops:6, primaryAction:"Resolve high-severity QA and export launch checklist." }
    ],
    signals: ["local-first","no-chat social layer","reviewable AI memory","rights metadata required","finish tiny games"]
  };
}
function normalizeCreatorOsDashboard(input = {}) {
  const fallback = buildDemoCreatorOsDashboard();
  const source = input && typeof input === "object" && !Array.isArray(input) ? input : fallback;
  const stations = Array.isArray(source.stations) && source.stations.length ? source.stations : fallback.stations;
  const normalized = stations.map((station, index) => ({
    id: String(station.id || `station_${index+1}`),
    name: String(station.name || `Station ${index+1}`),
    kind: String(station.kind || "station"),
    readiness: clamp(parseInt(station.readiness, 10) || 0, 0, 100),
    openLoops: Math.max(0, parseInt(station.openLoops, 10) || 0),
    primaryAction: String(station.primaryAction || "Choose the next small action.")
  })).slice(0, 12);
  return {
    osType: String(source.osType || fallback.osType),
    status: String(source.status || "alpha"),
    activeStationId: normalized.some(s => s.id === source.activeStationId) ? String(source.activeStationId) : normalized[0]?.id || "",
    summary: String(source.summary || fallback.summary),
    stations: normalized,
    signals: Array.isArray(source.signals) ? source.signals.map(String).slice(0, 12) : fallback.signals
  };
}
function renderCreatorOsDashboardPanel() {
  if (!el.creatorOsDashboardPanel) return;
  state.creatorOsDashboard = normalizeCreatorOsDashboard(state.creatorOsDashboard);
  const active = state.creatorOsDashboard.stations.find(s => s.id === state.creatorOsDashboard.activeStationId) || state.creatorOsDashboard.stations[0];
  const avg = Math.round(state.creatorOsDashboard.stations.reduce((n,s)=>n+s.readiness,0) / Math.max(1,state.creatorOsDashboard.stations.length));
  el.creatorOsDashboardPanel.innerHTML = `<article class="suite-card ready"><small>${escapeHtml(state.creatorOsDashboard.status)} · ${avg}% readiness</small><strong>${escapeHtml(active?.name || "Creator OS")}</strong><p>${escapeHtml(state.creatorOsDashboard.summary)}</p><p><em>Next: ${escapeHtml(active?.primaryAction || "Pick a station.")}</em></p></article>` + state.creatorOsDashboard.stations.map(station => `<article class="suite-card ${station.id===state.creatorOsDashboard.activeStationId?"active":""}"><small>${escapeHtml(station.kind)} · ${station.readiness}% · ${station.openLoops} open</small><strong>${escapeHtml(station.name)}</strong><p>${escapeHtml(station.primaryAction)}</p></article>`).join("");
}
function syncCreatorOsDashboard() {
  pushUndo();
  const qaOpen = (state.regionQaPass?.checks || []).filter(c => c.status !== "resolved").length;
  const launchOpen = (state.worldLaunchChecklist?.items || []).filter(i => i.required && !i.passed).length;
  const rightsWarnings = (state.rightsRegistry?.entries || []).filter(e => ["review","needs-source","blocked"].includes(e.status)).length;
  state.creatorOsDashboard = normalizeCreatorOsDashboard(state.creatorOsDashboard);
  state.creatorOsDashboard.stations = state.creatorOsDashboard.stations.map(station => {
    if (station.id === "station_world") return { ...station, openLoops: qaOpen + launchOpen, readiness: clamp(92 - (qaOpen + launchOpen) * 7, 0, 100) };
    if (station.id === "station_release") return { ...station, openLoops: launchOpen + rightsWarnings, readiness: clamp(88 - (launchOpen + rightsWarnings) * 9, 0, 100) };
    if (station.id === "station_commons") return { ...station, openLoops: rightsWarnings, readiness: clamp(82 - rightsWarnings * 8, 0, 100) };
    return station;
  });
  addPlaytestLogEntry("creator-os", "Synced Creator OS dashboard readiness from QA, launch, and rights states.", state.activeSceneId);
  renderAll("Creator OS dashboard synced.");
}
async function exportCreatorOsDashboard() {
  state.creatorOsDashboard = normalizeCreatorOsDashboard(state.creatorOsDashboard);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType:"pixelforge.creator-os-dashboard", exportVersion:ENGINE_VERSION, exportedAt:new Date().toISOString(), projectTitle:state.meta.title, projectHash, creatorOsDashboard:state.creatorOsDashboard };
  downloadBlob(new Blob([JSON.stringify(payload,null,2)], {type:"application/json"}), `${slugify(state.meta.title)}.creator-os-dashboard.v4.0.json`);
  log("Exported Creator OS Dashboard JSON.");
}

function buildDemoCartridgeLifecycle() {
  return {
    lifecycleType: "pixelforge.cartridge-lifecycle",
    activeStepId: "life_ai_scout",
    steps: [
      {id:"life_idea", label:"Idea Spark", status:"complete", output:"starter prompt + vibe lock"},
      {id:"life_world_seed", label:"World Seed", status:"complete", output:"world seed + region rack"},
      {id:"life_route", label:"Route + Questline", status:"complete", output:"route map + quest chain"},
      {id:"life_starter_cart", label:"Starter Cartridge", status:"review", output:"first playable cartridge plan"},
      {id:"life_ai_scout", label:"AI Scout + Theater", status:"active", output:"AI route findings + playtest receipt"},
      {id:"life_release_gate", label:"Release Gate", status:"open", output:"validated pack + rights registry"},
      {id:"life_shelf_bbs", label:"Shelf + BBS Share", status:"open", output:"shelf entry + Commons pack exchange card"},
      {id:"life_sequel_hook", label:"Sequel Hook", status:"draft", output:"continuity note + next cartridge seed"}
    ],
    rules: ["Do not share until rights metadata is attached.", "AI memories are local and reviewable.", "No free-text BBS chat is added by this flow.", "A cartridge should be finishable before expanding scope."]
  };
}
function normalizeCartridgeLifecycle(input = {}) {
  const fallback = buildDemoCartridgeLifecycle();
  const source = input && typeof input === "object" && !Array.isArray(input) ? input : fallback;
  const statuses = ["draft","open","active","review","complete","blocked"];
  const steps = (Array.isArray(source.steps) && source.steps.length ? source.steps : fallback.steps).map((step, index) => ({
    id: String(step.id || `life_${index+1}`),
    label: String(step.label || `Lifecycle step ${index+1}`),
    status: statuses.includes(step.status) ? step.status : "open",
    output: String(step.output || "")
  })).slice(0, 16);
  return { lifecycleType: String(source.lifecycleType || fallback.lifecycleType), activeStepId: steps.some(s=>s.id===source.activeStepId) ? String(source.activeStepId) : (steps.find(s=>s.status==="active")?.id || steps[0]?.id || ""), steps, rules: Array.isArray(source.rules) ? source.rules.map(String).slice(0, 12) : fallback.rules };
}
function renderCartridgeLifecyclePanel() {
  if (!el.cartridgeLifecyclePanel) return;
  state.cartridgeLifecycle = normalizeCartridgeLifecycle(state.cartridgeLifecycle);
  el.cartridgeLifecyclePanel.innerHTML = state.cartridgeLifecycle.steps.map((step, index) => `<article class="suite-card ${step.status} ${step.id===state.cartridgeLifecycle.activeStepId?"active":""}"><small>${index+1}. ${escapeHtml(step.status)}</small><strong>${escapeHtml(step.label)}</strong><p>${escapeHtml(step.output)}</p></article>`).join("") + `<article class="suite-card"><small>Rules</small>${state.cartridgeLifecycle.rules.map(rule => `<p>• ${escapeHtml(rule)}</p>`).join("")}</article>`;
}
function advanceCartridgeLifecycle() {
  pushUndo();
  state.cartridgeLifecycle = normalizeCartridgeLifecycle(state.cartridgeLifecycle);
  const steps = state.cartridgeLifecycle.steps;
  const idx = Math.max(0, steps.findIndex(step => step.id === state.cartridgeLifecycle.activeStepId));
  const step = steps[idx];
  if (step) step.status = step.status === "complete" ? "review" : "complete";
  const next = steps.find((s, i) => i > idx && !["complete"].includes(s.status));
  if (next) { next.status = "active"; state.cartridgeLifecycle.activeStepId = next.id; }
  addPlaytestLogEntry("lifecycle", `Advanced lifecycle from ${step?.label || "step"}.`, state.activeSceneId);
  renderAll("Cartridge lifecycle advanced.");
}
async function exportCartridgeLifecycle() {
  state.cartridgeLifecycle = normalizeCartridgeLifecycle(state.cartridgeLifecycle);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType:"pixelforge.cartridge-lifecycle", exportVersion:ENGINE_VERSION, exportedAt:new Date().toISOString(), projectTitle:state.meta.title, projectHash, cartridgeLifecycle:state.cartridgeLifecycle };
  downloadBlob(new Blob([JSON.stringify(payload,null,2)], {type:"application/json"}), `${slugify(state.meta.title)}.cartridge-lifecycle.v4.0.json`);
  log("Exported Cartridge Lifecycle JSON.");
}

