function normalizeAgentOrchestrator(input = {}) {
  const fallback = buildDemoAgentOrchestrator();
  const source = input && typeof input === "object" && !Array.isArray(input) ? input : fallback;
  const agents = (Array.isArray(source.agents) && source.agents.length ? source.agents : fallback.agents).map((agent, index) => ({ id:String(agent.id || `agent_${index+1}`), name:String(agent.name || `Agent ${index+1}`), role:String(agent.role || "helper"), assignedStation:String(agent.assignedStation || "station_world"), currentTask:String(agent.currentTask || "Awaiting task."), memoryScope:String(agent.memoryScope || "game-specific") })).slice(0, 16);
  const agentIds = new Set(agents.map(a=>a.id));
  const statuses = ["open","ready","active","done","blocked"];
  const tasks = (Array.isArray(source.tasks) && source.tasks.length ? source.tasks : fallback.tasks).map((task, index) => ({ id:String(task.id || `agent_task_${index+1}`), title:String(task.title || `Agent task ${index+1}`), agentId: agentIds.has(task.agentId) ? String(task.agentId) : (agents[0]?.id || ""), status: statuses.includes(task.status) ? task.status : "open", acceptance:String(task.acceptance || "Human review required.") })).slice(0, 32);
  return { orchestratorType:String(source.orchestratorType || fallback.orchestratorType), activeTaskId:tasks.some(t=>t.id===source.activeTaskId)?String(source.activeTaskId):(tasks.find(t=>t.status==="active")?.id || tasks[0]?.id || ""), mode:String(source.mode || "local-first-planning"), agents, tasks, boundaries:Array.isArray(source.boundaries)?source.boundaries.map(String).slice(0,12):fallback.boundaries };
}
function renderAgentOrchestratorPanel() {
  if (!el.agentOrchestratorPanel) return;
  state.agentOrchestrator = normalizeAgentOrchestrator(state.agentOrchestrator);
  const active = state.agentOrchestrator.tasks.find(t=>t.id===state.agentOrchestrator.activeTaskId) || state.agentOrchestrator.tasks[0];
  const agentById = Object.fromEntries(state.agentOrchestrator.agents.map(a=>[a.id,a]));
  el.agentOrchestratorPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.agentOrchestrator.mode)}</small><strong>${escapeHtml(active?.title || "No active task")}</strong><p>${escapeHtml(agentById[active?.agentId]?.name || "Unassigned")} · ${escapeHtml(active?.status || "")}</p><p><em>${escapeHtml(active?.acceptance || "")}</em></p></article>` + state.agentOrchestrator.agents.map(agent => `<article class="suite-card"><small>${escapeHtml(agent.role)} · ${escapeHtml(agent.memoryScope)}</small><strong>${escapeHtml(agent.name)}</strong><p>${escapeHtml(agent.currentTask)}</p></article>`).join("");
}
function assignNextAgentTask() {
  pushUndo();
  state.agentOrchestrator = normalizeAgentOrchestrator(state.agentOrchestrator);
  const task = state.agentOrchestrator.tasks.find(t=>t.status==="open") || state.agentOrchestrator.tasks.find(t=>t.status==="ready") || state.agentOrchestrator.tasks[0];
  if (task) { task.status = "active"; state.agentOrchestrator.activeTaskId = task.id; addPlaytestLogEntry("agent", `Assigned AI task: ${task.title}.`, state.activeSceneId); }
  renderAll("Assigned next AI orchestrator task.");
}
async function exportAgentOrchestrator() { state.agentOrchestrator = normalizeAgentOrchestrator(state.agentOrchestrator); const projectHash = await sha256(stableStringify(state)); const payload = { exportType:"pixelforge.agent-orchestrator", exportVersion:ENGINE_VERSION, exportedAt:new Date().toISOString(), projectTitle:state.meta.title, projectHash, agentOrchestrator:state.agentOrchestrator, boundary:"Planning and local playtest agents only; no autonomous external actions." }; downloadBlob(new Blob([JSON.stringify(payload,null,2)], {type:"application/json"}), `${slugify(state.meta.title)}.agent-orchestrator.v4.0.json`); log("Exported Agent Orchestrator JSON."); }

