function normalizeExperienceMap(input = {}) { const fallback = buildDemoExperienceMap(); const source = input && typeof input === "object" && !Array.isArray(input) ? input : fallback; const nodes = (Array.isArray(source.nodes)&&source.nodes.length?source.nodes:fallback.nodes).map((node,index)=>({ id:String(node.id||`node_${index+1}`), label:String(node.label||`Node ${index+1}`), kind:String(node.kind||"node"), connects:Array.isArray(node.connects)?node.connects.map(String).slice(0,12):[] })).slice(0,24); const ids = new Set(nodes.map(n=>n.id)); nodes.forEach(n=>{ n.connects = n.connects.filter(id=>ids.has(id)); }); return { mapType:String(source.mapType||fallback.mapType), activeNodeId:nodes.some(n=>n.id===source.activeNodeId)?String(source.activeNodeId):(nodes[0]?.id||""), nodes, legend:Array.isArray(source.legend)?source.legend.map(String).slice(0,12):fallback.legend, note:String(source.note||fallback.note) }; }
