function renderPalette() {
  el.tilePalette.innerHTML = "";
  Object.entries(tileDefs).forEach(([id, def]) => {
    const btn = document.createElement("button");
    btn.className = `tile-choice ${editor.selectedTile === id ? "active" : ""}`;
    btn.innerHTML = `<span class="tile-swatch" style="background: linear-gradient(135deg, ${def.color} 0 50%, ${def.alt} 50% 100%)"></span><small>${def.label}</small>`;
    btn.addEventListener("click", () => { editor.selectedTile = id; renderPalette(); log(`Tile selected: ${def.label}`); });
    el.tilePalette.appendChild(btn);
  });
}

function syncInputs() {
  const scene = currentScene();
  el.gameTitle.value = state.meta.title;
  el.sceneName.value = scene?.name || "Untitled Scene";
  el.sceneKind.value = scene?.kind || "scene";
  el.stageTitle.textContent = state.meta.title;
  el.stageScene.textContent = `${scene?.name || "No Scene"} · ${scene?.kind || "unknown"}`;
}

