function currentScene() { return state.scenes.find(scene => scene.id === state.activeSceneId) || state.scenes[0]; }
function selectedNpc() { return currentScene()?.npcs.find(npc => npc.id === editor.selectedNpcId) || currentScene()?.npcs[0] || null; }
function selectedItem() { return currentScene()?.items.find(item => item.id === editor.selectedItemId) || currentScene()?.items[0] || null; }
function selectedWarp() { return currentScene()?.warps.find(warp => warp.id === editor.selectedWarpId) || currentScene()?.warps[0] || null; }
function selectedEvent() { return state.journey.events.find(event => event.id === editor.selectedEventId) || state.journey.events[0] || null; }
function selectedEncounter() { return (state.journey.encounters || []).find(encounter => encounter.id === editor.selectedEncounterId) || (state.journey.encounters || [])[0] || null; }
function selectedQuest() { return state.quests.find(quest => quest.id === editor.selectedQuestId) || state.quests.find(q => q.status !== "hidden") || state.quests[0] || null; }

function setSelectionsFromScene() {
  const scene = currentScene();
  editor.selectedSceneId = scene?.id || null;
  editor.selectedNpcId = scene?.npcs[0]?.id || null;
  editor.selectedItemId = scene?.items[0]?.id || null;
  editor.selectedWarpId = scene?.warps[0]?.id || null;
  editor.selectedEventId = state.journey?.events?.[0]?.id || null;
  editor.selectedEncounterId = state.journey?.encounters?.[0]?.id || null;
  editor.selectedQuestId = state.quests?.find(q => q.status !== "hidden")?.id || state.quests?.[0]?.id || null;
  editor.selectedBeatId = state.storyBeats?.[0]?.id || null;
}

function switchScene(sceneId, message = "Scene switched.") {
  if (!state.scenes.some(s => s.id === sceneId)) return;
  state.activeSceneId = sceneId;
  advanceStoryArcForScene(sceneId);
  addPlaytestLogEntry("scene", `Opened scene: ${sceneNameById(sceneId)}`, sceneId);
  setSelectionsFromScene();
  setPlayMode(false, false);
  renderAll(message);
}

function renderSceneList() {
  el.sceneList.innerHTML = state.scenes.map(scene => {
    const counts = `${scene.npcs.length} NPC · ${scene.items.filter(i => !i.collected).length}/${scene.items.length} item · ${scene.warps.length} warp`;
    return `<button class="scene-chip ${scene.id === state.activeSceneId ? "active" : ""}" data-scene-id="${escapeAttr(scene.id)}"><span>${escapeHtml(scene.name)}</span><small>${escapeHtml(scene.kind)} · ${counts}</small></button>`;
  }).join("");
  el.sceneList.querySelectorAll(".scene-chip").forEach(btn => btn.addEventListener("click", () => switchScene(btn.dataset.sceneId, `Opened scene: ${btn.querySelector("span").textContent}`)));
}

function addScene() {
  pushUndo();
  const id = uniqueId("scene_custom", state.scenes.map(s => s.id));
  const tiles = blankTiles("grass");
  rect(tiles, 2, 10, 21, 12, "road");
  const scene = makeScene(id, "New Pixel Scene", "custom", tiles, { x: 3, y: 11 }, [], [], []);
  state.scenes.push(scene);
  state.activeSceneId = id;
  setSelectionsFromScene();
  renderAll("Added a new blank scene.");
}

function duplicateScene() {
  const scene = currentScene();
  if (!scene) return;
  pushUndo();
  const copy = structuredCloneSafe(scene);
  copy.id = uniqueId(`${scene.id}_copy`, state.scenes.map(s => s.id));
  copy.name = `${scene.name} Copy`;
  copy.npcs = copy.npcs.map(npc => ({ ...npc, id: uniqueId(`${npc.id}_copy`, copy.npcs.map(n => n.id)) }));
  copy.items = copy.items.map(item => ({ ...item, id: uniqueId(`${item.id}_copy`, copy.items.map(i => i.id)), collected: false }));
  copy.warps = copy.warps.map(warp => ({ ...warp, id: uniqueId(`${warp.id}_copy`, copy.warps.map(w => w.id)) }));
  state.scenes.push(copy);
  state.activeSceneId = copy.id;
  setSelectionsFromScene();
  renderAll(`Duplicated scene: ${scene.name}`);
}

function renderMap() {
  const scene = currentScene();
  if (!scene) return;
  ctx.clearRect(0, 0, el.canvas.width, el.canvas.height);
  for (let y = 0; y < scene.map.height; y++) {
    for (let x = 0; x < scene.map.width; x++) drawTile(x, y, scene.map.tiles[y * scene.map.width + x] || "grass");
  }
  drawGrid(scene);
  scene.warps.forEach(drawWarp);
  scene.items.filter(item => !item.collected).forEach(drawItem);
  scene.npcs.forEach(drawNpc);
  if (state.player.sceneId === scene.id) drawPlayer(state.player.x, state.player.y); else drawSpawn(scene.playerStart.x, scene.playerStart.y);
  drawModeBadge(scene);
}

function drawTile(x, y, tileId) {
  const d = tileDefs[tileId] || tileDefs.grass;
  const px = x * TILE_SIZE, py = y * TILE_SIZE;
  ctx.fillStyle = d.color;
  ctx.fillRect(px, py, TILE_SIZE, TILE_SIZE);
  ctx.fillStyle = d.alt;
  if (tileId === "grass") { if ((x + y) % 2 === 0) ctx.fillRect(px + 4, py + 22, 5, 2); if ((x * 3 + y) % 5 === 0) ctx.fillRect(px + 21, py + 9, 3, 3); }
  else if (tileId === "road") { ctx.fillRect(px, py + 14, TILE_SIZE, 5); ctx.fillRect(px + 8, py + 4, 4, 4); ctx.fillRect(px + 22, py + 24, 3, 3); }
  else if (tileId === "forest") { ctx.fillRect(px + 5, py + 14, 22, 12); ctx.fillStyle = "#123922"; ctx.fillRect(px + 14, py + 23, 4, 8); ctx.fillStyle = d.alt; ctx.fillRect(px + 9, py + 7, 14, 10); }
  else if (tileId === "water") { ctx.fillRect(px + 2, py + 9, 12, 3); ctx.fillRect(px + 15, py + 21, 14, 3); ctx.fillStyle = "rgba(255,255,255,0.35)"; ctx.fillRect(px + 4, py + 17, 5, 2); }
  else if (tileId === "mountain") { ctx.fillStyle = d.alt; ctx.beginPath(); ctx.moveTo(px + 3, py + 29); ctx.lineTo(px + 16, py + 4); ctx.lineTo(px + 30, py + 29); ctx.closePath(); ctx.fill(); ctx.fillStyle = "#f8f2de"; ctx.fillRect(px + 14, py + 8, 4, 5); }
  else if (tileId === "diner") { ctx.fillStyle = "#ffecc2"; ctx.fillRect(px + 4, py + 10, 24, 15); ctx.fillStyle = d.color; ctx.fillRect(px + 2, py + 6, 28, 8); ctx.fillStyle = "#2d2547"; ctx.fillRect(px + 13, py + 17, 6, 8); }
  else if (tileId === "pyramid") { ctx.fillStyle = d.alt; ctx.beginPath(); ctx.moveTo(px + 3, py + 29); ctx.lineTo(px + 16, py + 4); ctx.lineTo(px + 29, py + 29); ctx.closePath(); ctx.fill(); ctx.fillStyle = "rgba(255,255,255,0.36)"; ctx.fillRect(px + 15, py + 8, 2, 20); ctx.fillRect(px + 8, py + 22, 16, 2); }
  else if (tileId === "dream") { ctx.fillStyle = d.alt; ctx.fillRect(px + 6, py + 6, 5, 5); ctx.fillRect(px + 20, py + 12, 4, 4); ctx.fillRect(px + 13, py + 23, 6, 3); }
  else if (tileId === "bridge") { ctx.fillStyle = d.alt; ctx.fillRect(px + 2, py + 10, 28, 12); ctx.fillStyle = d.color; ctx.fillRect(px + 4, py + 8, 3, 18); ctx.fillRect(px + 14, py + 8, 3, 18); ctx.fillRect(px + 24, py + 8, 3, 18); }
  else if (tileId === "cabin") { ctx.fillStyle = d.alt; ctx.fillRect(px + 5, py + 12, 22, 15); ctx.fillStyle = d.color; ctx.beginPath(); ctx.moveTo(px + 3, py + 14); ctx.lineTo(px + 16, py + 4); ctx.lineTo(px + 29, py + 14); ctx.closePath(); ctx.fill(); ctx.fillStyle = "#2d1b18"; ctx.fillRect(px + 14, py + 19, 5, 8); }
  else if (tileId === "sign") { ctx.fillStyle = d.alt; ctx.fillRect(px + 15, py + 15, 3, 14); ctx.fillStyle = d.color; ctx.fillRect(px + 5, py + 7, 22, 10); ctx.fillStyle = "#20130c"; ctx.fillRect(px + 9, py + 11, 14, 2); }
  else if (tileId === "shrine") { ctx.fillStyle = d.alt; ctx.fillRect(px + 8, py + 20, 16, 7); ctx.fillStyle = d.color; ctx.beginPath(); ctx.moveTo(px + 8, py + 19); ctx.lineTo(px + 16, py + 6); ctx.lineTo(px + 24, py + 19); ctx.closePath(); ctx.fill(); ctx.fillStyle = "#ffd36e"; ctx.fillRect(px + 15, py + 13, 2, 8); }
  else if (tileId === "portal") { ctx.fillStyle = d.alt; ctx.fillRect(px + 8, py + 5, 16, 22); ctx.fillStyle = d.color; ctx.fillRect(px + 11, py + 8, 10, 16); ctx.fillStyle = "#61f0ff"; ctx.fillRect(px + 15, py + 7, 2, 18); }
  else if (tileId === "lab") { ctx.fillStyle = "#e9f7ff"; ctx.fillRect(px + 4, py + 8, 24, 18); ctx.fillStyle = d.alt; ctx.fillRect(px + 8, py + 12, 5, 5); ctx.fillRect(px + 18, py + 12, 5, 5); ctx.fillStyle = "#10142a"; ctx.fillRect(px + 10, py + 21, 12, 3); }
  else if (tileId === "cave") { ctx.fillStyle = d.alt; ctx.beginPath(); ctx.arc(px + 16, py + 23, 13, Math.PI, 0); ctx.fill(); ctx.fillStyle = "#090b16"; ctx.fillRect(px + 8, py + 18, 16, 11); }
  else if (tileId === "flowers") { ctx.fillStyle = d.alt; [[7,9],[18,8],[14,21],[24,22]].forEach(([a,b]) => ctx.fillRect(px+a, py+b, 3, 3)); ctx.fillStyle = "#2f8c51"; ctx.fillRect(px+5,py+24,22,2); }
  else if (tileId === "crystal") { ctx.fillStyle = d.alt; ctx.beginPath(); ctx.moveTo(px+16,py+4); ctx.lineTo(px+25,py+14); ctx.lineTo(px+20,py+29); ctx.lineTo(px+10,py+29); ctx.lineTo(px+7,py+14); ctx.closePath(); ctx.fill(); ctx.fillStyle = "rgba(255,255,255,.55)"; ctx.fillRect(px+14,py+9,3,15); }
  else if (tileId === "tower") { ctx.fillStyle = d.color; ctx.fillRect(px+9,py+8,14,21); ctx.fillStyle = d.alt; ctx.fillRect(px+7,py+5,18,5); ctx.fillRect(px+12,py+14,3,3); ctx.fillRect(px+18,py+20,3,3); }
  else if (tileId === "tunnel") { ctx.fillStyle = d.alt; ctx.beginPath(); ctx.arc(px+16,py+18,12,Math.PI,0); ctx.fill(); ctx.fillStyle = "#050710"; ctx.fillRect(px+7,py+18,18,11); ctx.fillStyle = "rgba(255,255,255,.20)"; ctx.fillRect(px+14,py+10,4,2); }
  else if (tileId === "neon") { ctx.fillStyle = d.alt; ctx.fillRect(px+5,py+8,22,3); ctx.fillRect(px+5,py+21,22,3); ctx.fillStyle = "#ff7aa2"; ctx.fillRect(px+9,py+12,3,8); ctx.fillRect(px+20,py+12,3,8); }
  else if (tileId === "artifact") { ctx.fillStyle = d.alt; ctx.beginPath(); ctx.moveTo(px+16,py+5); ctx.lineTo(px+26,py+16); ctx.lineTo(px+16,py+28); ctx.lineTo(px+6,py+16); ctx.closePath(); ctx.fill(); ctx.fillStyle = "rgba(255,255,255,.45)"; ctx.fillRect(px+15,py+9,2,14); }
}

function drawGrid(scene) {
  ctx.strokeStyle = "rgba(13,16,32,0.35)"; ctx.lineWidth = 1;
  for (let x = 0; x <= scene.map.width; x++) { ctx.beginPath(); ctx.moveTo(x * TILE_SIZE, 0); ctx.lineTo(x * TILE_SIZE, scene.map.height * TILE_SIZE); ctx.stroke(); }
  for (let y = 0; y <= scene.map.height; y++) { ctx.beginPath(); ctx.moveTo(0, y * TILE_SIZE); ctx.lineTo(scene.map.width * TILE_SIZE, y * TILE_SIZE); ctx.stroke(); }
}
function drawPlayer(x, y) { const px=x*TILE_SIZE, py=y*TILE_SIZE; ctx.fillStyle="rgba(0,0,0,0.22)"; ctx.fillRect(px+8,py+27,17,4); ctx.fillStyle="#21182f"; ctx.fillRect(px+9,py+9,14,19); ctx.fillStyle="#ffd36e"; ctx.fillRect(px+10,py+5,12,9); ctx.fillStyle="#8dc8ff"; ctx.fillRect(px+11,py+15,10,10); ctx.fillStyle="#111"; ctx.fillRect(px+13,py+8,2,2); ctx.fillRect(px+19,py+8,2,2); ctx.fillStyle="#ff7aa2"; ctx.fillRect(px+14,py+26,3,4); ctx.fillRect(px+19,py+26,3,4); }
function drawSpawn(x, y) { const px=x*TILE_SIZE, py=y*TILE_SIZE; ctx.strokeStyle="#8df7c8"; ctx.lineWidth=3; ctx.strokeRect(px+7,py+7,18,18); ctx.fillStyle="#8df7c8"; ctx.font="10px monospace"; ctx.fillText("SPAWN", px+1, py+30); }
function drawNpc(npc) { const px=npc.x*TILE_SIZE, py=npc.y*TILE_SIZE; ctx.fillStyle="rgba(0,0,0,0.22)"; ctx.fillRect(px+8,py+25,17,4); ctx.fillStyle=npc.color||"#f8f2de"; ctx.fillRect(px+9,py+10,14,16); ctx.fillStyle="#fff4d6"; ctx.fillRect(px+10,py+5,12,9); ctx.fillStyle="#10142a"; ctx.fillRect(px+13,py+8,2,2); ctx.fillRect(px+18,py+8,2,2); if (npc.id === editor.selectedNpcId && !editor.isPlaying) outlineCell(px,py,"#ffd36e"); }
function drawItem(item) { const px=item.x*TILE_SIZE, py=item.y*TILE_SIZE; ctx.fillStyle="rgba(0,0,0,0.22)"; ctx.fillRect(px+10,py+25,12,3); ctx.fillStyle=item.color||"#61f0ff"; ctx.fillRect(px+11,py+11,10,10); ctx.fillStyle="rgba(255,255,255,0.62)"; ctx.fillRect(px+13,py+9,3,3); ctx.fillRect(px+17,py+20,3,3); if (item.id === editor.selectedItemId && !editor.isPlaying) outlineCell(px,py,"#61f0ff"); }
function drawWarp(warp) { const px=warp.x*TILE_SIZE, py=warp.y*TILE_SIZE; ctx.fillStyle="rgba(0,0,0,0.2)"; ctx.fillRect(px+7,py+25,18,4); ctx.strokeStyle=warp.color||"#ff7aa2"; ctx.lineWidth=3; ctx.strokeRect(px+8,py+5,16,22); ctx.fillStyle=warp.color||"#ff7aa2"; ctx.fillRect(px+14,py+9,4,14); if (warp.id === editor.selectedWarpId && !editor.isPlaying) outlineCell(px,py,"#ff7aa2"); }
function outlineCell(px, py, color) { ctx.strokeStyle=color; ctx.lineWidth=3; ctx.strokeRect(px+2, py+2, TILE_SIZE-4, TILE_SIZE-4); }
function drawModeBadge(scene) { ctx.fillStyle="rgba(13,16,32,0.78)"; ctx.fillRect(8,8,340,30); ctx.fillStyle="#ffd36e"; ctx.font="14px monospace"; const mode=editor.isPlaying ? "PLAY MODE · SPACE TALKS · WARPS ACTIVE" : `EDITOR: ${editor.mode.toUpperCase()} · BRUSH ${editor.brushSize}`; ctx.fillText(`${mode} · ${scene.name}`,18,28); }

function onCanvasClick(event) {
  const pos = canvasGridPos(event); if (!pos) return;
  const scene = currentScene(); if (!scene) return;
  if (editor.isPlaying) { const npc = npcAt(pos.x, pos.y); if (npc) openDialogue(npc); return; }
  if (editor.mode === "paint") { pushUndo(); applyBrush(pos.x,pos.y,xy => setSceneTile(scene, xy.x, xy.y, editor.selectedTile)); renderAll(`Painted ${tileDefs[editor.selectedTile].label} around ${pos.x},${pos.y}.`); }
  else if (editor.mode === "erase") { pushUndo(); const r=Math.floor(editor.brushSize/2); applyBrush(pos.x,pos.y,xy => setSceneTile(scene, xy.x, xy.y, "grass")); scene.npcs = scene.npcs.filter(n => Math.abs(n.x-pos.x)>r || Math.abs(n.y-pos.y)>r); scene.items = scene.items.filter(i => Math.abs(i.x-pos.x)>r || Math.abs(i.y-pos.y)>r); scene.warps = scene.warps.filter(w => Math.abs(w.x-pos.x)>r || Math.abs(w.y-pos.y)>r); setSelectionsFromScene(); renderAll(`Cleared around ${pos.x},${pos.y}.`); }
  else if (editor.mode === "npc") { const npc=selectedNpc(); if (npc) { pushUndo(); npc.x=pos.x; npc.y=pos.y; renderAll(`Placed ${npc.name} at ${pos.x},${pos.y}.`); } }
  else if (editor.mode === "item") { const item=selectedItem(); if (item) { pushUndo(); item.x=pos.x; item.y=pos.y; item.collected=false; renderAll(`Placed ${item.name} at ${pos.x},${pos.y}.`); } }
  else if (editor.mode === "warp") { const warp=selectedWarp(); if (warp) { pushUndo(); warp.x=pos.x; warp.y=pos.y; renderAll(`Placed ${warp.name} at ${pos.x},${pos.y}.`); } }
  else if (editor.mode === "player") { if (isWalkable(pos.x,pos.y)) { pushUndo(); state.player.sceneId=scene.id; state.player.x=pos.x; state.player.y=pos.y; scene.playerStart={x:pos.x,y:pos.y}; renderAll(`Player spawn set to ${pos.x},${pos.y} in ${scene.name}.`); } else log("That tile is not walkable."); }
}
function applyBrush(cx, cy, fn) { const radius = Math.floor(editor.brushSize / 2); for (let y=cy-radius; y<=cy+radius; y++) for (let x=cx-radius; x<=cx+radius; x++) if (x>=0 && x<MAP_W && y>=0 && y<MAP_H) fn({x,y}); }
function canvasGridPos(event) { const rect = el.canvas.getBoundingClientRect(); const scaleX = el.canvas.width / rect.width; const scaleY = el.canvas.height / rect.height; const x = Math.floor((event.clientX - rect.left) * scaleX / TILE_SIZE); const y = Math.floor((event.clientY - rect.top) * scaleY / TILE_SIZE); if (x<0||x>=MAP_W||y<0||y>=MAP_H) return null; return {x,y}; }
function setSceneTile(scene, x, y, tileId) { scene.map.tiles[y * scene.map.width + x] = tileId; }

function setPlayMode(value, rerender = true) {
  editor.isPlaying = Boolean(value);
  document.getElementById("editorModeBtn").classList.toggle("active", !editor.isPlaying);
  document.getElementById("playModeBtn").classList.toggle("active", editor.isPlaying);
  el.dialogueBox.classList.add("hidden"); editor.activeDialogueNpcId = null; editor.dialogueIndex = 0;
  if (editor.isPlaying) { state.activeSceneId = state.player.sceneId || state.activeSceneId; editor.selectedSceneId = state.activeSceneId; log("Play mode on. Move with WASD/arrow keys. Warps trigger when you step on them."); }
  else log("Editor mode on.");
  if (rerender) renderAll();
}
function onKeyDown(event) {
  if (["INPUT","TEXTAREA","SELECT"].includes(document.activeElement?.tagName)) return;
  if (!editor.isPlaying) return;
  if (editor.activeDialogueNpcId && [" ", "Enter"].includes(event.key)) { event.preventDefault(); const npc=npcAtDialogue(); if (npc) openDialogue(npc, true); return; }
  const moves = { ArrowUp:[0,-1], w:[0,-1], W:[0,-1], ArrowDown:[0,1], s:[0,1], S:[0,1], ArrowLeft:[-1,0], a:[-1,0], A:[-1,0], ArrowRight:[1,0], d:[1,0], D:[1,0] };
  if (moves[event.key]) { event.preventDefault(); movePlayer(...moves[event.key]); }
  else if ([" ", "Enter"].includes(event.key)) { event.preventDefault(); interact(); }
}
function movePlayer(dx, dy) {
  const nx=state.player.x+dx, ny=state.player.y+dy;
  if (!isWalkable(nx,ny)) { log("Blocked by terrain."); return; }
  state.player.x=nx; state.player.y=ny;
  const item=itemAt(nx,ny); if (item) collectItem(item);
  const warp=warpAt(nx,ny); if (warp) { triggerWarp(warp); return; }
  renderMap();
}
function isWalkable(x,y) { const scene=currentScene(); if (!scene || x<0||x>=MAP_W||y<0||y>=MAP_H) return false; const tile=scene.map.tiles[y*scene.map.width+x]; return Boolean(tileDefs[tile]?.walkable); }
function npcAt(x,y) { return currentScene()?.npcs.find(n => n.x===x && n.y===y) || null; }
function itemAt(x,y) { return currentScene()?.items.find(i => !i.collected && i.x===x && i.y===y) || null; }
function warpAt(x,y) { return currentScene()?.warps.find(w => w.x===x && w.y===y) || null; }
function collectItem(item) { item.collected = true; state.inventory ||= []; if (!state.inventory.includes(item.id)) state.inventory.push(item.id); applyDelta(item.effect); renderAll(`Collected ${item.name}.`); if (item.type === "signal") revealQuest("quest_collect_signal"); }
function triggerWarp(warp) {
  const gate = checkWarpGate(warp);
  if (!gate.ok) {
    el.dialogueBox.classList.remove("hidden");
    el.dialogueBox.innerHTML = `<strong>${escapeHtml(warp.name)}</strong><p>${escapeHtml(gate.message)}</p><small>Story gate blocked</small>`;
    log(`Warp blocked: ${gate.message}`);
    renderMap();
    return;
  }
  const target = state.scenes.find(s => s.id === warp.targetSceneId);
  if (!target) { log(`Warp target missing: ${warp.targetSceneId}`); return; }
  state.activeSceneId = target.id;
  state.player.sceneId = target.id;
  state.player.x = clamp(parseInt(warp.targetX,10)||target.playerStart.x,0,MAP_W-1);
  state.player.y = clamp(parseInt(warp.targetY,10)||target.playerStart.y,0,MAP_H-1);
  unlockBeatForScene(target.id);
  setSelectionsFromScene();
  renderAll(`Warped through ${warp.name} → ${target.name}.`);
}
function checkWarpGate(warp) {
  const requirements = [];
  if (warp.requiredItemId && !(state.inventory || []).includes(warp.requiredItemId)) requirements.push(`item ${itemNameById(warp.requiredItemId)}`);
  if (warp.requiredQuestId && state.quests.find(q => q.id === warp.requiredQuestId)?.status !== "complete") requirements.push(`completed quest ${questTitleById(warp.requiredQuestId)}`);
  if (Number.isInteger(warp.requiredWonder) && state.journey.stats.wonder < warp.requiredWonder) requirements.push(`${warp.requiredWonder} Wonder`);
  if (!requirements.length) return { ok: true, message: "Gate open." };
  return { ok: false, message: warp.blockedText || `Need ${requirements.join(", ")} before this path opens.` };
}
function unlockBeatForScene(sceneId) {
  (state.storyBeats || []).filter(beat => beat.sceneId === sceneId && beat.status === "locked").forEach(beat => { beat.status = "active"; log(`Story beat unlocked: ${beat.title}`); });
}
function applyDelta(delta) { Object.entries(delta || {}).forEach(([key,value]) => { if (statKeys.includes(key)) state.journey.stats[key] = clamp((state.journey.stats[key] || 0) + parseInt(value,10), 0, 99); }); }
function interact() { const dirs=[[0,0],[0,-1],[0,1],[-1,0],[1,0]]; for (const [dx,dy] of dirs) { const npc=npcAt(state.player.x+dx,state.player.y+dy); if (npc) { openDialogue(npc); return; } } log("No one nearby to talk to."); }
function npcAtDialogue() { const scene=currentScene(); return scene?.npcs.find(n => n.id === editor.activeDialogueNpcId) || null; }
function openDialogue(npc, advance=false) {
  if (!advance || editor.activeDialogueNpcId !== npc.id) {
    editor.activeDialogueNpcId=npc.id;
    editor.dialogueIndex=0;
    if (!npc.talked) {
      npc.talked=true;
      applyDelta(npc.effect);
      if (npc.revealsQuestId) revealQuest(npc.revealsQuestId);
    }
  } else editor.dialogueIndex++;
  const lines = npc.dialogue?.length ? npc.dialogue : ["..."];
  if (editor.dialogueIndex >= lines.length) {
    if (Array.isArray(npc.choices) && npc.choices.length) { renderDialogueChoices(npc); return; }
    el.dialogueBox.classList.add("hidden");
    editor.activeDialogueNpcId=null; editor.dialogueIndex=0;
    renderAll(`Finished talking to ${npc.name}.`);
    return;
  }
  el.dialogueBox.classList.remove("hidden");
  el.dialogueBox.innerHTML = `<strong>${escapeHtml(npc.name)}</strong><p>${escapeHtml(lines[editor.dialogueIndex])}</p><small>Space/Enter for next line</small>`;
  renderStats(); renderMap();
}
function renderDialogueChoices(npc) {
  el.dialogueBox.classList.remove("hidden");
  el.dialogueBox.innerHTML = `<strong>${escapeHtml(npc.name)}</strong><p>What do you do?</p><div class="choice-list">${npc.choices.map((choice,index)=>`<button class="choice-btn" data-choice-index="${index}">${escapeHtml(choice.label || `Choice ${index+1}`)}</button>`).join("")}</div>`;
  el.dialogueBox.querySelectorAll(".choice-btn").forEach(btn => btn.addEventListener("click", () => chooseDialogueOption(npc, parseInt(btn.dataset.choiceIndex,10))));
  renderMap();
}
function chooseDialogueOption(npc, index) {
  const choice = npc.choices?.[index];
  if (!choice) return;
  pushUndo();
  applyDelta(choice.delta || {});
  if (choice.revealQuestId) revealQuest(choice.revealQuestId);
  if (choice.setFlag) state.flags[choice.setFlag] = true;
  el.dialogueBox.innerHTML = `<strong>${escapeHtml(npc.name)}</strong><p>${escapeHtml(choice.response || "...")}</p><small>Choice: ${escapeHtml(choice.label || "choice")}</small>`;
  editor.activeDialogueNpcId = null; editor.dialogueIndex = 0;
  renderStats(); renderQuestLog(); renderQuestEditor(); renderStoryBeats(); renderStoryArc(); addPlaytestLogEntry("encounter", encounter.text, state.activeSceneId); updateHash();
  log(`Dialogue choice selected: ${npc.name} / ${choice.label}`);
}

function renderNpcList() { const scene=currentScene(); el.npcList.innerHTML = scene.npcs.map(npc => `<button class="npc-chip ${npc.id===editor.selectedNpcId?"active":""}" data-id="${escapeAttr(npc.id)}"><span>${escapeHtml(npc.name)}</span><small>${escapeHtml(npc.role||"NPC")} · ${npc.x},${npc.y}</small></button>`).join("") || `<p>No NPCs yet.</p>`; el.npcList.querySelectorAll(".npc-chip").forEach(btn => btn.addEventListener("click", () => { editor.selectedNpcId=btn.dataset.id; renderNpcList(); renderNpcEditor(); renderMap(); })); }
function renderNpcEditor() {
  const npc=selectedNpc();
  if (!npc) { el.npcEditor.innerHTML="<p>Add an NPC, then place it on the map.</p>"; return; }
  el.npcEditor.innerHTML = `<label>Name<input id="npcName" value="${escapeAttr(npc.name)}"></label><label>Role<input id="npcRole" value="${escapeAttr(npc.role||"")}"></label><div class="row"><label>Color<input id="npcColor" type="color" value="${escapeAttr(npc.color||"#f8f2de")}"></label><label>Reveal quest<input id="npcReveal" value="${escapeAttr(npc.revealsQuestId||"")}" placeholder="quest_id optional"></label></div><label>Dialogue lines<textarea id="npcDialogue">${escapeHtml((npc.dialogue||[]).join("\n"))}</textarea></label><label>First-talk stat effect<textarea id="npcEffect" placeholder="wonder: 1\ncoherence: 1">${escapeHtml(deltaToLines(npc.effect||{}))}</textarea></label><label>Choice lines<textarea id="npcChoices" placeholder="Ask about pyramid => The road answers softly. | wonder:1 | reveal:quest_id | flag:asked_pyramid">${escapeHtml(choicesToLines(npc.choices||[]))}</textarea></label><button id="saveNpcBtn" class="secondary full">Save NPC</button>`;
  document.getElementById("saveNpcBtn").addEventListener("click", () => {
    pushUndo();
    npc.name=document.getElementById("npcName").value.trim()||"NPC";
    npc.role=document.getElementById("npcRole").value.trim();
    npc.color=document.getElementById("npcColor").value;
    npc.revealsQuestId=document.getElementById("npcReveal").value.trim();
    if (!npc.revealsQuestId) delete npc.revealsQuestId;
    npc.dialogue=document.getElementById("npcDialogue").value.split("\n").map(s=>s.trim()).filter(Boolean);
    npc.effect=linesToDelta(document.getElementById("npcEffect").value);
    npc.choices=linesToChoices(document.getElementById("npcChoices").value);
    renderAll(`Saved NPC: ${npc.name}`);
  });
}
function addNpc() { const scene=currentScene(); pushUndo(); const npc={ id: uniqueId("npc_custom", scene.npcs.map(n=>n.id)), name:"New Weird Friend", role:"NPC", x: state.player.sceneId===scene.id?state.player.x:scene.playerStart.x, y: state.player.sceneId===scene.id?state.player.y:scene.playerStart.y, color:"#f8f2de", dialogue:["I was born in the editor.", "Please give me one funny line and one sincere line."], effect:{} }; scene.npcs.push(npc); editor.selectedNpcId=npc.id; renderAll("Added NPC."); }

function renderItemList() { const scene=currentScene(); el.itemList.innerHTML = scene.items.map(item => `<button class="npc-chip item-chip ${item.id===editor.selectedItemId?"active":""}" data-id="${escapeAttr(item.id)}"><span>${escapeHtml(item.name)}</span><small>${escapeHtml(item.type||"item")} · ${item.collected?"collected":"open"}</small></button>`).join("") || `<p>No items yet.</p>`; el.itemList.querySelectorAll(".item-chip").forEach(btn => btn.addEventListener("click", () => { editor.selectedItemId=btn.dataset.id; renderItemList(); renderItemEditor(); renderMap(); })); }
function renderItemEditor() { const item=selectedItem(); if (!item) { el.itemEditor.innerHTML="<p>Add an item, then place it on the map.</p>"; return; } el.itemEditor.innerHTML = `<label>Name<input id="itemName" value="${escapeAttr(item.name)}"></label><div class="row"><label>Type<input id="itemType" value="${escapeAttr(item.type||"relic")}"></label><label>Color<input id="itemColor" type="color" value="${escapeAttr(item.color||"#61f0ff")}"></label></div><label>Stat effect<textarea id="itemEffect">${escapeHtml(deltaToLines(item.effect||{}))}</textarea></label><button id="saveItemBtn" class="secondary full">Save Item</button><button id="uncollectItemBtn" class="secondary full">Mark Uncollected</button>`; document.getElementById("saveItemBtn").addEventListener("click", () => { pushUndo(); item.name=document.getElementById("itemName").value.trim()||"Item"; item.type=document.getElementById("itemType").value.trim()||"relic"; item.color=document.getElementById("itemColor").value; item.effect=linesToDelta(document.getElementById("itemEffect").value); renderAll(`Saved item: ${item.name}`); }); document.getElementById("uncollectItemBtn").addEventListener("click", () => { pushUndo(); item.collected=false; state.inventory = (state.inventory || []).filter(id => id !== item.id); renderAll(`Marked ${item.name} uncollected.`); }); }
function addItem() { const scene=currentScene(); pushUndo(); const item={ id: uniqueId("item_custom", scene.items.map(i=>i.id)), name:"New Shiny Thing", type:"relic", x: state.player.sceneId===scene.id?state.player.x:scene.playerStart.x, y: state.player.sceneId===scene.id?state.player.y:scene.playerStart.y, color:"#61f0ff", collected:false, effect:{ wonder:1 } }; scene.items.push(item); editor.selectedItemId=item.id; renderAll("Added item."); }
function renderInventory() { const allItems = state.scenes.flatMap(scene => scene.items.map(item => ({...item, sceneName: scene.name}))); const collected = (state.inventory || []).map(id => allItems.find(item => item.id === id)).filter(Boolean); el.inventoryList.innerHTML = collected.length ? collected.map(item => `<span class="inventory-pill"><span style="background:${escapeAttr(item.color||"#61f0ff")}"></span>${escapeHtml(item.name)}</span>`).join("") : "No items collected yet."; }

function renderWarpList() { const scene=currentScene(); el.warpList.innerHTML = scene.warps.map(warp => `<button class="npc-chip warp-chip ${warp.id===editor.selectedWarpId?"active":""}" data-id="${escapeAttr(warp.id)}"><span>${escapeHtml(warp.name)}</span><small>to ${escapeHtml(sceneNameById(warp.targetSceneId))} · ${warp.x},${warp.y}</small></button>`).join("") || `<p>No warps yet.</p>`; el.warpList.querySelectorAll(".warp-chip").forEach(btn => btn.addEventListener("click", () => { editor.selectedWarpId=btn.dataset.id; renderWarpList(); renderWarpEditor(); renderMap(); })); }
function renderWarpEditor() {
  const warp=selectedWarp();
  if (!warp) { el.warpEditor.innerHTML="<p>Add a warp, then link it to another scene.</p>"; return; }
  const sceneOptions = state.scenes.map(scene => `<option value="${escapeAttr(scene.id)}" ${scene.id===warp.targetSceneId?"selected":""}>${escapeHtml(scene.name)}</option>`).join("");
  const itemOptions = `<option value="">No item gate</option>` + state.scenes.flatMap(scene => scene.items.map(item => `<option value="${escapeAttr(item.id)}" ${item.id===warp.requiredItemId?"selected":""}>${escapeHtml(item.name)} · ${escapeHtml(scene.name)}</option>`)).join("");
  const questOptions = `<option value="">No quest gate</option>` + state.quests.map(q => `<option value="${escapeAttr(q.id)}" ${q.id===warp.requiredQuestId?"selected":""}>${escapeHtml(q.title)}</option>`).join("");
  el.warpEditor.innerHTML = `<label>Name<input id="warpName" value="${escapeAttr(warp.name)}"></label><label>Target scene<select id="warpTarget">${sceneOptions}</select></label><div class="row"><label>Target X<input id="warpTargetX" type="number" min="0" max="23" value="${warp.targetX}"></label><label>Target Y<input id="warpTargetY" type="number" min="0" max="15" value="${warp.targetY}"></label></div><label>Required item<select id="warpRequiredItem">${itemOptions}</select></label><label>Required completed quest<select id="warpRequiredQuest">${questOptions}</select></label><div class="row"><label>Required Wonder<input id="warpRequiredWonder" type="number" min="0" max="99" value="${Number.isInteger(warp.requiredWonder)?warp.requiredWonder:""}" placeholder="optional"></label><label>Color<input id="warpColor" type="color" value="${escapeAttr(warp.color||"#ff7aa2")}"></label></div><label>Blocked text<textarea id="warpBlockedText" placeholder="What the gate says when blocked">${escapeHtml(warp.blockedText||"")}</textarea></label><button id="saveWarpBtn" class="secondary full">Save Warp</button>`;
  document.getElementById("saveWarpBtn").addEventListener("click", () => {
    pushUndo();
    warp.name=document.getElementById("warpName").value.trim()||"Warp";
    warp.targetSceneId=document.getElementById("warpTarget").value;
    warp.targetX=clamp(parseInt(document.getElementById("warpTargetX").value,10)||0,0,MAP_W-1);
    warp.targetY=clamp(parseInt(document.getElementById("warpTargetY").value,10)||0,0,MAP_H-1);
    warp.requiredItemId=document.getElementById("warpRequiredItem").value || undefined;
    warp.requiredQuestId=document.getElementById("warpRequiredQuest").value || undefined;
    const wonderRaw = document.getElementById("warpRequiredWonder").value;
    if (wonderRaw === "") delete warp.requiredWonder; else warp.requiredWonder=clamp(parseInt(wonderRaw,10)||0,0,99);
    warp.blockedText=document.getElementById("warpBlockedText").value.trim(); if (!warp.blockedText) delete warp.blockedText;
    warp.color=document.getElementById("warpColor").value;
    if (!warp.requiredItemId) delete warp.requiredItemId;
    if (!warp.requiredQuestId) delete warp.requiredQuestId;
    renderAll(`Saved warp: ${warp.name}`);
  });
}
function addWarp() { const scene=currentScene(); pushUndo(); const target = state.scenes.find(s => s.id !== scene.id) || scene; const warp={ id: uniqueId("warp_custom", scene.warps.map(w=>w.id)), name:"New Doorway", x:scene.playerStart.x, y:scene.playerStart.y, targetSceneId:target.id, targetX:target.playerStart.x, targetY:target.playerStart.y, color:"#ff7aa2" }; scene.warps.push(warp); editor.selectedWarpId=warp.id; renderAll("Added warp."); }

function renderEventEditor() { const event=selectedEvent(); if (!event) { el.eventEditor.innerHTML="<p>No journey events yet.</p><button id='addEventBtn' class='secondary full'>Add Event</button>"; document.getElementById("addEventBtn").addEventListener("click", addEvent); return; } el.eventEditor.innerHTML = `<label>Event title<input id="eventTitle" value="${escapeAttr(event.title)}"></label><label>Event text<textarea id="eventText">${escapeHtml(event.text)}</textarea></label><label>Stat delta<textarea id="eventDelta">${escapeHtml(deltaToLines(event.delta||{}))}</textarea></label><button id="saveEventBtn" class="secondary full">Save Event</button><button id="addEventBtn" class="secondary full">Add Event</button>`; document.getElementById("saveEventBtn").addEventListener("click", () => { pushUndo(); event.title=document.getElementById("eventTitle").value.trim()||"Untitled Event"; event.text=document.getElementById("eventText").value.trim()||"Something strange happens."; event.delta=linesToDelta(document.getElementById("eventDelta").value); renderAll(`Saved event: ${event.title}`); }); document.getElementById("addEventBtn").addEventListener("click", addEvent); }
function addEvent() { pushUndo(); const ev={id:uniqueId("event_custom", state.journey.events.map(e=>e.id)), title:"New Road Event", text:"A tiny strange moment changes the road.", delta:{wonder:1}}; state.journey.events.push(ev); editor.selectedEventId=ev.id; renderAll("Added journey event."); }
function drawJourneyEvent() { const events=state.journey.events; if (!events.length) { log("No journey events available."); return; } pushUndo(); const index=state.journey.eventCursor % events.length; const event=events[index]; state.journey.eventCursor=(state.journey.eventCursor+1)%events.length; applyDelta(event.delta); el.eventCard.innerHTML=`<strong>${escapeHtml(event.title)}</strong><p>${escapeHtml(event.text)}</p><small>${escapeHtml(deltaToLines(event.delta||{}).replace(/\n/g, " · ") || "No stat change")}</small>`; addPlaytestLogEntry("event", event.text, state.activeSceneId); renderStats(); updateHash(); log(`Journey event: ${event.title}`); }
function renderEncounterEditor() {
  const encounter = selectedEncounter();
  if (!encounter) {
    el.encounterEditor.innerHTML = "<p>No encounters yet.</p><button id='addEncounterBtn' class='secondary full'>Add Encounter</button>";
    document.getElementById("addEncounterBtn").addEventListener("click", addEncounter);
    return;
  }
  el.encounterEditor.innerHTML = `<label>Encounter title<input id="encounterTitle" value="${escapeAttr(encounter.title)}"></label><label>Kind<input id="encounterKind" value="${escapeAttr(encounter.kind||"weird")}" placeholder="weird, kindness, inner, bureaucracy"></label><label>Encounter text<textarea id="encounterText">${escapeHtml(encounter.text)}</textarea></label><label>Stat delta<textarea id="encounterDelta">${escapeHtml(deltaToLines(encounter.delta||{}))}</textarea></label><div class="row"><label>Reveal quest<input id="encounterReveal" value="${escapeAttr(encounter.revealQuestId||"")}" placeholder="quest_id optional"></label><label>Set flag<input id="encounterFlag" value="${escapeAttr(encounter.setFlag||"")}" placeholder="flag_name optional"></label></div><button id="saveEncounterBtn" class="secondary full">Save Encounter</button><button id="addEncounterBtn" class="secondary full">Add Encounter</button>`;
  document.getElementById("saveEncounterBtn").addEventListener("click", () => {
    pushUndo();
    encounter.title = document.getElementById("encounterTitle").value.trim() || "Untitled Encounter";
    encounter.kind = document.getElementById("encounterKind").value.trim() || "weird";
    encounter.text = document.getElementById("encounterText").value.trim() || "Something jumps out of the tall grass of reality.";
    encounter.delta = linesToDelta(document.getElementById("encounterDelta").value);
    encounter.revealQuestId = document.getElementById("encounterReveal").value.trim();
    encounter.setFlag = document.getElementById("encounterFlag").value.trim();
    if (!encounter.revealQuestId) delete encounter.revealQuestId;
    if (!encounter.setFlag) delete encounter.setFlag;
    renderAll(`Saved encounter: ${encounter.title}`);
  });
  document.getElementById("addEncounterBtn").addEventListener("click", addEncounter);
}
function addEncounter() {
  pushUndo();
  state.journey.encounters ||= [];
  const enc = { id: uniqueId("encounter_custom", state.journey.encounters.map(e => e.id)), title: "New Strange Encounter", kind: "weird", text: "A funny little obstacle asks the party to become more coherent.", delta: { wonder: 1, coherence: 1 } };
  state.journey.encounters.push(enc);
  editor.selectedEncounterId = enc.id;
  renderAll("Added encounter.");
}
function drawEncounter() {
  const encounters = state.journey.encounters || [];
  if (!encounters.length) { log("No encounters available."); return; }
  pushUndo();
  const index = (state.journey.encounterCursor || 0) % encounters.length;
  const encounter = encounters[index];
  state.journey.encounterCursor = (index + 1) % encounters.length;
  applyDelta(encounter.delta);
  if (encounter.revealQuestId) revealQuest(encounter.revealQuestId);
  if (encounter.setFlag) state.flags[encounter.setFlag] = true;
  el.encounterCard.innerHTML = `<strong>${escapeHtml(encounter.title)}</strong><p>${escapeHtml(encounter.text)}</p><small>${escapeHtml(encounter.kind || "encounter")} · ${escapeHtml(deltaToLines(encounter.delta||{}).replace(/\n/g, " · ") || "No stat change")}</small>`;
  renderStats(); renderQuestLog(); renderQuestEditor(); renderStoryBeats(); renderStoryArc(); addPlaytestLogEntry("encounter", encounter.text, state.activeSceneId); updateHash();
  log(`Encounter: ${encounter.title}`);
}
function renderStats() { el.statSupplies.textContent=state.journey.stats.supplies; el.statMorale.textContent=state.journey.stats.morale; el.statWonder.textContent=state.journey.stats.wonder; el.statCoherence.textContent=state.journey.stats.coherence; }
function renderQuestLog() {
  el.questLog.innerHTML = state.quests.filter(q=>q.status!=="hidden").map(q => `<button class="quest quest-select ${q.status} ${q.id===editor.selectedQuestId?"active":""}" data-id="${escapeAttr(q.id)}"><small>${escapeHtml(q.status)}${q.chapter ? ` · ${escapeHtml(q.chapter)}` : ""}</small><strong>${escapeHtml(q.title)}</strong><p>${escapeHtml(q.description||"")}</p></button>`).join("") || "No visible quests yet.";
  el.questLog.querySelectorAll(".quest-select").forEach(btn => btn.addEventListener("click", () => { editor.selectedQuestId = btn.dataset.id; renderQuestLog(); renderQuestEditor(); }));
}
function renderQuestEditor() {
  const q = selectedQuest();
  if (!q) { el.questEditor.innerHTML = "<p>Add a quest to start building the story spine.</p>"; return; }
  el.questEditor.innerHTML = `<label>Quest title<input id="questTitle" value="${escapeAttr(q.title)}"></label><label>Quest ID<input id="questId" value="${escapeAttr(q.id)}"></label><label>Chapter<input id="questChapter" value="${escapeAttr(q.chapter||"")}" placeholder="Road to Shasta"></label><label>Status<select id="questStatus"><option value="hidden" ${q.status==="hidden"?"selected":""}>hidden</option><option value="active" ${q.status==="active"?"selected":""}>active</option><option value="complete" ${q.status==="complete"?"selected":""}>complete</option></select></label><label>Description<textarea id="questDescription">${escapeHtml(q.description||"")}</textarea></label><button id="saveQuestBtn" class="secondary full">Save Quest</button>`;
  document.getElementById("saveQuestBtn").addEventListener("click", () => {
    pushUndo();
    const oldId = q.id;
    const newId = slugify(document.getElementById("questId").value).replace(/-/g,"_") || oldId;
    if (newId !== oldId && state.quests.some(other => other !== q && other.id === newId)) { log(`Quest ID already exists: ${newId}`); return; }
    q.id = newId; q.title = document.getElementById("questTitle").value.trim() || "Untitled Quest"; q.chapter = document.getElementById("questChapter").value.trim(); q.status = document.getElementById("questStatus").value; q.description = document.getElementById("questDescription").value.trim();
    if (newId !== oldId) updateQuestReferences(oldId, newId);
    editor.selectedQuestId = q.id;
    renderAll(`Saved quest: ${q.title}`);
  });
}
function addQuest() {
  pushUndo();
  const q = { id: uniqueId("quest_custom", state.quests.map(q => q.id)), title: "New Quest", status: "active", chapter: "Custom", description: "Describe the objective, emotional beat, or strange errand." };
  state.quests.push(q); editor.selectedQuestId = q.id; renderAll("Added quest.");
}
function updateQuestReferences(oldId, newId) {
  state.scenes.forEach(scene => {
    scene.npcs.forEach(npc => { if (npc.revealsQuestId === oldId) npc.revealsQuestId = newId; (npc.choices || []).forEach(choice => { if (choice.revealQuestId === oldId) choice.revealQuestId = newId; }); });
    scene.warps.forEach(warp => { if (warp.requiredQuestId === oldId) warp.requiredQuestId = newId; });
  });
}
function renderStoryBeats() {
  const beats = state.storyBeats || [];
  el.storyBeatPanel.innerHTML = beats.length ? beats.map(beat => `<article class="story-beat ${beat.status}"><small>${escapeHtml(beat.status)} · ${escapeHtml(sceneNameById(beat.sceneId))}</small><strong>${escapeHtml(beat.title)}</strong><p>${escapeHtml(beat.text||"")}</p></article>`).join("") : "No story beats yet.";
}

function renderStoryArc() {
  if (!el.storyArcPanel) return;
  const arc = state.storyArc || { title: "Story Arc", acts: [] };
  const acts = Array.isArray(arc.acts) ? arc.acts : [];
  el.storyArcPanel.innerHTML = acts.length ? acts.map(act => {
    const beats = (act.beatIds || []).map(id => (state.storyBeats || []).find(beat => beat.id === id)?.title || id).join(" · ");
    return `<article class="story-act ${escapeAttr(act.status || "locked")}"><small>${escapeHtml(act.status || "locked")}</small><strong>${escapeHtml(act.title || "Untitled Act")}</strong><p>${escapeHtml(act.goal || "No goal written yet.")}</p>${beats ? `<p><em>${escapeHtml(beats)}</em></p>` : ""}</article>`;
  }).join("") : "No story acts yet.";
}
function addStoryAct() {
  pushUndo();
  state.storyArc ||= { title: "Story Arc", currentActId: "", acts: [] };
  state.storyArc.acts ||= [];
  const act = { id: uniqueId("act_custom", state.storyArc.acts.map(a => a.id)), title: "New Story Act", status: "locked", goal: "Describe the emotional purpose of this chapter.", beatIds: [] };
  state.storyArc.acts.push(act);
  if (!state.storyArc.currentActId) state.storyArc.currentActId = act.id;
  addPlaytestLogEntry("story-arc", `Added story act: ${act.title}`, state.activeSceneId);
  renderAll("Added story act.");
}
function renderPlaytestLog() {
  if (!el.playtestLog) return;
  const entries = Array.isArray(state.playtestLog) ? state.playtestLog.slice(-12).reverse() : [];
  el.playtestLog.innerHTML = entries.length ? entries.map(entry => `<article class="playtest-entry"><small>${escapeHtml(entry.type || "note")} · ${escapeHtml(sceneNameById(entry.sceneId))}</small><strong>${escapeHtml(entry.createdAt || "session")}</strong><p>${escapeHtml(entry.text || "")}</p><span class="tag">${escapeHtml(entry.id || "entry")}</span></article>`).join("") : "No playtest notes yet.";
}
function addPlaytestLogEntry(type, text, sceneId = state.activeSceneId) {
  state.playtestLog ||= [];
  const entry = { id: uniqueId("playtest", state.playtestLog.map(e => e.id)), type: String(type || "note"), sceneId: sceneId || state.activeSceneId, text: String(text || "Note added."), createdAt: new Date().toISOString() };
  state.playtestLog.push(entry);
  if (state.playtestLog.length > 50) state.playtestLog = state.playtestLog.slice(-50);
  renderPlaytestLog();
  return entry;
}
function addPlaytestNote() {
  pushUndo();
  const scene = currentScene();
  addPlaytestLogEntry("note", `Manual note: ${scene?.name || "current scene"} needs playtest attention.`, state.activeSceneId);
  updateHash();
  log("Added playtest note.");
}
function clearPlaytestLog() {
  pushUndo();
  state.playtestLog = [];
  renderAll("Playtest log cleared.");
}
function advanceStoryArcForScene(sceneId) {
  const arc = state.storyArc;
  if (!arc || !Array.isArray(arc.acts)) return;
  const beatsInScene = new Set((state.storyBeats || []).filter(beat => beat.sceneId === sceneId).map(beat => beat.id));
  let changed = false;
  for (const act of arc.acts) {
    if (act.status === "locked" && (act.beatIds || []).some(id => beatsInScene.has(id))) {
      act.status = "active";
      arc.currentActId = act.id;
      changed = true;
      log(`Story act unlocked: ${act.title}`);
    }
  }
  if (changed) addPlaytestLogEntry("story-arc", `Story arc advanced in ${sceneNameById(sceneId)}.`, sceneId);
}

function revealQuest(id) { const q=state.quests.find(quest=>quest.id===id); if (q && q.status==="hidden") { q.status="active"; log(`Quest revealed: ${q.title}`); } }
function advanceQuest() { const q=state.quests.find(quest=>quest.status==="active"); if (!q) { log("No active quest to advance."); return; } pushUndo(); q.status="complete"; addPlaytestLogEntry("quest", `Completed quest: ${q.title}`, state.activeSceneId); renderAll(`Quest completed: ${q.title}`); }

function renderAssetGalleries() {
  const assets = state.assets || { palettes: [], sprites: [] };
  if (el.paletteGallery) {
    el.paletteGallery.innerHTML = (assets.palettes || []).map(palette => `<article class="asset-card"><strong>${escapeHtml(palette.name)}</strong><div class="swatch-row">${(palette.colors || []).slice(0, 8).map(color => `<span style="background:${escapeAttr(color)}"></span>`).join("")}</div><small>${palette.id === assets.activePaletteId ? "Active palette" : escapeHtml(palette.id)}</small></article>`).join("") || `<p>No palettes yet.</p>`;
  }
  if (el.spriteGallery) {
    el.spriteGallery.innerHTML = (assets.sprites || []).map(sprite => `<article class="asset-card sprite-card"><div class="sprite-mini" aria-hidden="true">${sprite.dataUrl ? `<img src="${escapeAttr(sprite.dataUrl)}" alt="" />` : (sprite.colors || []).slice(0,4).map(color => `<span style="background:${escapeAttr(color)}"></span>`).join("")}</div><div><strong>${escapeHtml(sprite.name)}</strong><small>${escapeHtml(sprite.role || "sprite")} · ${escapeHtml(sprite.note || sprite.id)}</small></div></article>`).join("") || `<p>No sprites yet.</p>`;
  }
}

