function addSceneTemplate() {
  pushUndo();
  state.sceneTemplates ||= [];
  const template = {
    id: uniqueId("template_custom", state.sceneTemplates.map(t => t.id)),
    name: "Custom Scene Template",
    kind: "custom",
    description: "A new creator-defined scene starter. Rename it, then use it as a design prompt.",
    layout: "road",
    recommendedAct: "Any Act"
  };
  state.sceneTemplates.push(template);
  renderAll("Added custom scene template.");
}


function onTemplatePanelClick(event) {
  const btn = event.target.closest?.("[data-template-id]");
  if (!btn) return;
  applySceneTemplate(btn.dataset.templateId);
}

function applySceneTemplate(templateId) {
  const template = (state.sceneTemplates || []).find(t => t.id === templateId);
  const scene = currentScene();
  if (!template || !scene) return;
  pushUndo();
  scene.map.tiles = buildTemplateTiles(template.layout || "road");
  scene.kind = template.kind || scene.kind;
  scene.name = template.name || scene.name;
  scene.playerStart = template.layout === "gate" ? {x: 4, y: 12} : template.layout === "diner" ? {x: 12, y: 13} : {x: 2, y: 12};
  state.player.sceneId = scene.id;
  state.player.x = scene.playerStart.x;
  state.player.y = scene.playerStart.y;
  addPlaytestLogEntry("template", `Applied scene template: ${template.name}`, scene.id);
  renderAll(`Applied template: ${template.name}`);
}

function buildTemplateTiles(layout) {
  const t = blankTiles(layout === "dream" ? "dream" : layout === "gate" ? "mountain" : "grass");
  if (layout === "diner") {
    rect(t, 2, 2, 21, 14, "diner"); rect(t, 4, 4, 19, 12, "road");
    rect(t, 7, 6, 16, 7, "neon"); rect(t, 6, 10, 17, 11, "campfire");
    setTileIn(t, 12, 13, "portal"); setTileIn(t, 5, 5, "banner"); setTileIn(t, 19, 5, "console");
  } else if (layout === "dream") {
    rect(t, 2, 2, 21, 13, "starpath"); rect(t, 5, 4, 18, 11, "dream");
    [6, 10, 14, 18].forEach(x => setTileIn(t, x, 5, "crystal"));
    setTileIn(t, 12, 12, "portal"); setTileIn(t, 12, 7, "shrine"); setTileIn(t, 4, 11, "artifact");
  } else if (layout === "gate") {
    rect(t, 0, 10, 23, 15, "grass"); rect(t, 2, 12, 21, 13, "road"); rect(t, 8, 3, 15, 10, "pyramid");
    rect(t, 10, 8, 13, 10, "lab"); setTileIn(t, 11, 11, "portal"); setTileIn(t, 12, 11, "portal");
    setTileIn(t, 5, 11, "banner"); setTileIn(t, 18, 11, "console"); setTileIn(t, 3, 12, "starpath");
  } else {
    for (let x = 0; x < 22; x++) setTileIn(t, x, 12, "road");
    for (let y = 5; y <= 12; y++) setTileIn(t, 8, y, "road");
    for (let x = 8; x < 20; x++) setTileIn(t, x, 5, "road");
    for (let x = 0; x < MAP_W; x += 2) setTileIn(t, x, 2, "forest");
    setTileIn(t, 3, 11, "campfire"); setTileIn(t, 7, 12, "bridge"); setTileIn(t, 12, 5, "banner"); setTileIn(t, 18, 5, "starpath"); setTileIn(t, 21, 5, "portal");
  }
  return t;
}

