function onAudioCueBoardClick(event) {
  const btn = event.target.closest?.("[data-audio-cue-id]");
  if (!btn) return;
  const cue = (state.audioCues || []).find(c => c.id === btn.dataset.audioCueId);
  previewAudioCue(cue);
}

function previewAudioCue(cue) {
  if (!cue) return;
  try {
    const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextCtor) throw new Error("WebAudio not available");
    const audioCtx = new AudioContextCtor();
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = "square";
    osc.frequency.value = Number(cue.frequency || 660);
    gain.gain.setValueAtTime(0.001, audioCtx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.08, audioCtx.currentTime + 0.015);
    gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + Math.max(0.06, Number(cue.durationMs || 120) / 1000));
    osc.connect(gain).connect(audioCtx.destination);
    osc.start();
    osc.stop(audioCtx.currentTime + Math.max(0.08, Number(cue.durationMs || 120) / 1000));
    log(`Previewed audio cue: ${cue.name}`);
  } catch (err) {
    log(`Audio cue preview unavailable: ${cue?.name || "cue"}. ${err.message}`);
  }
}

