function normalizeCredits(credits = {}) {
  const fallback = buildDemoCredits();
  const c = credits && typeof credits === "object" && !Array.isArray(credits) ? credits : fallback;
  return {
    studio: String(c.studio || fallback.studio),
    projectLead: String(c.projectLead || fallback.projectLead),
    assistantRole: String(c.assistantRole || fallback.assistantRole),
    specialThanks: Array.isArray(c.specialThanks) ? c.specialThanks.map(String).filter(Boolean).slice(0, 24) : fallback.specialThanks,
    about: String(c.about || fallback.about),
    licenseNote: String(c.licenseNote || fallback.licenseNote),
    claimBoundary: String(c.claimBoundary || fallback.claimBoundary)
  };
}

function normalizeAudioCues(audioCues) {
  const fallback = buildDemoAudioCues();
  const list = Array.isArray(audioCues) && audioCues.length ? audioCues : fallback;
  return list.map((cue, index) => ({
    id: String(cue.id || `cue_${index + 1}`),
    name: String(cue.name || `Cue ${index + 1}`),
    kind: String(cue.kind || "ui"),
    mood: String(cue.mood || "neutral"),
    note: String(cue.note || "Audio cue note."),
    frequency: clamp(parseInt(cue.frequency, 10) || 660, 80, 2000),
    durationMs: clamp(parseInt(cue.durationMs, 10) || 120, 40, 1200)
  })).slice(0, 32);
}

function normalizeAlphaAudit(alphaAudit = {}) {
  const fallback = buildDemoAlphaAudit();
  const a = alphaAudit && typeof alphaAudit === "object" && !Array.isArray(alphaAudit) ? alphaAudit : fallback;
  const checks = Array.isArray(a.checks) && a.checks.length ? a.checks : fallback.checks;
  return {
    auditType: String(a.auditType || fallback.auditType),
    targetVersion: String(a.targetVersion || fallback.targetVersion),
    status: String(a.status || fallback.status),
    notes: String(a.notes || fallback.notes),
    checks: checks.map((check, index) => ({
      id: String(check.id || `audit_${index + 1}`),
      label: String(check.label || `Audit check ${index + 1}`),
      passed: Boolean(check.passed),
      severity: ["blocker", "major", "minor"].includes(check.severity) ? check.severity : "minor"
    })).slice(0, 32)
  };
}

function validateCreditsBrowser(credits, errors) {
  if (!credits || typeof credits !== "object" || Array.isArray(credits)) { errors.push("credits must be an object."); return; }
  ["studio", "projectLead", "about", "claimBoundary"].forEach(key => { if (!credits[key]) errors.push(`credits.${key} is required.`); });
  if (!Array.isArray(credits.specialThanks)) errors.push("credits.specialThanks must be an array.");
}

function validateAudioCuesBrowser(audioCues, errors) {
  if (!Array.isArray(audioCues) || !audioCues.length) { errors.push("audioCues must be a non-empty array."); return; }
  const ids = new Set();
  audioCues.forEach((cue, index) => {
    if (!cue.id) errors.push(`audioCues[${index}].id required.`);
    if (cue.id && ids.has(cue.id)) errors.push(`duplicate audio cue id '${cue.id}'.`);
    if (cue.id) ids.add(cue.id);
    if (!cue.name) errors.push(`audioCues[${index}].name required.`);
    if (!Number.isInteger(cue.frequency) || cue.frequency < 80 || cue.frequency > 2000) errors.push(`audioCues[${index}].frequency must be 80..2000.`);
    if (!Number.isInteger(cue.durationMs) || cue.durationMs < 40 || cue.durationMs > 1200) errors.push(`audioCues[${index}].durationMs must be 40..1200.`);
  });
}

function validateAlphaAuditBrowser(alphaAudit, errors) {
  if (!alphaAudit || typeof alphaAudit !== "object" || Array.isArray(alphaAudit)) { errors.push("alphaAudit must be an object."); return; }
  if (!alphaAudit.auditType) errors.push("alphaAudit.auditType is required.");
  if (!Array.isArray(alphaAudit.checks) || !alphaAudit.checks.length) { errors.push("alphaAudit.checks must be a non-empty array."); return; }
  alphaAudit.checks.forEach((check, index) => {
    if (!check.id) errors.push(`alphaAudit.checks[${index}].id required.`);
    if (!check.label) errors.push(`alphaAudit.checks[${index}].label required.`);
    if (typeof check.passed !== "boolean") errors.push(`alphaAudit.checks[${index}].passed must be boolean.`);
    if (!["blocker", "major", "minor"].includes(check.severity)) errors.push(`alphaAudit.checks[${index}].severity must be blocker, major, or minor.`);
  });
}


