function normalizeSceneThumbnailsV1(sceneThumbnails, scenes = []) {
  const source = Array.isArray(sceneThumbnails) && sceneThumbnails.length ? sceneThumbnails : buildDemoSceneThumbnails();
  const sceneIds = new Set((scenes || []).map(scene => scene.id));
  const byScene = new Map(source.map(th => [String(th.sceneId || ""), th]));
  const fromScenes = (scenes || []).map(scene => {
    const th = byScene.get(scene.id) || {};
    return {
      sceneId: scene.id,
      label: String(th.label || scene.name || scene.id),
      caption: String(th.caption || `${scene.name || scene.id} thumbnail placeholder.`),
      reviewStatus: ["needs-review", "needs-polish", "needs-playtest", "approved"].includes(th.reviewStatus) ? th.reviewStatus : "needs-review"
    };
  });
  return fromScenes.length ? fromScenes : source.filter(th => sceneIds.has(th.sceneId)).map(th => ({
    sceneId: String(th.sceneId),
    label: String(th.label || th.sceneId),
    caption: String(th.caption || "Thumbnail placeholder."),
    reviewStatus: ["needs-review", "needs-polish", "needs-playtest", "approved"].includes(th.reviewStatus) ? th.reviewStatus : "needs-review"
  }));
}

function normalizeReleaseCandidate(releaseCandidate = {}) {
  const fallback = buildDemoReleaseCandidate();
  const c = releaseCandidate && typeof releaseCandidate === "object" && !Array.isArray(releaseCandidate) ? releaseCandidate : fallback;
  const checklist = Array.isArray(c.checklist) && c.checklist.length ? c.checklist : fallback.checklist;
  const exports = Array.isArray(c.requiredExports) && c.requiredExports.length ? c.requiredExports : fallback.requiredExports;
  return {
    candidateType: String(c.candidateType || fallback.candidateType),
    targetVersion: String(c.targetVersion || ENGINE_VERSION),
    status: ["draft", "alpha-candidate", "ready-for-review"].includes(c.status) ? c.status : "alpha-candidate",
    handoffNotes: String(c.handoffNotes || fallback.handoffNotes),
    requiredExports: exports.map(String).filter(Boolean).slice(0, 24),
    checklist: checklist.map((item, index) => ({
      id: String(item.id || `v1_check_${index + 1}`),
      label: String(item.label || `v1 checklist item ${index + 1}`),
      done: Boolean(item.done)
    })).slice(0, 32)
  };
}

function validateSceneThumbnailsV1(sceneThumbnails, sceneIds, errors) {
  if (!Array.isArray(sceneThumbnails) || !sceneThumbnails.length) { errors.push("sceneThumbnails must be a non-empty array."); return; }
  sceneThumbnails.forEach((th, index) => {
    if (!th.sceneId) errors.push(`sceneThumbnails[${index}].sceneId required.`);
    if (th.sceneId && !sceneIds.has(th.sceneId)) errors.push(`sceneThumbnails[${index}].sceneId references missing scene '${th.sceneId}'.`);
    if (!th.label) errors.push(`sceneThumbnails[${index}].label required.`);
    if (!th.caption) errors.push(`sceneThumbnails[${index}].caption required.`);
    if (!["needs-review", "needs-polish", "needs-playtest", "approved"].includes(th.reviewStatus)) errors.push(`sceneThumbnails[${index}].reviewStatus invalid.`);
  });
}

function validateReleaseCandidateV1(releaseCandidate, errors) {
  if (!releaseCandidate || typeof releaseCandidate !== "object" || Array.isArray(releaseCandidate)) { errors.push("releaseCandidate must be an object."); return; }
  if (!releaseCandidate.candidateType) errors.push("releaseCandidate.candidateType is required.");
  if (!releaseCandidate.targetVersion) errors.push("releaseCandidate.targetVersion is required.");
  if (!Array.isArray(releaseCandidate.requiredExports) || !releaseCandidate.requiredExports.length) errors.push("releaseCandidate.requiredExports must be a non-empty array.");
  if (!Array.isArray(releaseCandidate.checklist) || !releaseCandidate.checklist.length) { errors.push("releaseCandidate.checklist must be a non-empty array."); return; }
  releaseCandidate.checklist.forEach((item, index) => {
    if (!item.id) errors.push(`releaseCandidate.checklist[${index}].id required.`);
    if (!item.label) errors.push(`releaseCandidate.checklist[${index}].label required.`);
    if (typeof item.done !== "boolean") errors.push(`releaseCandidate.checklist[${index}].done must be boolean.`);
  });
}


