function applyActiveAssetPack() {
  const pack = activeAssetPack();
  if (!pack) { log("No asset pack available to apply."); return; }
  pushUndo();
  const paletteId = pack.paletteIds.find(id => state.assets?.palettes?.some(p => p.id === id));
  if (paletteId) state.assets.activePaletteId = paletteId;
  const templateId = pack.templateIds.find(id => state.sceneTemplates?.some(t => t.id === id));
  if (templateId) {
    const template = state.sceneTemplates.find(t => t.id === templateId);
    if (template) currentScene().kind = template.kind || currentScene().kind;
  }
  addPlaytestLogEntry("asset-pack", `Applied asset pack: ${pack.name}`, state.activeSceneId);
  renderAll(`Applied asset pack: ${pack.name}.`);
}

async function exportActiveAssetPack() {
  const pack = activeAssetPack();
  if (!pack) { log("No active asset pack to export."); return; }
  const hash = await sha256(stableStringify(pack));
  const payload = {
    packType: "pixelforge.asset-pack",
    packVersion: ENGINE_VERSION,
    exportedAt: new Date().toISOString(),
    projectTitle: state.meta.title,
    packHash: hash,
    pack,
    palettes: (state.assets?.palettes || []).filter(p => pack.paletteIds.includes(p.id)),
    sprites: (state.assets?.sprites || []).filter(s => pack.spriteIds.includes(s.id)),
    templates: (state.sceneTemplates || []).filter(t => pack.templateIds.includes(t.id)),
    claimBoundary: state.meta.claimBoundary
  };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(pack.name)}.asset-pack.v3.2.json`);
  log(`Exported asset pack: ${pack.name}.`);
}


