function tilesForWizardLayout(layout, pack) {
  const primary = pack?.tileIds?.[0] || "grass";
  const secondary = pack?.tileIds?.[1] || "road";
  const accent = pack?.tileIds?.[2] || "sign";
  const t = blankTiles(primary);
  if (layout === "diner") {
    rect(t, 1, 1, 22, 14, "diner"); rect(t, 4, 4, 19, 11, secondary); rect(t, 7, 6, 16, 8, "workshop");
    setTileIn(t, 5, 5, "kiosk"); setTileIn(t, 18, 5, "console"); setTileIn(t, 12, 12, "neon");
  } else if (layout === "dream") {
    rect(t, 2, 2, 21, 13, "dream"); rect(t, 10, 4, 14, 11, "starpath");
    setTileIn(t, 12, 8, "moonwell"); setTileIn(t, 8, 8, "crystal"); setTileIn(t, 16, 8, "glyph"); setTileIn(t, 12, 12, "portal");
  } else if (layout === "gate") {
    rect(t, 0, 10, 23, 15, "road"); rect(t, 9, 3, 14, 10, "pyramid");
    setTileIn(t, 11, 11, "checkpoint"); setTileIn(t, 12, 11, "portal"); setTileIn(t, 7, 12, "console"); setTileIn(t, 17, 12, "glyph");
  } else {
    for (let x = 0; x < MAP_W; x++) setTileIn(t, x, 12, "road");
    for (let y = 6; y <= 12; y++) setTileIn(t, 12, y, "road");
    setTileIn(t, 10, 12, "busstop"); setTileIn(t, 8, 11, "payphone"); setTileIn(t, 14, 10, accent); setTileIn(t, 18, 12, "trailmarker");
  }
  return t;
}

function generateSceneFromWizard() {
  state.sceneWizard = normalizeSceneWizard(state.sceneWizard);
  const preset = activeSceneWizardPreset();
  const pack = (state.assetPacks || []).find(p => p.id === preset.assetPackId) || activeAssetPack();
  const sourceScene = currentScene();
  pushUndo();
  state.sceneWizard.generatedCount = (state.sceneWizard.generatedCount || 0) + 1;
  const sceneId = uniqueId(`scene_${preset.id}`, state.scenes.map(scene => scene.id));
  const tiles = tilesForWizardLayout(preset.layout, pack);
  const scene = makeScene(sceneId, `${preset.name} ${state.sceneWizard.generatedCount}`, preset.kind, tiles, { x: 12, y: 12 }, [
    { id: uniqueId(`npc_${preset.id}`, []), name: preset.defaultNpcName, role: "Wizard Seed NPC", x: 12, y: 9, color: "#f8f2de", dialogue: [`${preset.name} loaded from the Scene Wizard.`, "Edit me into someone memorable."], effect: { wonder: 1 } }
  ], [
    { id: uniqueId(`item_${preset.id}`, []), name: preset.defaultItemName, type: "wizard-seed", x: 14, y: 12, color: "#61f0ff", collected: false, effect: { morale: 1, coherence: 1 } }
  ], [
    { id: uniqueId(`warp_back_${sourceScene.id}`, []), name: `Back to ${sourceScene.name}`, x: 12, y: 15, targetSceneId: sourceScene.id, targetX: sourceScene.playerStart?.x || 2, targetY: sourceScene.playerStart?.y || 12, color: "#ffd36e" }
  ]);
  state.scenes.push(scene);
  state.activeSceneId = scene.id;
  state.player.sceneId = scene.id;
  state.player.x = scene.playerStart.x;
  state.player.y = scene.playerStart.y;
  if (pack?.id) state.activeAssetPackId = pack.id;
  addPlaytestLogEntry("scene-wizard", `Generated scene '${scene.name}' from preset '${preset.name}'.`, scene.id);
  renderAll(`Generated scene from Scene Wizard: ${scene.name}.`);
}

function normalizeSceneWizard(sceneWizard = {}) {
  const fallback = buildDemoSceneWizard();
  const source = sceneWizard && typeof sceneWizard === "object" && !Array.isArray(sceneWizard) ? sceneWizard : fallback;
  const presets = Array.isArray(source.presets) && source.presets.length ? source.presets : fallback.presets;
  const normalized = presets.map((preset, index) => ({
    id: String(preset.id || `preset_${index + 1}`),
    name: String(preset.name || `Scene Preset ${index + 1}`),
    layout: ["road", "diner", "dream", "gate"].includes(preset.layout) ? preset.layout : "road",
    kind: String(preset.kind || "scene"),
    templateId: String(preset.templateId || ""),
    assetPackId: String(preset.assetPackId || ""),
    description: String(preset.description || "Scene wizard preset."),
    defaultNpcName: String(preset.defaultNpcName || "Wizard NPC"),
    defaultItemName: String(preset.defaultItemName || "Wizard Item")
  })).slice(0, 24);
  return {
    activePresetId: normalized.some(preset => preset.id === source.activePresetId) ? String(source.activePresetId) : normalized[0]?.id || "",
    generatedCount: clamp(parseInt(source.generatedCount, 10) || 0, 0, 999),
    presets: normalized
  };
}

