function applyActiveQuickStamp() {
  const stamp = activeQuickStamp();
  if (!stamp) { log("No quick stamp available."); return; }
  const scene = currentScene();
  pushUndo();
  const cx = clamp(state.player.x || 12, 1, MAP_W - 2);
  const cy = clamp(state.player.y || 8, 1, MAP_H - 2);
  let i = 0;
  for (let dy = -1; dy <= 1; dy++) {
    for (let dx = -1; dx <= 1; dx++) {
      const tile = stamp.tileIds[i++] || stamp.tileIds[0] || "grass";
      setTileIn(scene.map.tiles, cx + dx, cy + dy, tile);
    }
  }
  addPlaytestLogEntry("quick-stamp", `Applied quick stamp '${stamp.name}' at ${cx},${cy}.`, scene.id);
  renderAll(`Applied Quick Stamp: ${stamp.name}.`);
}

