  el.creatorPromptDeckPanel.innerHTML = state.creatorPromptDeck.prompts.map(prompt => `<article class="prompt-card ${prompt.id === state.activeCreatorPromptId ? "active" : ""}"><small>${escapeHtml(prompt.kind)}</small><strong>${prompt.id === state.activeCreatorPromptId ? "★ " : ""}${escapeHtml(prompt.title)}</strong><p>${escapeHtml(prompt.text)}</p><p><em>${escapeHtml(prompt.outputHint)}</em></p></article>`).join("");
