function normalizeChiptuneStudio(chiptuneStudio = {}) {
  const fallback = buildDemoChiptuneStudio();
  const source = chiptuneStudio && typeof chiptuneStudio === "object" && !Array.isArray(chiptuneStudio) ? chiptuneStudio : fallback;
  const presetsSource = Array.isArray(source.presets) && source.presets.length ? source.presets : fallback.presets;
  const presets = presetsSource.map((preset, index) => ({
    id: String(preset.id || `chiptune_preset_${index + 1}`),
    name: String(preset.name || `Retro Preset ${index + 1}`),
    targetStyle: ["8-bit", "16-bit", "hybrid"].includes(preset.targetStyle) ? preset.targetStyle : "8-bit",
    waveform: ["square", "triangle", "sawtooth", "sine"].includes(preset.waveform) ? preset.waveform : "square",
    bitDepth: clamp(parseInt(preset.bitDepth, 10) || 8, 4, 16),
    sampleRate: clamp(parseInt(preset.sampleRate, 10) || 11025, 8000, 48000),
    channels: clamp(parseInt(preset.channels, 10) || 1, 1, 2),
    defaultBpm: clamp(parseInt(preset.defaultBpm, 10) || 120, 40, 220),
    note: String(preset.note || "Retro audio conversion preset.")
  })).slice(0, 16);
  const tracks = Array.isArray(source.importedTracks) ? source.importedTracks.map((track, index) => ({
    id: String(track.id || `track_${index + 1}`),
    name: String(track.name || `Imported Track ${index + 1}`),
    sourceName: String(track.sourceName || "unknown-audio"),
    durationSec: Math.round(Number(track.durationSec || 0)),
    sampleRate: clamp(parseInt(track.sampleRate, 10) || 44100, 8000, 192000),
    channels: clamp(parseInt(track.channels, 10) || 1, 1, 8),
    presetId: presets.some(p => p.id === track.presetId) ? String(track.presetId) : presets[0]?.id || "",
    status: ["seed", "imported", "analyzed", "converted", "exported"].includes(track.status) ? track.status : "imported",
    rightsNote: String(track.rightsNote || "Use music you own, created, or have permission to transform.")
  })).slice(-24) : [];
  const outputs = Array.isArray(source.retroOutputs) ? source.retroOutputs.map((output, index) => ({
    id: String(output.id || `retro_output_${index + 1}`),
    trackId: String(output.trackId || tracks[0]?.id || ""),
    name: String(output.name || `Retro Output ${index + 1}`),
    targetStyle: ["8-bit", "16-bit", "hybrid"].includes(output.targetStyle) ? output.targetStyle : presets[0]?.targetStyle || "8-bit",
    bpm: clamp(parseInt(output.bpm, 10) || presets[0]?.defaultBpm || 120, 40, 220),
    keyHint: String(output.keyHint || "unknown / by ear"),
    outputKind: ["cue", "loop-manifest", "arrangement", "stem-plan"].includes(output.outputKind) ? output.outputKind : "loop-manifest",
    status: ["draft", "review", "approved", "exported"].includes(output.status) ? output.status : "draft",
    cueId: String(output.cueId || ""),
    notes: String(output.notes || "Retro conversion notes pending.")
  })).slice(-32) : [];
  const sketches = Array.isArray(source.arrangementSketches) ? source.arrangementSketches.map((sketch, index) => ({
    id: String(sketch.id || `arrangement_${index + 1}`),
    name: String(sketch.name || `Arrangement ${index + 1}`),
    bars: clamp(parseInt(sketch.bars, 10) || 4, 1, 64),
    parts: Array.isArray(sketch.parts) ? sketch.parts.map(String).filter(Boolean).slice(0, 12) : [],
    loopable: Boolean(sketch.loopable)
  })).slice(-24) : [];
  const last = source.lastAnalysis && typeof source.lastAnalysis === "object" && !Array.isArray(source.lastAnalysis) ? source.lastAnalysis : fallback.lastAnalysis;
  return {
    studioType: String(source.studioType || fallback.studioType),
    activePresetId: presets.some(preset => preset.id === source.activePresetId) ? String(source.activePresetId) : presets[0]?.id || "",
    presets,
    importedTracks: tracks,
    retroOutputs: outputs,
    arrangementSketches: sketches,
    lastAnalysis: {
      trackId: String(last?.trackId || tracks[0]?.id || ""),
      summary: String(last?.summary || "Import an audio file to analyze it locally."),
      estimatedBpm: clamp(parseInt(last?.estimatedBpm, 10) || presets[0]?.defaultBpm || 120, 40, 220),
      energy: String(last?.energy || "unknown"),
      suggestedUse: String(last?.suggestedUse || "game loop / cue")
    }
  };
}

function activeChiptunePreset() {
  state.chiptuneStudio = normalizeChiptuneStudio(state.chiptuneStudio);
  return state.chiptuneStudio.presets.find(preset => preset.id === state.chiptuneStudio.activePresetId) || state.chiptuneStudio.presets[0];
}

