let selectedAudioForChiptuneStudio = null;
function onMusicInputChange(event) {
  selectedAudioForChiptuneStudio = event.target.files?.[0] || null;
  if (selectedAudioForChiptuneStudio) log(`Selected music for Chiptune Studio: ${selectedAudioForChiptuneStudio.name}.`);
}

async function analyzeSelectedMusic() {
  if (!selectedAudioForChiptuneStudio) { log("Choose an audio file first, then analyze it."); return; }
  const preset = activeChiptunePreset();
  try {
    const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
    if (!AudioContextCtor) throw new Error("WebAudio decode is not available in this browser.");
    const audioCtx = new AudioContextCtor();
    const buffer = await selectedAudioForChiptuneStudio.arrayBuffer();
    const decoded = await audioCtx.decodeAudioData(buffer.slice(0));
    pushUndo();
    state.chiptuneStudio = normalizeChiptuneStudio(state.chiptuneStudio);
    const durationSec = Math.round(decoded.duration || 0);
    const estimatedBpm = clamp(Math.round((preset.defaultBpm + (durationSec % 32)) / 2 + 32), 60, 180);
    const energy = decoded.numberOfChannels > 1 && decoded.duration > 60 ? "medium-high" : decoded.duration < 30 ? "short-cue" : "medium";
    const track = {
      id: uniqueId("audio_track", state.chiptuneStudio.importedTracks.map(track => track.id)),
      name: selectedAudioForChiptuneStudio.name.replace(/\.[^.]+$/, "") || "Imported Music",
      sourceName: selectedAudioForChiptuneStudio.name,
      durationSec,
      sampleRate: decoded.sampleRate,
      channels: decoded.numberOfChannels,
      presetId: preset.id,
      status: "analyzed",
      rightsNote: "Use music you own, created, or have permission to transform."
    };
    state.chiptuneStudio.importedTracks.push(track);
    state.chiptuneStudio.importedTracks = state.chiptuneStudio.importedTracks.slice(-24);
    state.chiptuneStudio.lastAnalysis = { trackId: track.id, summary: `${track.name}: ${durationSec}s, ${decoded.numberOfChannels}ch, ${decoded.sampleRate}Hz. Suggested ${preset.targetStyle} conversion via ${preset.name}.`, estimatedBpm, energy, suggestedUse: preset.targetStyle === "16-bit" ? "scene loop / emotional theme" : "UI cue / overworld motif" };
    try { await audioCtx.close(); } catch {}
    addPlaytestLogEntry("chiptune-studio", `Analyzed music reference: ${track.name}.`, state.activeSceneId);
    renderAll(`Analyzed music for Chiptune Studio: ${track.name}.`);
  } catch (err) {
    log(`Music analysis failed: ${err.message}`);
  }
}

function generateRetroCue() {
  pushUndo();
  state.chiptuneStudio = normalizeChiptuneStudio(state.chiptuneStudio);
  const preset = activeChiptunePreset();
  const track = state.chiptuneStudio.importedTracks.at(-1) || state.chiptuneStudio.importedTracks[0];
  const bpm = state.chiptuneStudio.lastAnalysis?.estimatedBpm || preset.defaultBpm;
  const outputId = uniqueId("retro_output", state.chiptuneStudio.retroOutputs.map(output => output.id));
  const cueId = uniqueId("cue_chiptune", (state.audioCues || []).map(cue => cue.id));
  const frequency = preset.waveform === "triangle" ? 392 : preset.waveform === "sawtooth" ? 330 : 660;
  const durationMs = clamp(Math.round(60000 / bpm), 80, 900);
  const cue = { id: cueId, name: `${track?.name || "Imported Music"} ${preset.targetStyle} Cue`, kind: "music", mood: preset.targetStyle === "16-bit" ? "warm-retro" : "bright-retro", note: `Generated from Chiptune Studio preset ${preset.name}; use as a placeholder cue until full loop rendering is added.`, frequency, durationMs };
  state.audioCues = normalizeAudioCues([...(state.audioCues || []), cue]);
  const output = { id: outputId, trackId: track?.id || "", name: `${track?.name || "Music"} — ${preset.name}`, targetStyle: preset.targetStyle, bpm, keyHint: preset.targetStyle === "16-bit" ? "minor / heartfelt" : "major / quirky", outputKind: "loop-manifest", status: "draft", cueId, notes: `Reduce to ${preset.bitDepth}-bit character, ${preset.sampleRate}Hz target, ${preset.channels} channel(s), ${preset.waveform}-wave lead. Keep the core melody/hook, simplify harmony, and make an 8-bar loop.` };
  state.chiptuneStudio.retroOutputs.push(output);
  state.chiptuneStudio.retroOutputs = state.chiptuneStudio.retroOutputs.slice(-32);
  state.chiptuneStudio.arrangementSketches.push({ id: uniqueId("arrangement", state.chiptuneStudio.arrangementSketches.map(a => a.id)), name: `${output.name} Arrangement`, bars: 8, parts: [`${preset.waveform} lead`, "pulse bass", "noise percussion", "counter-melody sparkle"], loopable: true });
  addPlaytestLogEntry("chiptune-studio", `Generated retro cue: ${output.name}.`, state.activeSceneId);
  renderAll(`Generated Chiptune Studio output: ${output.name}.`);
}

function previewChiptuneOutput() {
  state.chiptuneStudio = normalizeChiptuneStudio(state.chiptuneStudio);
  const preset = activeChiptunePreset();
  const output = state.chiptuneStudio.retroOutputs.at(-1);
  const cue = output?.cueId ? (state.audioCues || []).find(c => c.id === output.cueId) : null;
  previewAudioCue(cue || { name: preset.name, frequency: preset.waveform === "triangle" ? 392 : preset.waveform === "sawtooth" ? 330 : 660, durationMs: 180 });
}

async function exportChiptuneStudio() {
  state.chiptuneStudio = normalizeChiptuneStudio(state.chiptuneStudio);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.chiptune-studio.manifest", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, chiptuneStudio: state.chiptuneStudio, audioCues: state.audioCues, claimBoundary: "Creative audio tooling only. Use music you own, created, or have permission to transform." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.chiptune-studio.v3.2.json`);
  log("Exported Chiptune Studio manifest JSON.");
}



