function normalizeCreativeSuite(creativeSuite = {}) {
  const fallback = buildDemoCreativeSuite();
  const source = creativeSuite && typeof creativeSuite === "object" && !Array.isArray(creativeSuite) ? creativeSuite : fallback;
  const tracks = Array.isArray(source.tracks) && source.tracks.length ? source.tracks.map((track, index) => ({
    id: String(track.id || `suite_track_${index + 1}`),
    name: String(track.name || `Suite Track ${index + 1}`),
    domain: ["pixel", "writers", "chiptune", "release", "suite"].includes(track.domain) ? track.domain : "suite",
    status: ["draft", "planned", "active", "ready", "review", "blocked"].includes(track.status) ? track.status : "draft",
    summary: String(track.summary || "Creative-suite track summary pending.")
  })).slice(0, 16) : fallback.tracks;
  const loops = Array.isArray(source.openLoops) ? source.openLoops.map((loop, index) => ({
    id: String(loop.id || `suite_loop_${index + 1}`),
    title: String(loop.title || `Open Loop ${index + 1}`),
    status: ["future", "planned", "active", "done"].includes(loop.status) ? loop.status : "planned",
    owner: String(loop.owner || "PixelForge"),
    note: String(loop.note || "Follow-up needed.")
  })).slice(-24) : fallback.openLoops;
  return {
    suiteType: String(source.suiteType || fallback.suiteType),
    activeTrackId: tracks.some(track => track.id === source.activeTrackId) ? String(source.activeTrackId) : tracks[0]?.id || "",
    readinessScore: clamp(parseInt(source.readinessScore, 10) || fallback.readinessScore, 0, 100),
    lastSync: String(source.lastSync || fallback.lastSync),
    tracks,
    openLoops: loops,
    handoffRecipe: String(source.handoffRecipe || fallback.handoffRecipe)
  };
}

function normalizeGameKitComposer(gameKitComposer = {}) {
  const fallback = buildDemoGameKitComposer();
  const source = gameKitComposer && typeof gameKitComposer === "object" && !Array.isArray(gameKitComposer) ? gameKitComposer : fallback;
  const kits = Array.isArray(source.kits) && source.kits.length ? source.kits.map((kit, index) => ({
    id: String(kit.id || `game_kit_${index + 1}`),
    name: String(kit.name || `Game Kit ${index + 1}`),
    themeId: String(kit.themeId || ""),
    assetPackId: String(kit.assetPackId || ""),
    sceneWizardPresetId: String(kit.sceneWizardPresetId || ""),
    writerRoleId: String(kit.writerRoleId || ""),
    chiptunePresetId: String(kit.chiptunePresetId || ""),
    exportProfileId: String(kit.exportProfileId || ""),
    status: ["draft", "active", "ready", "archived"].includes(kit.status) ? kit.status : "draft",
    summary: String(kit.summary || "Game kit summary pending.")
  })).slice(0, 16) : fallback.kits;
  const generated = Array.isArray(source.generatedKits) ? source.generatedKits.map((kit, index) => ({
    id: String(kit.id || `generated_kit_${index + 1}`),
    sourceKitId: String(kit.sourceKitId || kits[0]?.id || ""),
    name: String(kit.name || `Generated Kit ${index + 1}`),
    generatedAt: String(kit.generatedAt || "imported"),
    includes: Array.isArray(kit.includes) ? kit.includes.map(String).filter(Boolean).slice(0, 20) : [],
    status: ["draft", "ready", "exported"].includes(kit.status) ? kit.status : "draft"
  })).slice(-24) : fallback.generatedKits;
  return {
    activeKitId: kits.some(kit => kit.id === source.activeKitId) ? String(source.activeKitId) : kits[0]?.id || "",
    kits,
    generatedKits: generated,
    lastGeneratedAt: String(source.lastGeneratedAt || fallback.lastGeneratedAt)
  };
}

function normalizeSceneAudioBoard(sceneAudioBoard = {}, scenes = [], cues = []) {
  const fallback = buildDemoSceneAudioBoard();
  const source = sceneAudioBoard && typeof sceneAudioBoard === "object" && !Array.isArray(sceneAudioBoard) ? sceneAudioBoard : fallback;
  const sceneIds = new Set((scenes || []).map(scene => scene.id));
  const cueIds = new Set((cues || []).map(cue => cue.id));
  const firstScene = scenes[0]?.id || "scene_roadside";
  const firstCue = cues[0]?.id || "cue_shasta_road_loop";
  const assignments = Array.isArray(source.assignments) ? source.assignments.map((assignment, index) => ({
    id: String(assignment.id || `scene_audio_${index + 1}`),
    sceneId: sceneIds.has(assignment.sceneId) ? String(assignment.sceneId) : firstScene,
    cueId: cueIds.has(assignment.cueId) ? String(assignment.cueId) : firstCue,
    chiptuneOutputId: String(assignment.chiptuneOutputId || ""),
    trigger: ["scene-enter", "encounter", "warp", "title-screen", "manual"].includes(assignment.trigger) ? assignment.trigger : "scene-enter",
    volume: Math.max(0, Math.min(1, Number(assignment.volume ?? 0.7))),
    loop: Boolean(assignment.loop),
    status: ["planned", "draft", "approved", "exported"].includes(assignment.status) ? assignment.status : "draft",
    note: String(assignment.note || "Scene audio assignment note pending.")
  })).slice(-32) : fallback.assignments;
  const notes = Array.isArray(source.mixNotes) ? source.mixNotes.map((note, index) => ({
    id: String(note.id || `mix_note_${index + 1}`),
    target: String(note.target || "scene"),
    note: String(note.note || "Mix note pending.")
  })).slice(-24) : fallback.mixNotes;
  return {
    activeAssignmentId: assignments.some(a => a.id === source.activeAssignmentId) ? String(source.activeAssignmentId) : assignments[0]?.id || "",
    assignments,
    mixNotes: notes
  };
}

function renderCreativeSuitePanel() {
  if (!el.creativeSuitePanel) return;
  state.creativeSuite = normalizeCreativeSuite(state.creativeSuite);
  const active = state.creativeSuite.tracks.find(track => track.id === state.creativeSuite.activeTrackId) || state.creativeSuite.tracks[0];
  const chips = state.creativeSuite.tracks.map(track => `<span class="mini-pill">${escapeHtml(track.domain)} · ${escapeHtml(track.status)}</span>`).join("");
  el.creativeSuitePanel.innerHTML = `
    <article class="suite-card active"><small>${escapeHtml(state.creativeSuite.suiteType)}</small><strong>${escapeHtml(active?.name || "Creative Suite")}</strong><p>${escapeHtml(active?.summary || "Sync the suite to refresh readiness.")}</p><p>Readiness: <strong>${state.creativeSuite.readinessScore}%</strong> · last sync ${escapeHtml(state.creativeSuite.lastSync)}</p></article>
    <div class="mini-pill-row">${chips}</div>
    <article class="suite-card"><small>${state.creativeSuite.openLoops.length} open loop(s)</small><p>${escapeHtml(state.creativeSuite.handoffRecipe)}</p></article>
  `;
}

function renderGameKitPanel() {
  if (!el.gameKitPanel) return;
  state.gameKitComposer = normalizeGameKitComposer(state.gameKitComposer);
  const active = state.gameKitComposer.kits.find(kit => kit.id === state.gameKitComposer.activeKitId) || state.gameKitComposer.kits[0];
  const generated = state.gameKitComposer.generatedKits.at(-1);
  el.gameKitPanel.innerHTML = `
    <article class="suite-card active"><small>${escapeHtml(active?.status || "draft")}</small><strong>${escapeHtml(active?.name || "Game Kit")}</strong><p>${escapeHtml(active?.summary || "Generate a kit from the current creative-suite state.")}</p></article>
    ${generated ? `<article class="suite-card"><small>${escapeHtml(generated.status)} · ${escapeHtml(generated.generatedAt)}</small><strong>${escapeHtml(generated.name)}</strong><p>${generated.includes.map(item => escapeHtml(item)).join(" · ")}</p></article>` : ""}
  `;
}

function renderSceneAudioPanel() {
  if (!el.sceneAudioPanel) return;
  state.sceneAudioBoard = normalizeSceneAudioBoard(state.sceneAudioBoard, state.scenes, state.audioCues);
  const cards = state.sceneAudioBoard.assignments.map(assignment => {
    const scene = state.scenes.find(s => s.id === assignment.sceneId);
    const cue = (state.audioCues || []).find(c => c.id === assignment.cueId);
    return `<article class="suite-card ${assignment.id === state.sceneAudioBoard.activeAssignmentId ? "active" : ""}"><small>${escapeHtml(assignment.trigger)} · ${escapeHtml(assignment.status)} · vol ${assignment.volume.toFixed(2)}</small><strong>${escapeHtml(scene?.name || assignment.sceneId)}</strong><p>${escapeHtml(cue?.name || assignment.cueId)} ${assignment.loop ? "· loop" : ""}</p><p>${escapeHtml(assignment.note)}</p></article>`;
  }).join("");
  el.sceneAudioPanel.innerHTML = cards || `<article class="suite-card"><p>No scene audio assignments yet.</p></article>`;
}

function syncCreativeSuite() {
  pushUndo();
  state.creativeSuite = normalizeCreativeSuite(state.creativeSuite);
  const counts = {
    pixel: (state.pixelStudio?.importedAssets || []).length + (state.assetPipeline?.importedRefs || []).length,
    writers: (state.writersStudio?.generatedDrafts || []).length + (state.adventurePipeline?.pitchPacks || []).length,
    chiptune: (state.chiptuneStudio?.retroOutputs || []).length + (state.sceneAudioBoard?.assignments || []).length,
    release: (state.playableQa?.checks || []).filter(c => c.passed).length + (state.releaseDiagnostics?.checks || []).filter(c => c.passed).length
  };
  const score = clamp(55 + counts.pixel * 3 + counts.writers * 3 + counts.chiptune * 4 + counts.release * 2, 0, 100);
  state.creativeSuite.readinessScore = score;
  state.creativeSuite.lastSync = new Date().toISOString();
  state.creativeSuite.tracks = state.creativeSuite.tracks.map(track => ({ ...track, status: track.domain === "suite" ? "active" : counts[track.domain] > 0 ? "ready" : track.status }));
  addPlaytestLogEntry("creative-suite", `Synced Creative Suite readiness: ${score}%.`, state.activeSceneId);
  renderAll(`Creative Suite synced at ${score}% readiness.`);
}

function generateGameKit() {
  pushUndo();
  state.gameKitComposer = normalizeGameKitComposer(state.gameKitComposer);
  state.creativeSuite = normalizeCreativeSuite(state.creativeSuite);
  const source = state.gameKitComposer.kits.find(kit => kit.id === state.gameKitComposer.activeKitId) || state.gameKitComposer.kits[0];
  const kit = {
    id: uniqueId("generated_kit", state.gameKitComposer.generatedKits.map(k => k.id)),
    sourceKitId: source?.id || "",
    name: `${source?.name || state.meta.title} Export Kit`,
    generatedAt: new Date().toISOString(),
    includes: ["title screen", "active theme", "active asset pack", "pixel assets", "writer drafts", "chiptune preset", "scene audio map", "QA checklist", "release manifest"],
    status: "ready"
  };
  state.gameKitComposer.generatedKits.push(kit);
  state.gameKitComposer.generatedKits = state.gameKitComposer.generatedKits.slice(-24);
  state.gameKitComposer.lastGeneratedAt = kit.generatedAt;
  state.creativeSuite.openLoops = state.creativeSuite.openLoops.filter(loop => loop.id !== "loop_game_kit_needed");
  addPlaytestLogEntry("game-kit", `Generated game kit: ${kit.name}.`, state.activeSceneId);
  renderAll(`Generated Game Kit: ${kit.name}.`);
}

function assignSceneAudio() {
  pushUndo();
  state.sceneAudioBoard = normalizeSceneAudioBoard(state.sceneAudioBoard, state.scenes, state.audioCues);
  const scene = currentScene();
  const output = state.chiptuneStudio?.retroOutputs?.at(-1);
  const cue = output?.cueId ? (state.audioCues || []).find(c => c.id === output.cueId) : (state.audioCues || [])[0];
  if (!scene || !cue) { log("Need at least one scene and one audio cue before assigning scene audio."); return; }
  const assignment = {
    id: uniqueId("scene_audio", state.sceneAudioBoard.assignments.map(a => a.id)),
    sceneId: scene.id,
    cueId: cue.id,
    chiptuneOutputId: output?.id || "",
    trigger: "scene-enter",
    volume: 0.7,
    loop: true,
    status: "draft",
    note: `Assigned ${cue.name} to ${scene.name} from the v3.2 Scene Audio Board.`
  };
  state.sceneAudioBoard.assignments.push(assignment);
  state.sceneAudioBoard.activeAssignmentId = assignment.id;
  addPlaytestLogEntry("scene-audio", `Assigned ${cue.name} to ${scene.name}.`, scene.id);
  renderAll(`Assigned scene audio: ${cue.name} → ${scene.name}.`);
}

