function normalizeProductionBoard(board = {}, scenes = []) {
  const fallback = buildDemoProductionBoard();
  const source = board && typeof board === "object" && !Array.isArray(board) ? board : fallback;
  const lanes = Array.isArray(source.lanes) && source.lanes.length ? source.lanes.map((lane, index) => ({
    id: String(lane.id || `lane_${index + 1}`),
    name: String(lane.name || `Lane ${index + 1}`),
    status: ["draft", "active", "review", "ready", "blocked"].includes(lane.status) ? lane.status : "draft",
    wipLimit: clamp(parseInt(lane.wipLimit, 10) || 4, 1, 12),
    summary: String(lane.summary || "Production lane summary pending.")
  })).slice(0, 8) : fallback.lanes;
  const laneIds = new Set(lanes.map(l => l.id));
  const sceneIds = new Set((scenes || []).map(s => s.id));
  const cardsSource = Array.isArray(source.cards) && source.cards.length ? source.cards : fallback.cards;
  const cards = cardsSource.map((card, index) => ({
    id: String(card.id || `prod_card_${index + 1}`),
    title: String(card.title || `Production Card ${index + 1}`),
    laneId: laneIds.has(card.laneId) ? String(card.laneId) : lanes[0]?.id || "",
    sceneId: sceneIds.has(card.sceneId) ? String(card.sceneId) : (scenes[0]?.id || ""),
    kind: ["scene", "asset", "audio", "story", "qa", "release"].includes(card.kind) ? card.kind : "scene",
    priority: ["low", "medium", "high"].includes(card.priority) ? card.priority : "medium",
    status: ["draft", "active", "review", "ready", "done", "blocked"].includes(card.status) ? card.status : "draft",
    owner: String(card.owner || "Creator"),
    acceptance: String(card.acceptance || "Acceptance criteria pending.")
  })).slice(0, 48);
  return { boardType: String(source.boardType || "pixelforge.production-board"), activeLaneId: laneIds.has(source.activeLaneId) ? String(source.activeLaneId) : lanes[0]?.id || "", updatedAt: String(source.updatedAt || "imported"), lanes, cards };
}

function normalizeReadinessMatrix(matrix = {}, scenes = []) {
  const fallback = buildDemoReadinessMatrix();
  const source = matrix && typeof matrix === "object" && !Array.isArray(matrix) ? matrix : fallback;
  const sceneIds = new Set((scenes || []).map(s => s.id));
  const statuses = ["todo", "planned", "draft", "review", "ready"];
  const releases = ["blocked", "alpha", "showcase", "release"];
  const rowsSource = Array.isArray(source.rows) && source.rows.length ? source.rows : fallback.rows;
  const rows = rowsSource.map((row, index) => ({
    id: String(row.id || `ready_row_${index + 1}`),
    sceneId: sceneIds.has(row.sceneId) ? String(row.sceneId) : (scenes[index % Math.max(scenes.length, 1)]?.id || ""),
    visual: statuses.includes(row.visual) ? row.visual : "todo",
    story: statuses.includes(row.story) ? row.story : "todo",
    audio: statuses.includes(row.audio) ? row.audio : "todo",
    qa: statuses.includes(row.qa) ? row.qa : "todo",
    release: releases.includes(row.release) ? row.release : "blocked",
    notes: String(row.notes || "Readiness notes pending.")
  })).filter(row => row.sceneId).slice(0, 64);
  const thresholds = source.thresholds && typeof source.thresholds === "object" ? source.thresholds : fallback.thresholds;
  return { matrixType: String(source.matrixType || "pixelforge.readiness-matrix"), overallScore: clamp(parseInt(source.overallScore, 10) || 0, 0, 100), lastComputed: String(source.lastComputed || "imported"), thresholds: { alpha: clamp(parseInt(thresholds.alpha, 10) || 70, 1, 100), showcase: clamp(parseInt(thresholds.showcase, 10) || 85, 1, 100), release: clamp(parseInt(thresholds.release, 10) || 95, 1, 100) }, rows };
}

function normalizeReleaseCutBuilder(builder = {}, scenes = []) {
  const fallback = buildDemoReleaseCutBuilder();
  const source = builder && typeof builder === "object" && !Array.isArray(builder) ? builder : fallback;
  const sceneIds = new Set((scenes || []).map(s => s.id));
  const cutSource = Array.isArray(source.cuts) && source.cuts.length ? source.cuts : fallback.cuts;
  const cuts = cutSource.map((cut, index) => ({
    id: String(cut.id || `cut_${index + 1}`),
    name: String(cut.name || `Release Cut ${index + 1}`),
    kind: ["alpha", "showcase", "release", "backup"].includes(cut.kind) ? cut.kind : "alpha",
    status: ["draft", "active", "ready", "shipped", "blocked"].includes(cut.status) ? cut.status : "draft",
    sceneIds: Array.isArray(cut.sceneIds) ? cut.sceneIds.map(String).filter(id => sceneIds.has(id)).slice(0, 24) : (scenes || []).map(s => s.id),
    requiredExports: Array.isArray(cut.requiredExports) ? cut.requiredExports.map(String).filter(Boolean).slice(0, 24) : [],
    readinessTarget: clamp(parseInt(cut.readinessTarget, 10) || 70, 1, 100),
    notes: String(cut.notes || "Release cut notes pending.")
  })).slice(0, 16);
  const cutIds = new Set(cuts.map(c => c.id));
  const generatedCuts = Array.isArray(source.generatedCuts) ? source.generatedCuts.map((cut, index) => ({
    id: String(cut.id || `generated_cut_${index + 1}`),
    sourceCutId: cutIds.has(cut.sourceCutId) ? String(cut.sourceCutId) : (cuts[0]?.id || ""),
    name: String(cut.name || `Generated Cut ${index + 1}`),
    generatedAt: String(cut.generatedAt || "imported"),
    exportList: Array.isArray(cut.exportList) ? cut.exportList.map(String).filter(Boolean).slice(0, 32) : [],
    status: ["draft", "ready", "shipped"].includes(cut.status) ? cut.status : "draft"
  })).slice(-32) : [];
  return { activeCutId: cutIds.has(source.activeCutId) ? String(source.activeCutId) : cuts[0]?.id || "", cuts, generatedCuts, lastBuiltAt: String(source.lastBuiltAt || "imported") };
}

function renderProductionBoardPanel() {
  if (!el.productionBoardPanel) return;
  state.productionBoard = normalizeProductionBoard(state.productionBoard, state.scenes);
  const laneCards = state.productionBoard.lanes.map(lane => {
    const cards = state.productionBoard.cards.filter(card => card.laneId === lane.id);
    const cardHtml = cards.map(card => `<div class="mini-card"><strong>${escapeHtml(card.title)}</strong><small>${escapeHtml(card.kind)} · ${escapeHtml(card.priority)} · ${escapeHtml(card.status)}</small><p>${escapeHtml(card.acceptance)}</p></div>`).join("");
    return `<article class="suite-card"><small>${escapeHtml(lane.status)} · WIP ${cards.length}/${lane.wipLimit}</small><strong>${escapeHtml(lane.name)}</strong><p>${escapeHtml(lane.summary)}</p>${cardHtml}</article>`;
  }).join("");
  el.productionBoardPanel.innerHTML = laneCards || `<article class="suite-card"><p>No production lanes yet.</p></article>`;
}

function renderReadinessMatrixPanel() {
  if (!el.readinessMatrixPanel) return;
  state.readinessMatrix = normalizeReadinessMatrix(state.readinessMatrix, state.scenes);
  const rows = state.readinessMatrix.rows.map(row => {
    const scene = state.scenes.find(s => s.id === row.sceneId);
    return `<article class="suite-card ${row.release !== "blocked" ? "active" : ""}"><small>${escapeHtml(row.release)} · visual ${escapeHtml(row.visual)} · story ${escapeHtml(row.story)} · audio ${escapeHtml(row.audio)} · QA ${escapeHtml(row.qa)}</small><strong>${escapeHtml(scene?.name || row.sceneId)}</strong><p>${escapeHtml(row.notes)}</p></article>`;
  }).join("");
  el.readinessMatrixPanel.innerHTML = `<article class="suite-card active"><small>Overall readiness</small><strong>${state.readinessMatrix.overallScore}%</strong><p>Alpha ${state.readinessMatrix.thresholds.alpha}% · Showcase ${state.readinessMatrix.thresholds.showcase}% · Release ${state.readinessMatrix.thresholds.release}%</p></article>${rows}`;
}

function renderReleaseCutPanel() {
  if (!el.releaseCutPanel) return;
  state.releaseCutBuilder = normalizeReleaseCutBuilder(state.releaseCutBuilder, state.scenes);
  const active = state.releaseCutBuilder.cuts.find(cut => cut.id === state.releaseCutBuilder.activeCutId) || state.releaseCutBuilder.cuts[0];
  const generated = state.releaseCutBuilder.generatedCuts.at(-1);
  el.releaseCutPanel.innerHTML = `
    <article class="suite-card active"><small>${escapeHtml(active?.kind || "alpha")} · target ${active?.readinessTarget || 70}%</small><strong>${escapeHtml(active?.name || "Release Cut")}</strong><p>${escapeHtml(active?.notes || "Build a named release cut.")}</p><p>${(active?.sceneIds || []).length} scene(s) · ${(active?.requiredExports || []).length} export(s)</p></article>
    <article class="suite-card"><small>Last generated</small><strong>${escapeHtml(generated?.name || "No generated cut yet")}</strong><p>${escapeHtml(generated?.status || "Generate a cut when ready.")}</p></article>`;
}

function advanceProductionCard() {
  pushUndo();
  state.productionBoard = normalizeProductionBoard(state.productionBoard, state.scenes);
  const laneOrder = state.productionBoard.lanes.map(l => l.id);
  const card = state.productionBoard.cards.find(c => c.status !== "done") || state.productionBoard.cards[0];
  if (!card) { log("No production cards to advance."); return; }
  const currentIndex = Math.max(0, laneOrder.indexOf(card.laneId));
  const nextLane = laneOrder[Math.min(currentIndex + 1, laneOrder.length - 1)];
  card.laneId = nextLane;
  card.status = nextLane === laneOrder.at(-1) ? "ready" : nextLane === "lane_qa_review" ? "review" : "active";
  state.productionBoard.updatedAt = new Date().toISOString();
  addPlaytestLogEntry("production-board", `Advanced production card: ${card.title}.`, card.sceneId || state.activeSceneId);
  renderAll(`Advanced production card: ${card.title}.`);
}

function computeReadinessMatrix() {
  pushUndo();
  const audioScenes = new Set((state.sceneAudioBoard?.assignments || []).map(a => a.sceneId));
  const storyScenes = new Set((state.storyBeats || []).map(b => b.sceneId));
  const qaSceneSet = new Set((state.demoWalkthrough?.steps || []).filter(step => step.done).map(step => step.sceneId));
  const statusScore = { todo: 0, planned: 1, draft: 2, review: 3, ready: 4 };
  const rows = state.scenes.map(scene => {
    const visual = (scene.map?.tiles || []).some(t => !["grass", "road", "forest"].includes(t)) ? "ready" : "draft";
    const story = storyScenes.has(scene.id) || (scene.npcs || []).some(n => (n.choices || []).length) ? "ready" : "draft";
    const audio = audioScenes.has(scene.id) ? "ready" : "planned";
    const qa = qaSceneSet.has(scene.id) ? "ready" : ((state.playableQa?.checks || []).some(c => c.passed) ? "review" : "todo");
    const avg = (statusScore[visual] + statusScore[story] + statusScore[audio] + statusScore[qa]) / 16;
    const release = avg >= 0.9 ? "release" : avg >= 0.75 ? "showcase" : avg >= 0.55 ? "alpha" : "blocked";
    return { id: `ready_${scene.id}`, sceneId: scene.id, visual, story, audio, qa, release, notes: `${scene.name} computed from map variety, story beats, audio assignments, and QA progress.` };
  });
  const total = rows.reduce((sum, row) => sum + statusScore[row.visual] + statusScore[row.story] + statusScore[row.audio] + statusScore[row.qa], 0);
  const overallScore = rows.length ? Math.round((total / (rows.length * 16)) * 100) : 0;
  state.readinessMatrix = { matrixType: "pixelforge.readiness-matrix", overallScore, lastComputed: new Date().toISOString(), thresholds: state.readinessMatrix?.thresholds || { alpha: 70, showcase: 85, release: 95 }, rows };
  addPlaytestLogEntry("readiness-matrix", `Computed scene readiness matrix: ${overallScore}%.`, state.activeSceneId);
  renderAll(`Computed readiness matrix: ${overallScore}%.`);
}

function buildReleaseCut() {
  pushUndo();
  state.releaseCutBuilder = normalizeReleaseCutBuilder(state.releaseCutBuilder, state.scenes);
  const source = state.releaseCutBuilder.cuts.find(cut => cut.id === state.releaseCutBuilder.activeCutId) || state.releaseCutBuilder.cuts[0];
  if (!source) { log("No release cut template available."); return; }
  const generated = {
    id: uniqueId("generated_cut", state.releaseCutBuilder.generatedCuts.map(c => c.id)),
    sourceCutId: source.id,
    name: `${source.name} ${new Date().toISOString().slice(0, 10)}`,
    generatedAt: new Date().toISOString(),
    exportList: [...new Set([...(source.requiredExports || []), "production-board", "readiness-matrix", "release-cut", "receipt"])],
    status: (state.readinessMatrix?.overallScore || 0) >= source.readinessTarget ? "ready" : "draft"
  };
  state.releaseCutBuilder.generatedCuts.push(generated);
  state.releaseCutBuilder.generatedCuts = state.releaseCutBuilder.generatedCuts.slice(-32);
  state.releaseCutBuilder.lastBuiltAt = generated.generatedAt;
  addPlaytestLogEntry("release-cut", `Built release cut: ${generated.name}.`, state.activeSceneId);
  renderAll(`Built release cut: ${generated.name}.`);
}

async function exportProductionBoard() {
  state.productionBoard = normalizeProductionBoard(state.productionBoard, state.scenes);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.production-board", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, productionBoard: state.productionBoard };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.production-board.v3.2.json`);
  log("Exported Production Board JSON.");
}

async function exportReadinessMatrix() {
  state.readinessMatrix = normalizeReadinessMatrix(state.readinessMatrix, state.scenes);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.readiness-matrix", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, readinessMatrix: state.readinessMatrix };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.readiness-matrix.v3.2.json`);
  log("Exported Readiness Matrix JSON.");
}

async function exportReleaseCut() {
  state.releaseCutBuilder = normalizeReleaseCutBuilder(state.releaseCutBuilder, state.scenes);
  const projectHash = await sha256(stableStringify(state));
  const active = state.releaseCutBuilder.cuts.find(cut => cut.id === state.releaseCutBuilder.activeCutId) || state.releaseCutBuilder.cuts[0];
  const payload = { exportType: "pixelforge.release-cut", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, activeCut: active, generatedCuts: state.releaseCutBuilder.generatedCuts, readinessMatrix: state.readinessMatrix, productionBoard: state.productionBoard };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.release-cut.v3.2.json`);
  log("Exported Release Cut JSON.");
}


