function normalizeReleaseWorkshop(workshop = {}) {
  const fallback = buildDemoReleaseWorkshop();
  const source = workshop && typeof workshop === "object" && !Array.isArray(workshop) ? workshop : fallback;
  const assembliesSource = Array.isArray(source.assemblies) && source.assemblies.length ? source.assemblies : fallback.assemblies;
  const assemblies = assembliesSource.map((assembly, index) => ({
    id: String(assembly.id || `assembly_${index + 1}`),
    name: String(assembly.name || `Release Assembly ${index + 1}`),
    kind: ["alpha", "showcase", "archive", "release"].includes(assembly.kind) ? assembly.kind : "alpha",
    status: ["draft", "assembling", "ready", "blocked"].includes(assembly.status) ? assembly.status : "draft",
    requiredPieces: Array.isArray(assembly.requiredPieces) ? assembly.requiredPieces.map(String).filter(Boolean).slice(0, 32) : [],
    notes: String(assembly.notes || "")
  })).slice(0, 32);
  return {
    workshopType: "pixelforge.release-workshop",
    activeAssemblyId: assemblies.some(assembly => assembly.id === source.activeAssemblyId) ? String(source.activeAssemblyId) : assemblies[0]?.id || "",
    status: ["draft", "assembling", "ready", "blocked"].includes(source.status) ? source.status : "draft",
    lastAssembledAt: String(source.lastAssembledAt || "never"),
    assemblies,
    assembledPackages: Array.isArray(source.assembledPackages) ? source.assembledPackages.slice(-32) : []
  };
}

function normalizeExportValidator(validator = {}) {
  const fallback = buildDemoExportValidator();
  const source = validator && typeof validator === "object" && !Array.isArray(validator) ? validator : fallback;
  const checksSource = Array.isArray(source.checks) && source.checks.length ? source.checks : fallback.checks;
  const checks = checksSource.map((check, index) => ({
    id: String(check.id || `export_check_${index + 1}`),
    label: String(check.label || `Export Check ${index + 1}`),
    exportName: String(check.exportName || "export"),
    status: ["pass", "warning", "fail"].includes(check.status) ? check.status : "warning",
    severity: ["blocker", "major", "minor"].includes(check.severity) ? check.severity : "major",
    note: String(check.note || "")
  })).slice(0, 64);
  const overallStatus = checks.some(check => check.status === "fail" && check.severity === "blocker") ? "fail" : checks.some(check => check.status === "warning" || check.status === "fail") ? "warning" : "pass";
  return { validatorType: "pixelforge.export-validator", lastRunAt: String(source.lastRunAt || "never"), overallStatus, checks };
}

function normalizeBuildNotes(buildNotes = {}) {
  const fallback = buildDemoBuildNotes();
  const source = buildNotes && typeof buildNotes === "object" && !Array.isArray(buildNotes) ? buildNotes : fallback;
  const notesSource = Array.isArray(source.notes) && source.notes.length ? source.notes : fallback.notes;
  const notes = notesSource.map((note, index) => ({
    id: String(note.id || `build_note_${index + 1}`),
    title: String(note.title || `Build Note ${index + 1}`),
    kind: ["release", "audio", "rights", "qa", "art", "story"].includes(note.kind) ? note.kind : "release",
    status: ["open", "resolved", "deferred"].includes(note.status) ? note.status : "open",
    author: String(note.author || "Creator"),
    text: String(note.text || "")
  })).slice(0, 128);
  return { notesType: "pixelforge.build-notes", activeNoteId: notes.some(note => note.id === source.activeNoteId) ? String(source.activeNoteId) : notes[0]?.id || "", notes };
}

function normalizeRightsRegistry(registry = {}) {
  const fallback = buildDemoRightsRegistry();
  const source = registry && typeof registry === "object" && !Array.isArray(registry) ? registry : fallback;
  const entriesSource = Array.isArray(source.entries) && source.entries.length ? source.entries : fallback.entries;
  const entries = entriesSource.map((entry, index) => ({
    id: String(entry.id || `rights_entry_${index + 1}`),
    title: String(entry.title || `Rights Entry ${index + 1}`),
    sourceType: ["original", "placeholder", "imported", "licensed", "public-domain"].includes(entry.sourceType) ? entry.sourceType : "placeholder",
    status: ["cleared", "review", "needs-source", "blocked"].includes(entry.status) ? entry.status : "review",
    owner: String(entry.owner || "Unknown"),
    usage: String(entry.usage || "")
  })).slice(0, 128);
  return { registryType: "pixelforge.rights-registry", activeEntryId: entries.some(entry => entry.id === source.activeEntryId) ? String(source.activeEntryId) : entries[0]?.id || "", policy: String(source.policy || fallback.policy), entries };
}


