  const checks = state.exportValidator.checks.map(check => `<article class="suite-card ${check.status === "pass" ? "active" : ""}"><small>${escapeHtml(check.status)} · ${escapeHtml(check.severity)} · ${escapeHtml(check.exportName)}</small><strong>${escapeHtml(check.label)}</strong><p>${escapeHtml(check.note)}</p></article>`).join("");
  el.exportValidatorPanel.innerHTML = `<article class="suite-card active"><small>Overall export status</small><strong>${escapeHtml(state.exportValidator.overallStatus.toUpperCase())}</strong><p>Last run: ${escapeHtml(state.exportValidator.lastRunAt)}</p></article>${checks}`;
