function assembleReleaseWorkshop() {
  pushUndo();
  state.releaseWorkshop = normalizeReleaseWorkshop(state.releaseWorkshop);
  state.exportValidator = normalizeExportValidator(state.exportValidator);
  const active = state.releaseWorkshop.assemblies.find(assembly => assembly.id === state.releaseWorkshop.activeAssemblyId) || state.releaseWorkshop.assemblies[0];
  if (!active) { log("No release assembly available."); return; }
  const packageRecord = {
    id: uniqueId("assembled_package", (state.releaseWorkshop.assembledPackages || []).map(pkg => pkg.id)),
    sourceAssemblyId: active.id,
    name: `${active.name} ${new Date().toISOString().slice(0, 10)}`,
    assembledAt: new Date().toISOString(),
    pieceCount: active.requiredPieces.length,
    exportStatus: state.exportValidator.overallStatus,
    status: state.exportValidator.overallStatus === "fail" ? "blocked" : state.exportValidator.overallStatus === "warning" ? "review" : "ready"
  };
  state.releaseWorkshop.assembledPackages.push(packageRecord);
  state.releaseWorkshop.assembledPackages = state.releaseWorkshop.assembledPackages.slice(-32);
  state.releaseWorkshop.lastAssembledAt = packageRecord.assembledAt;
  state.releaseWorkshop.status = packageRecord.status === "ready" ? "ready" : "assembling";
  addPlaytestLogEntry("release-workshop", `Assembled game shelf library package: ${packageRecord.name}.`, state.activeSceneId);
  renderAll(`Assembled release package: ${packageRecord.name}.`);
}

function runExportValidator() {
  pushUndo();
  const checks = buildDemoExportValidator().checks.map(check => ({ ...check }));
  const sceneAudioReady = (state.sceneAudioBoard?.assignments || []).length >= Math.max(1, state.scenes.length - 1);
  checks.find(c => c.id === "export_scene_audio").status = sceneAudioReady ? "pass" : "warning";
  checks.find(c => c.id === "export_scene_audio").note = sceneAudioReady ? "Scene audio assignments cover the alpha route." : "Some scenes still need assigned cues before showcase export.";
  const rights = normalizeRightsRegistry(state.rightsRegistry);
  const blockedRights = rights.entries.some(entry => entry.status === "blocked");
  const missingRights = rights.entries.some(entry => entry.status === "needs-source");
  const rightsCheck = checks.find(c => c.id === "export_rights_registry");
  rightsCheck.status = blockedRights ? "fail" : missingRights ? "warning" : "pass";
  rightsCheck.note = blockedRights ? "At least one rights entry is blocked." : missingRights ? "Imported media placeholders still need source metadata." : "Rights registry is clear for current prototype assets.";
  state.exportValidator = normalizeExportValidator({ validatorType: "pixelforge.export-validator", lastRunAt: new Date().toISOString(), checks });
  addPlaytestLogEntry("export-validator", `Ran export validator: ${state.exportValidator.overallStatus}.`, state.activeSceneId);
  renderAll(`Export validator completed: ${state.exportValidator.overallStatus}.`);
}

function addBuildNote() {
  pushUndo();
  state.buildNotes = normalizeBuildNotes(state.buildNotes);
  const id = uniqueId("build_note", state.buildNotes.notes.map(note => note.id));
  const note = { id, title: `Build Note ${state.buildNotes.notes.length + 1}`, kind: "release", status: "open", author: "Creator", text: "New release-workshop note. Add what changed, what is blocked, and what needs the next build pass." };
  state.buildNotes.notes.unshift(note);
  state.buildNotes.activeNoteId = id;
  renderAll("Added build note.");
}

