function validateAssetPipelineBrowser(assetPipeline, errors) {
  if (!assetPipeline || typeof assetPipeline !== "object" || Array.isArray(assetPipeline)) { errors.push("assetPipeline must be an object."); return; }
  if (!Array.isArray(assetPipeline.importedRefs) || assetPipeline.importedRefs.length === 0) { errors.push("assetPipeline.importedRefs must be a non-empty array."); return; }
  const ids = new Set();
  assetPipeline.importedRefs.forEach((ref, index) => {
    const label = `assetPipeline.importedRefs[${index}]`;
    if (!ref.id) errors.push(`${label}.id required.`);
    if (ref.id && ids.has(ref.id)) errors.push(`${label} duplicate ref id '${ref.id}'.`);
    if (ref.id) ids.add(ref.id);
    if (!ref.name) errors.push(`${label}.name required.`);
    if (!["character-sprite", "tile-prop", "portrait", "background", "ui-icon"].includes(ref.kind)) errors.push(`${label}.kind invalid.`);
    if (!["draft", "needs-cleanup", "ready", "exported"].includes(ref.status)) errors.push(`${label}.status invalid.`);
  });
  if (assetPipeline.activeAssetId && !ids.has(assetPipeline.activeAssetId)) errors.push("assetPipeline.activeAssetId must reference an imported ref id.");
  if (!Array.isArray(assetPipeline.cleanupQueue)) errors.push("assetPipeline.cleanupQueue must be an array.");
}

function validateAdventurePipelineBrowser(adventurePipeline, errors) {
  if (!adventurePipeline || typeof adventurePipeline !== "object" || Array.isArray(adventurePipeline)) { errors.push("adventurePipeline must be an object."); return; }
  if (!Array.isArray(adventurePipeline.pitchPacks) || adventurePipeline.pitchPacks.length === 0) { errors.push("adventurePipeline.pitchPacks must be a non-empty array."); return; }
  const ids = new Set();
  adventurePipeline.pitchPacks.forEach((pack, index) => {
    const label = `adventurePipeline.pitchPacks[${index}]`;
    if (!pack.id) errors.push(`${label}.id required.`);
    if (pack.id && ids.has(pack.id)) errors.push(`${label} duplicate pitch id '${pack.id}'.`);
    if (pack.id) ids.add(pack.id);
    if (!pack.title) errors.push(`${label}.title required.`);
    if (!pack.logline) errors.push(`${label}.logline required.`);
    if (!["new-adventure", "sequel", "expansion", "episode"].includes(pack.kind)) errors.push(`${label}.kind invalid.`);
    if (!["seed", "draft", "review", "approved"].includes(pack.status)) errors.push(`${label}.status invalid.`);
  });
  if (adventurePipeline.activePitchId && !ids.has(adventurePipeline.activePitchId)) errors.push("adventurePipeline.activePitchId must reference a pitch pack id.");
  if (!Array.isArray(adventurePipeline.productionSteps)) errors.push("adventurePipeline.productionSteps must be an array.");
}

function validateSequelContinuityBrowser(sequelContinuity, errors) {
  if (!sequelContinuity || typeof sequelContinuity !== "object" || Array.isArray(sequelContinuity)) { errors.push("sequelContinuity must be an object."); return; }
  if (!Array.isArray(sequelContinuity.hooks) || sequelContinuity.hooks.length === 0) { errors.push("sequelContinuity.hooks must be a non-empty array."); return; }
  const ids = new Set();
  sequelContinuity.hooks.forEach((hook, index) => {
    const label = `sequelContinuity.hooks[${index}]`;
    if (!hook.id) errors.push(`${label}.id required.`);
    if (hook.id && ids.has(hook.id)) errors.push(`${label} duplicate hook id '${hook.id}'.`);
    if (hook.id) ids.add(hook.id);
    if (!hook.title) errors.push(`${label}.title required.`);
    if (!["seed", "active", "resolved", "retired"].includes(hook.status)) errors.push(`${label}.status invalid.`);
  });
  if (sequelContinuity.activeHookId && !ids.has(sequelContinuity.activeHookId)) errors.push("sequelContinuity.activeHookId must reference a hook id.");
  if (!Array.isArray(sequelContinuity.canonRules) || !sequelContinuity.canonRules.length) errors.push("sequelContinuity.canonRules must be a non-empty array.");
  if (!Array.isArray(sequelContinuity.sequelSeeds)) errors.push("sequelContinuity.sequelSeeds must be an array.");
}



function validateChiptuneStudioBrowser(chiptuneStudio, errors) {
  if (!chiptuneStudio || typeof chiptuneStudio !== "object" || Array.isArray(chiptuneStudio)) { errors.push("chiptuneStudio must be an object."); return; }
  if (!Array.isArray(chiptuneStudio.presets) || !chiptuneStudio.presets.length) errors.push("chiptuneStudio.presets must be a non-empty array.");
  const presetIds = new Set((chiptuneStudio.presets || []).map(preset => preset.id));
  if (chiptuneStudio.activePresetId && !presetIds.has(chiptuneStudio.activePresetId)) errors.push("chiptuneStudio.activePresetId must reference a preset id.");
  (chiptuneStudio.presets || []).forEach((preset, index) => {
    if (!preset.id) errors.push(`chiptuneStudio.presets[${index}].id required.`);
    if (!preset.name) errors.push(`chiptuneStudio.presets[${index}].name required.`);
    if (!["8-bit", "16-bit", "hybrid"].includes(preset.targetStyle)) errors.push(`chiptuneStudio.presets[${index}].targetStyle must be 8-bit, 16-bit, or hybrid.`);
    if (!Number.isInteger(preset.sampleRate) || preset.sampleRate < 8000 || preset.sampleRate > 48000) errors.push(`chiptuneStudio.presets[${index}].sampleRate must be 8000..48000.`);
  });
  if (!Array.isArray(chiptuneStudio.importedTracks)) errors.push("chiptuneStudio.importedTracks must be an array.");
  if (!Array.isArray(chiptuneStudio.retroOutputs)) errors.push("chiptuneStudio.retroOutputs must be an array.");
  if (!Array.isArray(chiptuneStudio.arrangementSketches)) errors.push("chiptuneStudio.arrangementSketches must be an array.");
}

function validatePixelStudioBrowser(pixelStudio, errors) {
  if (!pixelStudio || typeof pixelStudio !== "object" || Array.isArray(pixelStudio)) { errors.push("pixelStudio must be an object."); return; }
  if (!Array.isArray(pixelStudio.presets) || !pixelStudio.presets.length) { errors.push("pixelStudio.presets must be a non-empty array."); return; }
  const ids = new Set();
  pixelStudio.presets.forEach((preset, index) => {
    if (!preset.id) errors.push(`pixelStudio.presets[${index}].id required.`);
    if (preset.id && ids.has(preset.id)) errors.push(`duplicate pixelStudio preset id '${preset.id}'.`);
    if (preset.id) ids.add(preset.id);
    if (!preset.name) errors.push(`pixelStudio.presets[${index}].name required.`);
    if (!Number.isInteger(preset.outputSize) || preset.outputSize < 8 || preset.outputSize > 256) errors.push(`pixelStudio.presets[${index}].outputSize must be 8..256.`);
    if (!Number.isInteger(preset.pixelBlock) || preset.pixelBlock < 1 || preset.pixelBlock > 32) errors.push(`pixelStudio.presets[${index}].pixelBlock must be 1..32.`);
  });
  if (pixelStudio.activePresetId && !ids.has(pixelStudio.activePresetId)) errors.push("pixelStudio.activePresetId must reference a preset id.");
  if (!Array.isArray(pixelStudio.importedAssets)) errors.push("pixelStudio.importedAssets must be an array.");
}

function validateWritersStudioBrowser(writersStudio, errors) {
  if (!writersStudio || typeof writersStudio !== "object" || Array.isArray(writersStudio)) { errors.push("writersStudio must be an object."); return; }
  if (!Array.isArray(writersStudio.teamRoles) || !writersStudio.teamRoles.length) { errors.push("writersStudio.teamRoles must be a non-empty array."); return; }
  if (!Array.isArray(writersStudio.adventureBriefs) || !writersStudio.adventureBriefs.length) { errors.push("writersStudio.adventureBriefs must be a non-empty array."); return; }
  const roleIds = new Set(writersStudio.teamRoles.map(role => role.id));
  const briefIds = new Set(writersStudio.adventureBriefs.map(brief => brief.id));
  writersStudio.teamRoles.forEach((role, index) => { if (!role.id) errors.push(`writersStudio.teamRoles[${index}].id required.`); if (!role.name) errors.push(`writersStudio.teamRoles[${index}].name required.`); if (!role.prompt) errors.push(`writersStudio.teamRoles[${index}].prompt required.`); });
  writersStudio.adventureBriefs.forEach((brief, index) => { if (!brief.id) errors.push(`writersStudio.adventureBriefs[${index}].id required.`); if (!brief.title) errors.push(`writersStudio.adventureBriefs[${index}].title required.`); if (!brief.logline) errors.push(`writersStudio.adventureBriefs[${index}].logline required.`); if (!["new-adventure", "sequel", "expansion", "dlc"].includes(brief.kind)) errors.push(`writersStudio.adventureBriefs[${index}].kind invalid.`); });
  if (writersStudio.activeRoleId && !roleIds.has(writersStudio.activeRoleId)) errors.push("writersStudio.activeRoleId must reference a team role id.");
  if (writersStudio.activeBriefId && !briefIds.has(writersStudio.activeBriefId)) errors.push("writersStudio.activeBriefId must reference an adventure brief id.");
  if (!Array.isArray(writersStudio.generatedDrafts)) errors.push("writersStudio.generatedDrafts must be an array.");
}

