function normalizeCreatorOnboarding(onboarding = {}) {
  const fallback = buildDemoCreatorOnboarding();
  const source = onboarding && typeof onboarding === "object" && !Array.isArray(onboarding) ? onboarding : fallback;
  const steps = Array.isArray(source.steps) && source.steps.length ? source.steps : fallback.steps;
  return {
    track: String(source.track || fallback.track),
    currentStepId: String(source.currentStepId || steps.find(step => !step.done)?.id || steps[0]?.id || ""),
    steps: steps.map((step, index) => ({
      id: String(step.id || `step_${index + 1}`),
      label: String(step.label || `Creator step ${index + 1}`),
      done: Boolean(step.done),
      note: String(step.note || "")
    })).slice(0, 24)
  };
}

function normalizeStudioThemes(themes) {
  const fallback = buildDemoStudioThemes();
  const source = Array.isArray(themes) && themes.length ? themes : fallback;
  return source.map((theme, index) => ({
    id: String(theme.id || `theme_${index + 1}`),
    name: String(theme.name || `Theme ${index + 1}`),
    mode: String(theme.mode || "custom"),
    accent: String(theme.accent || "#61f0ff"),
    paletteId: String(theme.paletteId || state.assets?.activePaletteId || "palette_shasta_twilight"),
    notes: String(theme.notes || "")
  })).slice(0, 12);
}

function normalizeCartridgeMeta(meta = {}) {
  const fallback = buildDemoCartridgeMeta();
  const c = meta && typeof meta === "object" && !Array.isArray(meta) ? meta : fallback;
  return {
    cartridgeId: String(c.cartridgeId || fallback.cartridgeId),
    buildLabel: String(c.buildLabel || fallback.buildLabel),
    targetRuntime: String(c.targetRuntime || fallback.targetRuntime),
    rating: String(c.rating || fallback.rating),
    estimatedPlayMinutes: clamp(parseInt(c.estimatedPlayMinutes, 10) || fallback.estimatedPlayMinutes, 1, 180),
    coverTagline: String(c.coverTagline || fallback.coverTagline),
    includes: Array.isArray(c.includes) ? c.includes.map(String).filter(Boolean).slice(0, 24) : fallback.includes
  };
}

function normalizeHandoffBrief(brief = {}) {
  const fallback = buildDemoHandoffBrief();
  const b = brief && typeof brief === "object" && !Array.isArray(brief) ? brief : fallback;
  return {
    audience: String(b.audience || fallback.audience),
    summary: String(b.summary || fallback.summary),
    nextMilestone: String(b.nextMilestone || fallback.nextMilestone),
    risks: Array.isArray(b.risks) ? b.risks.map(String).filter(Boolean).slice(0, 12) : fallback.risks,
    asks: Array.isArray(b.asks) ? b.asks.map(String).filter(Boolean).slice(0, 12) : fallback.asks
  };
}

function validateCreatorOnboardingBrowser(onboarding, errors) {
  if (!onboarding || typeof onboarding !== "object" || Array.isArray(onboarding)) { errors.push("creatorOnboarding must be an object."); return; }
  if (!onboarding.track) errors.push("creatorOnboarding.track is required.");
  if (!Array.isArray(onboarding.steps) || !onboarding.steps.length) { errors.push("creatorOnboarding.steps must be a non-empty array."); return; }
  onboarding.steps.forEach((step, index) => {
    if (!step.id) errors.push(`creatorOnboarding.steps[${index}].id required.`);
    if (!step.label) errors.push(`creatorOnboarding.steps[${index}].label required.`);
    if (typeof step.done !== "boolean") errors.push(`creatorOnboarding.steps[${index}].done must be boolean.`);
  });
}

function validateStudioThemesBrowser(themes, activeThemeId, errors) {
  if (!Array.isArray(themes) || !themes.length) { errors.push("studioThemes must be a non-empty array."); return; }
  const ids = new Set();
  themes.forEach((theme, index) => {
    if (!theme.id) errors.push(`studioThemes[${index}].id required.`);
    if (theme.id && ids.has(theme.id)) errors.push(`duplicate studioThemes id '${theme.id}'.`);
    if (theme.id) ids.add(theme.id);
    if (!theme.name) errors.push(`studioThemes[${index}].name required.`);
    if (!theme.paletteId) errors.push(`studioThemes[${index}].paletteId required.`);
  });
  if (activeThemeId && !ids.has(activeThemeId)) errors.push("activeThemeId must reference a studioThemes id.");
}

function validateCartridgeMetaBrowser(meta, errors) {
  if (!meta || typeof meta !== "object" || Array.isArray(meta)) { errors.push("cartridgeMeta must be an object."); return; }
  ["cartridgeId", "buildLabel", "targetRuntime", "rating", "coverTagline"].forEach(key => { if (!meta[key]) errors.push(`cartridgeMeta.${key} is required.`); });
  if (!Number.isInteger(meta.estimatedPlayMinutes) || meta.estimatedPlayMinutes < 1 || meta.estimatedPlayMinutes > 180) errors.push("cartridgeMeta.estimatedPlayMinutes must be 1..180.");
  if (!Array.isArray(meta.includes) || !meta.includes.length) errors.push("cartridgeMeta.includes must be a non-empty array.");
}

function validateHandoffBriefBrowser(brief, errors) {
  if (!brief || typeof brief !== "object" || Array.isArray(brief)) { errors.push("handoffBrief must be an object."); return; }
  ["audience", "summary", "nextMilestone"].forEach(key => { if (!brief[key]) errors.push(`handoffBrief.${key} is required.`); });
  if (!Array.isArray(brief.risks)) errors.push("handoffBrief.risks must be an array.");
  if (!Array.isArray(brief.asks)) errors.push("handoffBrief.asks must be an array.");
}

function projectHealthScore() {
  const validation = validateProjectBrowser(state);
  const releaseChecks = state.releaseManifest?.checklist || [];
  const releaseDone = releaseChecks.length ? releaseChecks.filter(c => c.done).length / releaseChecks.length : 0;
  const onboardingSteps = state.creatorOnboarding?.steps || [];
  const onboardingDone = onboardingSteps.length ? onboardingSteps.filter(s => s.done).length / onboardingSteps.length : 0;
  const auditChecks = state.alphaAudit?.checks || [];
  const auditDone = auditChecks.length ? auditChecks.filter(c => c.passed).length / auditChecks.length : 0;
  const validity = validation.ok ? 1 : 0.25;
  return Math.round((validity * 0.4 + releaseDone * 0.2 + onboardingDone * 0.2 + auditDone * 0.2) * 100);
}

function renderStudioStats() {
  if (!el.studioStats) return;
  const counts = { scenes: state.scenes.length, npcs: state.scenes.reduce((sum, scene) => sum + scene.npcs.length, 0), items: state.scenes.reduce((sum, scene) => sum + scene.items.length, 0), warps: state.scenes.reduce((sum, scene) => sum + scene.warps.length, 0), quests: state.quests.length, sprites: state.assets?.sprites?.length || 0, acts: state.storyArc?.acts?.length || 0, notes: state.playtestLog?.length || 0, cues: state.audioCues?.length || 0, thumbs: state.sceneThumbnails?.length || 0, audit: state.alphaAudit?.checks?.filter?.(c => c.passed)?.length || 0, onboarding: state.creatorOnboarding?.steps?.filter?.(s => s.done)?.length || 0, health: projectHealthScore(), packs: state.assetPacks?.length || 0, presets: state.sceneWizard?.presets?.length || 0, stamps: state.quickStamps?.length || 0, profiles: state.exportProfiles?.length || 0, reviewOpen: state.projectReview?.reviewItems?.filter?.(item => item.status === "open")?.length || 0, scannerIssues: state.issueScanner?.checks?.filter?.(check => !check.passed)?.length || 0, codexTasks: state.codexHandoff?.tasks?.length || 0, creatorPrompts: state.creatorPromptDeck?.prompts?.length || 0, sprintTasks: state.buildSprint?.tasks?.length || 0, diagnostics: state.releaseDiagnostics?.checks?.filter?.(check => check.status !== "pass")?.length || 0, collabNotes: state.collaboratorNotes?.length || 0, recipes: state.buildRecipes?.length || 0, pixelAssets: state.pixelStudio?.importedAssets?.length || 0, spriteFrames: state.spriteStudio?.frames?.length || 0, writerDrafts: state.writersStudio?.generatedDrafts?.length || 0 };
  el.studioStats.innerHTML = `<div><strong>${counts.scenes}</strong><small>Scenes</small></div><div><strong>${counts.npcs}</strong><small>NPCs</small></div><div><strong>${counts.items}</strong><small>Items</small></div><div><strong>${counts.warps}</strong><small>Warps</small></div><div><strong>${counts.quests}</strong><small>Quests</small></div><div><strong>${counts.sprites}</strong><small>Sprites</small></div><div><strong>${counts.acts}</strong><small>Acts</small></div><div><strong>${counts.notes}</strong><small>Playtest Notes</small></div><div><strong>${counts.cues}</strong><small>Audio Cues</small></div><div><strong>${counts.thumbs}</strong><small>Thumbs</small></div><div><strong>${counts.audit}</strong><small>Audit Passes</small></div><div><strong>${counts.onboarding}</strong><small>Onboarded</small></div><div><strong>${counts.health}%</strong><small>Health</small></div><div><strong>${counts.packs}</strong><small>Packs</small></div><div><strong>${counts.sprintTasks}</strong><small>Sprint Tasks</small></div><div><strong>${counts.diagnostics}</strong><small>Diag Warnings</small></div><div><strong>${counts.pixelAssets}</strong><small>Pixel Assets</small></div><div><strong>${counts.writerDrafts}</strong><small>Writer Drafts</small></div>`;
}

