function saveLocal() { localStorage.setItem(STORAGE_KEY, JSON.stringify(state, null, 2)); log("Saved project to local browser storage."); }
function saveSlot(slot) {
  localStorage.setItem(`${SAVE_SLOT_PREFIX}${slot}`, JSON.stringify(state, null, 2));
  log(`Saved project to slot ${slot}.`);
}
function loadSlot(slot) {
  const raw = localStorage.getItem(`${SAVE_SLOT_PREFIX}${slot}`);
  if (!raw) { log(`No project saved in slot ${slot} yet.`); return; }
  try { loadProject(JSON.parse(raw), `Loaded save slot ${slot}.`); } catch(err) { log(`Slot ${slot} load failed: ${err.message}`); }
}
function loadLocal() { const raw=localStorage.getItem(STORAGE_KEY); if (!raw) { log("No local save found yet."); return; } try { loadProject(JSON.parse(raw), "Loaded local project."); } catch(err) { log(`Local load failed: ${err.message}`); } }
