function exportPlayableHtml() {
  const safeProjectJson = JSON.stringify(state, null, 2).replace(/<\/script/gi, "<\\/script");
  const html = `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"/>
<meta name="viewport" content="width=device-width, initial-scale=1"/>
<title>${escapeHtml(state.meta.title)} · PixelForge Export</title>
<style>body{margin:0;background:#0d1020;color:#f8f2de;font-family:system-ui,sans-serif;display:grid;place-items:center;min-height:100vh}.wrap{width:min(980px,96vw)}canvas{width:100%;max-width:768px;image-rendering:pixelated;background:#111;border:4px solid #252b4b;border-radius:12px}.hud{display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap}.box{background:#151a33;border:1px solid #343b68;border-radius:14px;padding:1rem;margin:.75rem 0}.dialogue{min-height:64px}small{color:#aab2d5}</style>
</head>
<body>
<div class="wrap"><div class="hud"><h1>${escapeHtml(state.meta.title)}</h1><p>Exported from Parallax PixelForge v3.2</p></div><div class="box"><strong>${escapeHtml(state.titleScreen?.subtitle || "")}</strong><p>${escapeHtml(state.titleScreen?.openingText || "")}</p><small>${escapeHtml(state.titleScreen?.startPrompt || "Press Play to begin.")}</small></div><canvas id="c" width="768" height="512"></canvas><div id="dialogue" class="box dialogue">Move with arrow keys/WASD. Space/Enter talks. Warps respect story gates.</div><div id="stats" class="box"></div><small>${escapeHtml(state.titleScreen?.footerText || state.meta.claimBoundary || "Creative game prototype.")}</small></div>
<script id="project" type="application/json">${safeProjectJson}</script>
<script>
const TILE=32, W=24, H=16; const tileColors={grass:["#5abf65","#4aaa57"],road:["#c99a5b","#b8864b"],forest:["#267445","#1f5f39"],water:["#3779d4","#285faf"],mountain:["#8d8998","#6f6b7d"],diner:["#ff6f91","#f7d66f"],pyramid:["#ffd36e","#b78235"],dream:["#8c6dff","#61f0ff"],bridge:["#9b6b43","#f0c27a"],cabin:["#8b4a32","#ffd6a0"],sign:["#deb887","#4b2d1a"],shrine:["#f8f2de","#8df7c8"],portal:["#3f2d80","#ff7aa2"],lab:["#26324c","#8dc8ff"],cave:["#332d3f","#6f6b7d"],flowers:["#62b96d","#ff7aa2"],crystal:["#123a5a","#61f0ff"],tower:["#26223e","#ffd36e"],tunnel:["#17121f","#8c6dff"],neon:["#10142a","#61f0ff"],artifact:["#3d2a12","#ffd36e"],campfire:["#402019","#ff9b6e"],console:["#10142a","#8df7c8"],banner:["#4a2330","#ffd36e"],starpath:["#171b31","#f8f2de"],arrow:["#1d253a","#ffd36e"],flagstone:["#2d2f40","#f8f2de"],testpad:["#172433","#8df7c8"],milestone:["#38223d","#ff9b6e"],launchshelf:["#1d1833","#ffd36e"],detailcard:["#1c2b3a","#8dc8ff"],profilechip:["#172a24","#8df7c8"],capsule:["#2b1738","#ff7aa2"]};
const walkable=new Set(["grass","road","forest","diner","pyramid","dream","bridge","cabin","sign","shrine","portal","lab","cave","flowers","crystal","tower","tunnel","neon","artifact","campfire","console","banner","starpath","launchshelf","detailcard","profilechip","capsule"]);
let p=JSON.parse(document.getElementById("project").textContent); const ctx=document.getElementById("c").getContext("2d"); const dlg=document.getElementById("dialogue"), stats=document.getElementById("stats");
function scene(){return p.scenes.find(s=>s.id===p.activeSceneId)||p.scenes[0]} function draw(){const s=scene(); for(let y=0;y<H;y++)for(let x=0;x<W;x++){let id=s.map.tiles[y*W+x]||"grass", c=tileColors[id]||tileColors.grass; ctx.fillStyle=c[0];ctx.fillRect(x*TILE,y*TILE,TILE,TILE);ctx.fillStyle=c[1];ctx.fillRect(x*TILE+8,y*TILE+8,16,16)} s.warps.forEach(o=>{ctx.strokeStyle=o.color||"#ff7aa2";ctx.lineWidth=3;ctx.strokeRect(o.x*TILE+8,o.y*TILE+5,16,22)}); s.items.filter(i=>!i.collected).forEach(o=>{ctx.fillStyle=o.color||"#61f0ff";ctx.fillRect(o.x*TILE+11,o.y*TILE+11,10,10)}); s.npcs.forEach(o=>{ctx.fillStyle=o.color||"#f8f2de";ctx.fillRect(o.x*TILE+9,o.y*TILE+6,14,20)}); ctx.fillStyle="#ffd36e";ctx.fillRect(p.player.x*TILE+9,p.player.y*TILE+5,14,23); stats.textContent="Scene: "+s.name+" · Supplies "+p.journey.stats.supplies+" · Morale "+p.journey.stats.morale+" · Wonder "+p.journey.stats.wonder+" · Coherence "+p.journey.stats.coherence}
function delta(d){Object.entries(d||{}).forEach(([k,v])=>{if(p.journey.stats[k]!=null)p.journey.stats[k]=Math.max(0,Math.min(99,p.journey.stats[k]+v))})} function at(list,x,y){return (list||[]).find(o=>o.x===x&&o.y===y)} function itemName(id){for(const s of p.scenes)for(const it of s.items||[])if(it.id===id)return it.name;return id}
function move(dx,dy){const s=scene(), x=p.player.x+dx, y=p.player.y+dy; if(x<0||x>=W||y<0||y>=H||!walkable.has(s.map.tiles[y*W+x])){dlg.textContent="Blocked.";return} p.player.x=x;p.player.y=y; const item=at(s.items,x,y); if(item&&!item.collected){item.collected=true;p.inventory=p.inventory||[];p.inventory.push(item.id);delta(item.effect);dlg.textContent="Collected "+item.name} const warp=at(s.warps,x,y); if(warp){ if(warp.requiredItemId && !(p.inventory||[]).includes(warp.requiredItemId)){dlg.textContent=warp.blockedText||("Need "+itemName(warp.requiredItemId)+"."); draw(); return;} if(warp.requiredWonder!=null && p.journey.stats.wonder<warp.requiredWonder){dlg.textContent=warp.blockedText||("Need "+warp.requiredWonder+" Wonder."); draw(); return;} const t=p.scenes.find(sc=>sc.id===warp.targetSceneId); if(t){p.activeSceneId=t.id;p.player.sceneId=t.id;p.player.x=warp.targetX;p.player.y=warp.targetY;dlg.textContent="Entered "+t.name}} draw()}
function talk(){const s=scene(), dirs=[[0,0],[0,-1],[0,1],[-1,0],[1,0]]; for(const [dx,dy] of dirs){const n=at(s.npcs,p.player.x+dx,p.player.y+dy); if(n){if(!n.talked){n.talked=true;delta(n.effect)} dlg.innerHTML="<b>"+n.name+"</b><br>"+(n.dialogue||["..."]).join("<br>"); draw(); return}} dlg.textContent="No one nearby."}
document.addEventListener("keydown",e=>{const m={ArrowUp:[0,-1],w:[0,-1],W:[0,-1],ArrowDown:[0,1],s:[0,1],S:[0,1],ArrowLeft:[-1,0],a:[-1,0],A:[-1,0],ArrowRight:[1,0],d:[1,0],D:[1,0]}; if(m[e.key]){e.preventDefault();move(...m[e.key])} if(e.key===" "||e.key==="Enter"){e.preventDefault();talk()}}); draw();
</script>
</body>
</html>`;
  downloadBlob(new Blob([html], {type:"text/html"}), `${slugify(state.meta.title)}.playable.v3.2.html`);
  log("Exported playable standalone HTML.");
}

