async function updateHash() { el.projectHash.textContent = await sha256(stableStringify(state)); }
async function sha256(text) { if(globalThis.crypto?.subtle) { const encoded=new TextEncoder().encode(text); const digest=await crypto.subtle.digest("SHA-256", encoded); return Array.from(new Uint8Array(digest)).map(b=>b.toString(16).padStart(2,"0")).join(""); } return `fallback-${simpleHash(text)}`; }
