function simpleHash(str) { let h1=0xdeadbeef, h2=0x41c6ce57; for(let i=0;i<str.length;i++){ const ch=str.charCodeAt(i); h1=Math.imul(h1^ch,2654435761); h2=Math.imul(h2^ch,1597334677); } h1=Math.imul(h1^(h1>>>16),2246822507)^Math.imul(h2^(h2>>>13),3266489909); h2=Math.imul(h2^(h2>>>16),2246822507)^Math.imul(h1^(h1>>>13),3266489909); return (4294967296*(2097151&h2)+(h1>>>0)).toString(16); }
function deltaToLines(delta) { return Object.entries(delta||{}).map(([key,value])=>`${key}: ${value}`).join("\n"); }
function choicesToLines(choices) {
  return (choices || []).map(choice => {
    const parts = [`${choice.label || "Choice"} => ${choice.response || "..."}`];
    const delta = Object.entries(choice.delta || {}).map(([key,value]) => `${key}:${value}`).join(",");
    if (delta) parts.push(delta);
    if (choice.revealQuestId) parts.push(`reveal:${choice.revealQuestId}`);
    if (choice.setFlag) parts.push(`flag:${choice.setFlag}`);
    return parts.join(" | ");
  }).join("\n");
}

