function validateLibraryLauncherBrowser(launcher, shelf, curation, errors) {
  if (!launcher || typeof launcher !== "object" || Array.isArray(launcher)) { errors.push("libraryLauncher must be an object."); return; }
  const gameIds = new Set((shelf?.entries || []).map(entry => entry.id));
  const collectionIds = new Set((curation?.collections || []).map(collection => collection.id));
  if (launcher.activeGameId && !gameIds.has(launcher.activeGameId)) errors.push("libraryLauncher.activeGameId must reference a shelf game.");
  if (launcher.featuredCollectionId && !collectionIds.has(launcher.featuredCollectionId)) errors.push("libraryLauncher.featuredCollectionId must reference a shelf collection.");
  if (!Array.isArray(launcher.featuredSlots) || !launcher.featuredSlots.length) errors.push("libraryLauncher.featuredSlots must be a non-empty array.");
  else launcher.featuredSlots.forEach((slot, index) => { if (!gameIds.has(slot.gameId)) errors.push(`libraryLauncher.featuredSlots[${index}].gameId references missing shelf game '${slot.gameId}'.`); });
}
function validateGameDetailBrowser(detail, shelf, errors) {
  if (!detail || typeof detail !== "object" || Array.isArray(detail)) { errors.push("gameDetail must be an object."); return; }
  const gameIds = new Set((shelf?.entries || []).map(entry => entry.id));
  if (detail.activeGameId && !gameIds.has(detail.activeGameId)) errors.push("gameDetail.activeGameId must reference a shelf game.");
  if (!Array.isArray(detail.tabs) || !detail.tabs.length) errors.push("gameDetail.tabs must be a non-empty array.");
}
function validateSaveProfileManagerBrowser(manager, shelf, sceneIds, errors) {
  if (!manager || typeof manager !== "object" || Array.isArray(manager)) { errors.push("saveProfileManager must be an object."); return; }
  const gameIds = new Set((shelf?.entries || []).map(entry => entry.id));
  const profileIds = new Set((manager.profiles || []).map(profile => profile.id));
  if (!Array.isArray(manager.profiles) || !manager.profiles.length) errors.push("saveProfileManager.profiles must be a non-empty array.");
  if (manager.activeProfileId && !profileIds.has(manager.activeProfileId)) errors.push("saveProfileManager.activeProfileId must reference a profile.");
  (manager.saveIndex || []).forEach((save, index) => { if (!profileIds.has(save.profileId)) errors.push(`saveProfileManager.saveIndex[${index}].profileId references missing profile.`); if (!gameIds.has(save.gameId)) errors.push(`saveProfileManager.saveIndex[${index}].gameId references missing game.`); if (save.sceneId && !sceneIds.has(save.sceneId)) errors.push(`saveProfileManager.saveIndex[${index}].sceneId references missing scene.`); });
}
function validateCollectionCapsulesBrowser(capsules, shelf, curation, errors) {
  if (!capsules || typeof capsules !== "object" || Array.isArray(capsules)) { errors.push("collectionCapsules must be an object."); return; }
  const gameIds = new Set((shelf?.entries || []).map(entry => entry.id));
  const collectionIds = new Set((curation?.collections || []).map(collection => collection.id));
  const capsuleIds = new Set((capsules.capsules || []).map(capsule => capsule.id));
  if (!Array.isArray(capsules.capsules) || !capsules.capsules.length) errors.push("collectionCapsules.capsules must be a non-empty array.");
  if (capsules.activeCapsuleId && !capsuleIds.has(capsules.activeCapsuleId)) errors.push("collectionCapsules.activeCapsuleId must reference a capsule.");
  (capsules.capsules || []).forEach((capsule, index) => { if (capsule.collectionId && !collectionIds.has(capsule.collectionId)) errors.push(`collectionCapsules.capsules[${index}].collectionId references missing collection.`); (capsule.gameIds || []).forEach(gameId => { if (!gameIds.has(gameId)) errors.push(`collectionCapsules.capsules[${index}].gameIds references missing game '${gameId}'.`); }); });
}


