function normalizeBbsNetwork(network = {}) {
  const fallback = buildDemoBbsNetwork();
  const source = network && typeof network === "object" && !Array.isArray(network) ? network : fallback;
  const channels = Array.isArray(source.channels) && source.channels.length ? source.channels : fallback.channels;
  return {
    bbsName: String(source.bbsName || fallback.bbsName),
    networkMode: String(source.networkMode || fallback.networkMode),
    activeChannelId: channels.some(ch => ch.id === source.activeChannelId) ? String(source.activeChannelId) : channels[0]?.id || "",
    privacyMode: String(source.privacyMode || fallback.privacyMode),
    welcomeMessage: String(source.welcomeMessage || fallback.welcomeMessage),
    guidelines: Array.isArray(source.guidelines) ? source.guidelines.map(String).filter(Boolean).slice(0, 12) : fallback.guidelines,
    channels: channels.map((channel, index) => ({
      id: String(channel.id || `chan_${index + 1}`),
      name: String(channel.name || `Channel ${index + 1}`),
      kind: String(channel.kind || "general"),
      description: String(channel.description || "Community channel."),
      status: ["open", "moderated", "closed"].includes(channel.status) ? channel.status : "open",
      postCount: Math.max(0, parseInt(channel.postCount, 10) || 0)
    })).slice(0, 32),
    shareTargets: Array.isArray(source.shareTargets) ? source.shareTargets.map((target, index) => ({
      id: String(target.id || `target_${index + 1}`), name: String(target.name || `Target ${index + 1}`), kind: String(target.kind || "offline"), status: String(target.status || "planned"), note: String(target.note || "")
    })).slice(0, 16) : fallback.shareTargets,
    syncLog: Array.isArray(source.syncLog) ? source.syncLog.map((entry, index) => ({ id: String(entry.id || `sync_${index + 1}`), at: String(entry.at || "unknown"), action: String(entry.action || "sync"), status: String(entry.status || "draft") })).slice(-50) : fallback.syncLog
  };
}

function normalizeSharePackages(sharePackages = {}, shelf = state.gameShelf, capsules = state.collectionCapsules) {
  const fallback = buildDemoSharePackages();
  const source = sharePackages && typeof sharePackages === "object" && !Array.isArray(sharePackages) ? sharePackages : fallback;
  const gameIds = new Set((shelf?.entries || []).map(entry => entry.id));
  const packages = (Array.isArray(source.packages) && source.packages.length ? source.packages : fallback.packages).map((pkg, index) => ({
    id: String(pkg.id || `share_package_${index + 1}`),
    title: String(pkg.title || `Share Package ${index + 1}`),
    gameId: gameIds.has(pkg.gameId) ? String(pkg.gameId) : ((shelf?.entries || [])[0]?.id || ""),
    packageType: String(pkg.packageType || "devlog"),
    status: ["draft", "ready", "published", "needs-review"].includes(pkg.status) ? pkg.status : "draft",
    rightsStatus: String(pkg.rightsStatus || "needs-review"),
    includedExports: Array.isArray(pkg.includedExports) ? pkg.includedExports.map(String).filter(Boolean).slice(0, 20) : [],
    notes: String(pkg.notes || "")
  })).slice(0, 32);
  return {
    activePackageId: packages.some(pkg => pkg.id === source.activePackageId) ? String(source.activePackageId) : packages[0]?.id || "",
    packages,
    exportHistory: Array.isArray(source.exportHistory) ? source.exportHistory.map((entry, index) => ({ id: String(entry.id || `share_export_${index + 1}`), packageId: String(entry.packageId || ""), exportedAt: String(entry.exportedAt || "unknown"), status: String(entry.status || "draft") })).slice(-40) : []
  };
}

function normalizeCommunityFeed(feed = {}, network = state.bbsNetwork, sharePackages = state.sharePackages) {
  const fallback = buildDemoCommunityFeed();
  const source = feed && typeof feed === "object" && !Array.isArray(feed) ? feed : fallback;
  const channelIds = new Set((network?.channels || fallback.posts || []).map(ch => ch.id));
  const posts = (Array.isArray(source.posts) && source.posts.length ? source.posts : fallback.posts).map((post, index) => ({
    id: String(post.id || `post_${index + 1}`),
    channelId: channelIds.has(post.channelId) ? String(post.channelId) : (network?.activeChannelId || "chan_devlog"),
    author: String(post.author || "Creator"),
    title: String(post.title || `Post ${index + 1}`),
    type: String(post.type || "devlog"),
    status: ["draft", "published", "hidden", "needs-review"].includes(post.status) ? post.status : "draft",
    text: String(post.text || ""),
    tags: Array.isArray(post.tags) ? post.tags.map(String).filter(Boolean).slice(0, 12) : [],
    reactions: post.reactions && typeof post.reactions === "object" ? { sparks: Math.max(0, parseInt(post.reactions.sparks, 10) || 0), hearts: Math.max(0, parseInt(post.reactions.hearts, 10) || 0) } : { sparks: 0, hearts: 0 },
    createdAt: String(post.createdAt || "draft")
  })).slice(0, 96);
  const postIds = new Set(posts.map(post => post.id));
  return {
    activePostId: posts.some(post => post.id === source.activePostId) ? String(source.activePostId) : posts[0]?.id || "",
    posts,
    comments: Array.isArray(source.comments) ? source.comments.map((comment, index) => ({
      id: String(comment.id || `comment_${index + 1}`), postId: postIds.has(comment.postId) ? String(comment.postId) : (posts[0]?.id || ""), author: String(comment.author || "Playtester"), text: String(comment.text || ""), status: ["visible", "hidden", "needs-review"].includes(comment.status) ? comment.status : "visible", createdAt: String(comment.createdAt || "draft")
    })).slice(0, 128) : fallback.comments,
    moderationQueue: Array.isArray(source.moderationQueue) ? source.moderationQueue.map((item, index) => ({ id: String(item.id || `mod_${index + 1}`), targetId: String(item.targetId || ""), kind: String(item.kind || "review"), status: ["open", "cleared", "deferred"].includes(item.status) ? item.status : "open", note: String(item.note || "") })).slice(0, 64) : fallback.moderationQueue
  };
}

function normalizeForumChannels(forum = {}, network = state.bbsNetwork, feed = state.communityFeed) {
  const fallback = buildDemoForumChannels();
  const source = forum && typeof forum === "object" && !Array.isArray(forum) ? forum : fallback;
  const networkChannels = network?.channels?.length ? network.channels : fallback.channels;
  const postIds = new Set((feed?.posts || []).map(post => post.id));
  const channels = (Array.isArray(source.channels) && source.channels.length ? source.channels : networkChannels).map((channel, index) => ({
    id: String(channel.id || `chan_${index + 1}`), name: String(channel.name || `Channel ${index + 1}`), kind: String(channel.kind || "general"),
    rules: Array.isArray(channel.rules) ? channel.rules.map(String).filter(Boolean).slice(0, 12) : ["Be kind", "Stay on topic"],
    featuredPostIds: Array.isArray(channel.featuredPostIds) ? channel.featuredPostIds.map(String).filter(id => postIds.size ? postIds.has(id) : true).slice(0, 12) : [],
    status: ["open", "moderated", "closed"].includes(channel.status) ? channel.status : "open"
  })).slice(0, 32);
  return {
    activeChannelId: channels.some(channel => channel.id === source.activeChannelId) ? String(source.activeChannelId) : (network?.activeChannelId || channels[0]?.id || ""),
    channels,
    badges: Array.isArray(source.badges) ? source.badges.map((badge, index) => ({ id: String(badge.id || `forum_badge_${index + 1}`), label: String(badge.label || `Badge ${index + 1}`), criteria: String(badge.criteria || "Community contribution"), earned: Boolean(badge.earned) })).slice(0, 32) : fallback.badges
  };
}

function activeBbsChannel() {
  state.bbsNetwork = normalizeBbsNetwork(state.bbsNetwork);
  return state.bbsNetwork.channels.find(channel => channel.id === state.bbsNetwork.activeChannelId) || state.bbsNetwork.channels[0];
}

function activeSharePackage() {
  state.sharePackages = normalizeSharePackages(state.sharePackages, state.gameShelf, state.collectionCapsules);
  return state.sharePackages.packages.find(pkg => pkg.id === state.sharePackages.activePackageId) || state.sharePackages.packages[0];
}

function renderBbsNetworkPanel() {
  if (!el.bbsNetworkPanel) return;
  state.bbsNetwork = normalizeBbsNetwork(state.bbsNetwork);
  const active = activeBbsChannel();
  const channels = state.bbsNetwork.channels.map(channel => `<article class="suite-card ${channel.id === state.bbsNetwork.activeChannelId ? "active" : ""}"><small>${escapeHtml(channel.kind)} · ${escapeHtml(channel.status)} · ${channel.postCount} post(s)</small><strong>${escapeHtml(channel.name)}</strong><p>${escapeHtml(channel.description)}</p></article>`).join("");
  const targets = state.bbsNetwork.shareTargets.map(target => `<span class="mini-pill">${escapeHtml(target.name)} · ${escapeHtml(target.status)}</span>`).join("");
  el.bbsNetworkPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.bbsNetwork.networkMode)} · ${escapeHtml(state.bbsNetwork.privacyMode)}</small><strong>${escapeHtml(state.bbsNetwork.bbsName)}</strong><p>${escapeHtml(state.bbsNetwork.welcomeMessage)}</p><p>Active channel: ${escapeHtml(active?.name || "none")}</p><div class="mini-pill-row">${targets}</div></article>${channels}`;
}

function renderSharePackagePanel() {
  if (!el.sharePackagePanel) return;
  state.sharePackages = normalizeSharePackages(state.sharePackages, state.gameShelf, state.collectionCapsules);
  const packages = state.sharePackages.packages.map(pkg => `<article class="suite-card ${pkg.id === state.sharePackages.activePackageId ? "active" : ""}"><small>${escapeHtml(pkg.packageType)} · ${escapeHtml(pkg.status)} · ${escapeHtml(pkg.rightsStatus)}</small><strong>${escapeHtml(pkg.title)}</strong><p>${escapeHtml(pkg.notes)}</p><div class="mini-pill-row">${pkg.includedExports.map(exp => `<span class="mini-pill">${escapeHtml(exp)}</span>`).join("")}</div></article>`).join("");
  el.sharePackagePanel.innerHTML = `<article class="suite-card active"><small>Share packages</small><strong>${state.sharePackages.packages.length} package(s) · ${state.sharePackages.exportHistory.length} export(s)</strong><p>Use this before posting a cartridge to the BBS so rights, exports, and version labels stay attached.</p></article>${packages}`;
}

function renderCommunityFeedPanel() {
  if (!el.communityFeedPanel) return;
  state.communityFeed = normalizeCommunityFeed(state.communityFeed, state.bbsNetwork, state.sharePackages);
  const posts = state.communityFeed.posts.slice(0, 8).map(post => `<article class="suite-card ${post.id === state.communityFeed.activePostId ? "active" : ""}"><small>${escapeHtml(post.channelId)} · ${escapeHtml(post.type)} · ${escapeHtml(post.status)}</small><strong>${escapeHtml(post.title)}</strong><p>${escapeHtml(post.text)}</p><div class="mini-pill-row"><span class="mini-pill">${post.reactions.sparks} sparks</span><span class="mini-pill">${post.reactions.hearts} hearts</span>${post.tags.map(tag => `<span class="mini-pill">#${escapeHtml(tag)}</span>`).join("")}</div></article>`).join("");
  const openMods = state.communityFeed.moderationQueue.filter(item => item.status === "open").length;
  el.communityFeedPanel.innerHTML = `<article class="suite-card ${openMods ? "needs-work" : "ready"}"><small>Local community feed</small><strong>${state.communityFeed.posts.length} post(s) · ${openMods} moderation item(s)</strong><p>Draft, export, and review posts before sharing with friends or a future hosted BBS.</p></article>${posts}`;
}

function renderForumChannelsPanel() {
  if (!el.forumChannelsPanel) return;
  state.forumChannels = normalizeForumChannels(state.forumChannels, state.bbsNetwork, state.communityFeed);
  const channels = state.forumChannels.channels.map(channel => `<article class="suite-card ${channel.id === state.forumChannels.activeChannelId ? "active" : ""}"><small>${escapeHtml(channel.kind)} · ${escapeHtml(channel.status)}</small><strong>${escapeHtml(channel.name)}</strong><p>${channel.rules.map(rule => `• ${escapeHtml(rule)}`).join("<br>")}</p></article>`).join("");
  const badges = state.forumChannels.badges.map(badge => `<span class="mini-pill">${badge.earned ? "✓ " : "○ "}${escapeHtml(badge.label)}</span>`).join("");
  el.forumChannelsPanel.innerHTML = `<article class="suite-card active"><small>Forum rules + badges</small><strong>${state.forumChannels.channels.length} channel(s)</strong><div class="mini-pill-row">${badges}</div></article>${channels}`;
}

function cycleBbsChannel() {
  pushUndo();
  state.bbsNetwork = normalizeBbsNetwork(state.bbsNetwork);
  const ids = state.bbsNetwork.channels.map(channel => channel.id);
  const index = Math.max(0, ids.indexOf(state.bbsNetwork.activeChannelId));
  state.bbsNetwork.activeChannelId = ids[(index + 1) % ids.length] || "";
  state.forumChannels = normalizeForumChannels(state.forumChannels, state.bbsNetwork, state.communityFeed);
  state.forumChannels.activeChannelId = state.bbsNetwork.activeChannelId;
  renderAll(`BBS channel selected: ${activeBbsChannel()?.name || "none"}.`);
}

function createBbsPost() {
  pushUndo();
  state.bbsNetwork = normalizeBbsNetwork(state.bbsNetwork);
  state.communityFeed = normalizeCommunityFeed(state.communityFeed, state.bbsNetwork, state.sharePackages);
  const channel = activeBbsChannel();
  const pkg = activeSharePackage();
  const id = uniqueId("post_share", state.communityFeed.posts.map(post => post.id));
  state.communityFeed.posts.unshift({
    id,
    channelId: channel?.id || "chan_devlog",
    author: "Tal-Aren-Vox",
    title: `${pkg?.title || state.meta.title} — BBS Post`,
    type: channel?.kind === "release" ? "cartridge" : "devlog",
    status: "draft",
    text: `Sharing ${pkg?.title || state.meta.title}. Include version, rights status, screenshots, save notes, and what feedback would help most.`,
    tags: ["pixelforge", "share", slugify(state.meta.title)],
    reactions: { sparks: 0, hearts: 0 },
    createdAt: new Date().toISOString()
  });
  state.communityFeed.activePostId = id;
  const channelRecord = state.bbsNetwork.channels.find(ch => ch.id === channel?.id);
  if (channelRecord) channelRecord.postCount += 1;
  addPlaytestLogEntry("bbs", `Drafted BBS post for ${pkg?.title || state.meta.title}.`, state.activeSceneId);
  renderAll("Created a local BBS draft post.");
}

function buildSharePackage() {
  pushUndo();
  state.gameShelf = normalizeGameShelf(state.gameShelf, state.scenes);
  state.sharePackages = normalizeSharePackages(state.sharePackages, state.gameShelf, state.collectionCapsules);
  const activeGame = state.gameShelf.entries.find(entry => entry.id === state.gameShelf.activeGameId) || state.gameShelf.entries[0];
  const id = uniqueId("share_package", state.sharePackages.packages.map(pkg => pkg.id));
  const pkg = { id, title: `${activeGame?.title || state.meta.title} — BBS Share Pack`, gameId: activeGame?.id || "", packageType: "bbs-cartridge", status: "draft", rightsStatus: activeGame?.rightsStatus || "needs-review", includedExports: ["game-detail", "game-shelf", "collection-capsule", "rights-registry", "release-workshop", "community-post"], notes: "Generated from the active shelf game for local BBS sharing." };
  state.sharePackages.packages.unshift(pkg);
  state.sharePackages.activePackageId = id;
  renderAll("Built a new BBS share package from the active shelf game.");
}

async function exportBbsNetwork() {
  state.bbsNetwork = normalizeBbsNetwork(state.bbsNetwork);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.bbs-network", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, bbsNetwork: state.bbsNetwork, boundary: "Local-first BBS manifest. Hosting, accounts, and public moderation are future integrations, not included in this prototype." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.bbs-network.v3.2.json`);
  log("Exported BBS Network JSON.");
}

async function exportSharePackage() {
  state.sharePackages = normalizeSharePackages(state.sharePackages, state.gameShelf, state.collectionCapsules);
  const pkg = activeSharePackage();
  if (pkg) state.sharePackages.exportHistory.push({ id: uniqueId("share_export", state.sharePackages.exportHistory.map(e => e.id)), packageId: pkg.id, exportedAt: new Date().toISOString(), status: pkg.status });
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.bbs-share-package", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, activePackage: pkg, sharePackages: state.sharePackages, rightsBoundary: "Only share user-owned, original, licensed, or public-domain assets/music. Keep placeholder/import status visible." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.bbs-share-package.v3.2.json`);
  renderAll("Exported BBS Share Package JSON.");
}

async function exportCommunityFeed() {
  state.communityFeed = normalizeCommunityFeed(state.communityFeed, state.bbsNetwork, state.sharePackages);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.community-feed", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, communityFeed: state.communityFeed, moderationBoundary: "Community feed is a local draft/export structure. Public posting requires human moderation and rights review." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.community-feed.v3.2.json`);
  log("Exported Community Feed JSON.");
}

function moderateCommunityPost() {
  pushUndo();
  state.communityFeed = normalizeCommunityFeed(state.communityFeed, state.bbsNetwork, state.sharePackages);
  const item = state.communityFeed.moderationQueue.find(mod => mod.status === "open") || state.communityFeed.moderationQueue[0];
  if (!item) { renderAll("No moderation items found."); return; }
  item.status = item.status === "cleared" ? "open" : "cleared";
  renderAll(`Moderation item ${item.status}: ${item.note}`);
}

async function exportForumChannels() {
  state.forumChannels = normalizeForumChannels(state.forumChannels, state.bbsNetwork, state.communityFeed);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.forum-channels", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, forumChannels: state.forumChannels, guidelines: state.bbsNetwork?.guidelines || [] };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.forum-channels.v3.2.json`);
  log("Exported Forum Channels JSON.");
}

function validateBbsNetworkBrowser(network, errors) {
  if (!network || typeof network !== "object" || Array.isArray(network)) { errors.push("bbsNetwork must be an object."); return; }
  const ids = new Set((network.channels || []).map(channel => channel.id));
  if (!Array.isArray(network.channels) || !network.channels.length) errors.push("bbsNetwork.channels must be a non-empty array.");
  if (network.activeChannelId && !ids.has(network.activeChannelId)) errors.push("bbsNetwork.activeChannelId must reference a channel.");
  if (!Array.isArray(network.guidelines) || !network.guidelines.length) errors.push("bbsNetwork.guidelines must be a non-empty array.");
}
function validateSharePackagesBrowser(sharePackages, shelf, capsules, errors) {
  if (!sharePackages || typeof sharePackages !== "object" || Array.isArray(sharePackages)) { errors.push("sharePackages must be an object."); return; }
  const gameIds = new Set((shelf?.entries || []).map(entry => entry.id));
  const ids = new Set((sharePackages.packages || []).map(pkg => pkg.id));
  if (!Array.isArray(sharePackages.packages) || !sharePackages.packages.length) errors.push("sharePackages.packages must be a non-empty array.");
  if (sharePackages.activePackageId && !ids.has(sharePackages.activePackageId)) errors.push("sharePackages.activePackageId must reference a package.");
  (sharePackages.packages || []).forEach((pkg, index) => { if (pkg.gameId && !gameIds.has(pkg.gameId)) errors.push(`sharePackages.packages[${index}].gameId references missing shelf game '${pkg.gameId}'.`); });
}
function validateCommunityFeedBrowser(feed, network, sharePackages, errors) {
  if (!feed || typeof feed !== "object" || Array.isArray(feed)) { errors.push("communityFeed must be an object."); return; }
  const channelIds = new Set((network?.channels || []).map(channel => channel.id));
  const postIds = new Set((feed.posts || []).map(post => post.id));
  if (!Array.isArray(feed.posts) || !feed.posts.length) errors.push("communityFeed.posts must be a non-empty array.");
  if (feed.activePostId && !postIds.has(feed.activePostId)) errors.push("communityFeed.activePostId must reference a post.");
  (feed.posts || []).forEach((post, index) => { if (post.channelId && !channelIds.has(post.channelId)) errors.push(`communityFeed.posts[${index}].channelId references missing channel '${post.channelId}'.`); });
  (feed.comments || []).forEach((comment, index) => { if (comment.postId && !postIds.has(comment.postId)) errors.push(`communityFeed.comments[${index}].postId references missing post '${comment.postId}'.`); });
}
function validateForumChannelsBrowser(forum, network, feed, errors) {
  if (!forum || typeof forum !== "object" || Array.isArray(forum)) { errors.push("forumChannels must be an object."); return; }
  const channelIds = new Set((forum.channels || []).map(channel => channel.id));
  const postIds = new Set((feed?.posts || []).map(post => post.id));
  if (!Array.isArray(forum.channels) || !forum.channels.length) errors.push("forumChannels.channels must be a non-empty array.");
  if (forum.activeChannelId && !channelIds.has(forum.activeChannelId)) errors.push("forumChannels.activeChannelId must reference a forum channel.");
  (forum.channels || []).forEach((channel, index) => (channel.featuredPostIds || []).forEach(id => { if (postIds.size && !postIds.has(id)) errors.push(`forumChannels.channels[${index}] references missing featured post '${id}'.`); }));
}

