function normalizeBbsLivingRoom(room = {}, network = state.bbsNetwork) {
  const fallback = buildDemoBbsLivingRoom();
  const source = room && typeof room === "object" && !Array.isArray(room) ? room : fallback;
  const modes = (Array.isArray(source.modes) && source.modes.length ? source.modes : fallback.modes).map((mode, index) => ({
    id: String(mode.id || `mode_${index + 1}`), name: String(mode.name || `Mode ${index + 1}`), kind: String(mode.kind || "spectate"), description: String(mode.description || "Shared play mode."),
    maxPlayers: Math.max(1, parseInt(mode.maxPlayers, 10) || 1), maxSpectators: Math.max(0, parseInt(mode.maxSpectators, 10) || 0), status: String(mode.status || "draft")
  })).slice(0, 16);
  return {
    roomName: String(source.roomName || fallback.roomName),
    activeModeId: modes.some(mode => mode.id === source.activeModeId) ? String(source.activeModeId) : modes[0]?.id || "",
    networkBoundary: String(source.networkBoundary || fallback.networkBoundary),
    roomCodePolicy: String(source.roomCodePolicy || fallback.roomCodePolicy),
    noChatDesign: source.noChatDesign !== false,
    modes,
    roomDecor: Array.isArray(source.roomDecor) ? source.roomDecor.map((decor, index) => ({ id: String(decor.id || `decor_${index + 1}`), tile: String(decor.tile || "livingroom"), label: String(decor.label || "Living Room Decor"), note: String(decor.note || "") })).slice(0, 24) : fallback.roomDecor,
    recentActivity: Array.isArray(source.recentActivity) ? source.recentActivity.map((entry, index) => ({ id: String(entry.id || `living_activity_${index + 1}`), at: String(entry.at || "unknown"), text: String(entry.text || "activity") })).slice(-50) : fallback.recentActivity
  };
}

function normalizeCouchCoopSessions(sessions = {}, room = state.bbsLivingRoom, shelf = state.gameShelf) {
  const fallback = buildDemoCouchCoopSessions();
  const source = sessions && typeof sessions === "object" && !Array.isArray(sessions) ? sessions : fallback;
  const modeIds = new Set((room?.modes || []).map(mode => mode.id));
  const gameIds = new Set((shelf?.entries || []).map(game => game.id));
  const normalized = (Array.isArray(source.sessions) && source.sessions.length ? source.sessions : fallback.sessions).map((session, index) => ({
    id: String(session.id || `couch_session_${index + 1}`),
    roomCode: String(session.roomCode || `ROOM-${index + 1}`),
    title: String(session.title || `Co-Play Session ${index + 1}`),
    gameId: gameIds.has(session.gameId) ? String(session.gameId) : ((shelf?.entries || [])[0]?.id || ""),
    modeId: modeIds.has(session.modeId) ? String(session.modeId) : ((room?.modes || [])[0]?.id || ""),
    host: String(session.host || "Host"),
    status: ["draft", "planned", "open", "active", "closed", "exported"].includes(session.status) ? session.status : "draft",
    players: Array.isArray(session.players) ? session.players.map((player, i) => ({ name: String(player.name || `Player ${i + 1}`), role: String(player.role || "player"), seat: Math.max(1, parseInt(player.seat, 10) || i + 1) })).slice(0, 8) : [],
    spectators: Math.max(0, parseInt(session.spectators, 10) || 0),
    saveSlotPolicy: String(session.saveSlotPolicy || "host-only writes"),
    scorePolicy: String(session.scorePolicy || "export scorecard"),
    notes: String(session.notes || "")
  })).slice(0, 32);
  return { activeSessionId: normalized.some(session => session.id === source.activeSessionId) ? String(source.activeSessionId) : normalized[0]?.id || "", inviteFormat: String(source.inviteFormat || fallback.inviteFormat), sessions: normalized, exportedInvites: Array.isArray(source.exportedInvites) ? source.exportedInvites.map((invite, index) => ({ id: String(invite.id || `invite_${index + 1}`), sessionId: String(invite.sessionId || ""), exportedAt: String(invite.exportedAt || "unknown"), roomCode: String(invite.roomCode || "") })).slice(-50) : [] };
}

function normalizeSignalWheel(wheel = {}) {
  const fallback = buildDemoSignalWheel();
  const source = wheel && typeof wheel === "object" && !Array.isArray(wheel) ? wheel : fallback;
  const signals = (Array.isArray(source.signals) && source.signals.length ? source.signals : fallback.signals).map((signal, index) => ({
    id: String(signal.id || `sig_${index + 1}`), label: String(signal.label || `Signal ${index + 1}`), emoji: String(signal.emoji || "•"), meaning: String(signal.meaning || "Preset signal."), category: String(signal.category || "status"), cooldownSeconds: Math.max(0, parseInt(signal.cooldownSeconds, 10) || 0)
  })).slice(0, 24);
  return { activeSignalId: signals.some(signal => signal.id === source.activeSignalId) ? String(source.activeSignalId) : signals[0]?.id || "", noChatReason: String(source.noChatReason || fallback.noChatReason), signals, recentPings: Array.isArray(source.recentPings) ? source.recentPings.map((ping, index) => ({ id: String(ping.id || `ping_${index + 1}`), signalId: signals.some(sig => sig.id === ping.signalId) ? String(ping.signalId) : signals[0]?.id || "", sender: String(ping.sender || "Player"), at: String(ping.at || "unknown"), context: String(ping.context || "") })).slice(-60) : fallback.recentPings };
}

function normalizeLivingRoomSafety(safety = {}) {
  const fallback = buildDemoLivingRoomSafety();
  const source = safety && typeof safety === "object" && !Array.isArray(safety) ? safety : fallback;
  return {
    noFreeTextChat: source.noFreeTextChat !== false,
    defaultVisibility: String(source.defaultVisibility || fallback.defaultVisibility),
    moderationMode: String(source.moderationMode || fallback.moderationMode),
    policies: Array.isArray(source.policies) ? source.policies.map((policy, index) => ({ id: String(policy.id || `safety_${index + 1}`), label: String(policy.label || `Safety Policy ${index + 1}`), status: String(policy.status || "draft"), note: String(policy.note || "") })).slice(0, 32) : fallback.policies,
    allowedInteractions: Array.isArray(source.allowedInteractions) ? source.allowedInteractions.map(String).filter(Boolean).slice(0, 32) : fallback.allowedInteractions,
    blockedInteractions: Array.isArray(source.blockedInteractions) ? source.blockedInteractions.map(String).filter(Boolean).slice(0, 32) : fallback.blockedInteractions
  };
}

function activeLivingMode() {
  state.bbsLivingRoom = normalizeBbsLivingRoom(state.bbsLivingRoom, state.bbsNetwork);
  return state.bbsLivingRoom.modes.find(mode => mode.id === state.bbsLivingRoom.activeModeId) || state.bbsLivingRoom.modes[0];
}
function activeCouchSession() {
  state.couchCoopSessions = normalizeCouchCoopSessions(state.couchCoopSessions, state.bbsLivingRoom, state.gameShelf);
  return state.couchCoopSessions.sessions.find(session => session.id === state.couchCoopSessions.activeSessionId) || state.couchCoopSessions.sessions[0];
}
function activeSignal() {
  state.signalWheel = normalizeSignalWheel(state.signalWheel);
  return state.signalWheel.signals.find(signal => signal.id === state.signalWheel.activeSignalId) || state.signalWheel.signals[0];
}

function renderLivingRoomPanel() {
  if (!el.livingRoomPanel) return;
  state.bbsLivingRoom = normalizeBbsLivingRoom(state.bbsLivingRoom, state.bbsNetwork);
  const mode = activeLivingMode();
  const modes = state.bbsLivingRoom.modes.map(item => `<article class="suite-card ${item.id === state.bbsLivingRoom.activeModeId ? "active" : ""}"><small>${escapeHtml(item.kind)} · ${escapeHtml(item.status)} · ${item.maxPlayers}P/${item.maxSpectators}S</small><strong>${escapeHtml(item.name)}</strong><p>${escapeHtml(item.description)}</p></article>`).join("");
  const decor = state.bbsLivingRoom.roomDecor.map(item => `<span class="mini-pill">${escapeHtml(item.label)}</span>`).join("");
  el.livingRoomPanel.innerHTML = `<article class="suite-card active"><small>${state.bbsLivingRoom.noChatDesign ? "no-chat" : "chat-enabled"} · ${escapeHtml(state.bbsLivingRoom.roomCodePolicy)}</small><strong>${escapeHtml(state.bbsLivingRoom.roomName)}</strong><p>${escapeHtml(state.bbsLivingRoom.networkBoundary)}</p><p>Active mode: ${escapeHtml(mode?.name || "none")}</p><div class="mini-pill-row">${decor}</div></article>${modes}`;
}
function renderCouchSessionPanel() {
  if (!el.couchSessionPanel) return;
  state.couchCoopSessions = normalizeCouchCoopSessions(state.couchCoopSessions, state.bbsLivingRoom, state.gameShelf);
  const cards = state.couchCoopSessions.sessions.map(session => `<article class="suite-card ${session.id === state.couchCoopSessions.activeSessionId ? "active" : ""}"><small>${escapeHtml(session.roomCode)} · ${escapeHtml(session.status)} · ${escapeHtml(session.modeId)}</small><strong>${escapeHtml(session.title)}</strong><p>${escapeHtml(session.notes)}</p><div class="mini-pill-row"><span class="mini-pill">${session.players.length} player(s)</span><span class="mini-pill">${session.spectators} spectator(s)</span><span class="mini-pill">${escapeHtml(session.saveSlotPolicy)}</span></div></article>`).join("");
  el.couchSessionPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.couchCoopSessions.inviteFormat)}</small><strong>${state.couchCoopSessions.sessions.length} co-play session(s)</strong><p>Invite/export sessions for watch parties, turn-table co-play, playtest couches, and score runs.</p></article>${cards}`;
}
function renderSignalWheelPanel() {
  if (!el.signalWheelPanel) return;
  state.signalWheel = normalizeSignalWheel(state.signalWheel);
  const active = activeSignal();
  const signals = state.signalWheel.signals.map(signal => `<button class="signal-chip ${signal.id === state.signalWheel.activeSignalId ? "active" : ""}" data-id="${escapeAttr(signal.id)}"><span>${escapeHtml(signal.emoji)}</span><strong>${escapeHtml(signal.label)}</strong><small>${escapeHtml(signal.category)}</small></button>`).join("");
  const pings = state.signalWheel.recentPings.slice(-5).reverse().map(ping => `<span class="mini-pill">${escapeHtml(ping.sender)}: ${escapeHtml(state.signalWheel.signals.find(sig => sig.id === ping.signalId)?.label || ping.signalId)}</span>`).join("");
  el.signalWheelPanel.innerHTML = `<article class="suite-card active"><small>No free-text chat</small><strong>${escapeHtml(active?.emoji || "•")} ${escapeHtml(active?.label || "Signal")}</strong><p>${escapeHtml(state.signalWheel.noChatReason)}</p><div class="signal-grid">${signals}</div><div class="mini-pill-row">${pings}</div></article>`;
  el.signalWheelPanel.querySelectorAll(".signal-chip").forEach(btn => btn.addEventListener("click", () => { pushUndo(); state.signalWheel.activeSignalId = btn.dataset.id; renderAll(`Signal selected: ${activeSignal()?.label || "signal"}.`); }));
}
function renderLivingRoomSafetyPanel() {
  if (!el.livingRoomSafetyPanel) return;
  state.livingRoomSafety = normalizeLivingRoomSafety(state.livingRoomSafety);
  const policies = state.livingRoomSafety.policies.map(policy => `<article class="suite-card ${policy.status === "locked" ? "ready" : ""}"><small>${escapeHtml(policy.status)}</small><strong>${escapeHtml(policy.label)}</strong><p>${escapeHtml(policy.note)}</p></article>`).join("");
  const allowed = state.livingRoomSafety.allowedInteractions.map(x => `<span class="mini-pill">✓ ${escapeHtml(x)}</span>`).join("");
  const blocked = state.livingRoomSafety.blockedInteractions.map(x => `<span class="mini-pill">✕ ${escapeHtml(x)}</span>`).join("");
  el.livingRoomSafetyPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.livingRoomSafety.defaultVisibility)} · ${escapeHtml(state.livingRoomSafety.moderationMode)}</small><strong>${state.livingRoomSafety.noFreeTextChat ? "No free-text chat by design" : "Chat enabled"}</strong><p>The Living Room keeps co-play simple with preset signals, invite-only sessions, host control, and protected save boundaries.</p><div class="mini-pill-row">${allowed}${blocked}</div></article>${policies}`;
}

function cycleLivingRoomMode() {
  pushUndo();
  state.bbsLivingRoom = normalizeBbsLivingRoom(state.bbsLivingRoom, state.bbsNetwork);
  const ids = state.bbsLivingRoom.modes.map(mode => mode.id);
  const index = Math.max(0, ids.indexOf(state.bbsLivingRoom.activeModeId));
  state.bbsLivingRoom.activeModeId = ids[(index + 1) % ids.length] || "";
  renderAll(`Living Room mode selected: ${activeLivingMode()?.name || "none"}.`);
}
function createCouchSession() {
  pushUndo();
  state.couchCoopSessions = normalizeCouchCoopSessions(state.couchCoopSessions, state.bbsLivingRoom, state.gameShelf);
  const mode = activeLivingMode();
  const activeGame = state.gameShelf?.entries?.find(entry => entry.id === state.gameShelf.activeGameId) || state.gameShelf?.entries?.[0];
  const id = uniqueId("couch_session", state.couchCoopSessions.sessions.map(session => session.id));
  const code = `${slugify(activeGame?.title || state.meta.title).slice(0, 6).toUpperCase()}-${Math.floor(100 + Math.random() * 900)}`;
  state.couchCoopSessions.sessions.unshift({ id, roomCode: code, title: `${activeGame?.title || state.meta.title} — ${mode?.name || "Co-Play"}`, gameId: activeGame?.id || "", modeId: mode?.id || "", host: "Tal-Aren-Vox", status: "draft", players: [{ name: "Host", role: "driver", seat: 1 }], spectators: 0, saveSlotPolicy: "host-only writes; imported sessions cannot overwrite saves", scorePolicy: "export scorecard after session", notes: "No chat. Use signal wheel only." });
  state.couchCoopSessions.activeSessionId = id;
  state.bbsLivingRoom.recentActivity.push({ id: uniqueId("living_activity", state.bbsLivingRoom.recentActivity.map(a => a.id)), at: new Date().toISOString(), text: `Created co-play session ${code}.` });
  renderAll("Created a no-chat couch co-play session draft.");
}
function sendSignalPing() {
  pushUndo();
  state.signalWheel = normalizeSignalWheel(state.signalWheel);
  const signal = activeSignal();
  state.signalWheel.recentPings.push({ id: uniqueId("ping", state.signalWheel.recentPings.map(p => p.id)), signalId: signal?.id || "", sender: "Local Player", at: new Date().toISOString(), context: activeCouchSession()?.title || "Living Room" });
  renderAll(`Sent signal: ${signal?.label || "signal"}.`);
}
async function exportBbsLivingRoom() {
  state.bbsLivingRoom = normalizeBbsLivingRoom(state.bbsLivingRoom, state.bbsNetwork);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.bbs-living-room", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, bbsLivingRoom: state.bbsLivingRoom, boundary: "Living Room is a no-chat co-play manifest foundation. Actual live online play requires a future relay/WebRTC/hosted BBS layer." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.bbs-living-room.v3.2.json`);
  log("Exported BBS Living Room JSON.");
}
async function exportCouchSessionInvite() {
  state.couchCoopSessions = normalizeCouchCoopSessions(state.couchCoopSessions, state.bbsLivingRoom, state.gameShelf);
  const session = activeCouchSession();
  if (session) state.couchCoopSessions.exportedInvites.push({ id: uniqueId("invite", state.couchCoopSessions.exportedInvites.map(i => i.id)), sessionId: session.id, exportedAt: new Date().toISOString(), roomCode: session.roomCode });
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.couch-session-invite", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, inviteFormat: state.couchCoopSessions.inviteFormat, session, noChat: state.livingRoomSafety?.noFreeTextChat === true, boundary: "Invite manifest only. It does not connect to an online server in this alpha." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.couch-session-invite.v3.2.json`);
  renderAll("Exported Couch Session Invite JSON.");
}
async function exportSignalWheel() {
  state.signalWheel = normalizeSignalWheel(state.signalWheel);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.signal-wheel", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, signalWheel: state.signalWheel, noChatReason: state.signalWheel.noChatReason };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.signal-wheel.v3.2.json`);
  log("Exported Signal Wheel JSON.");
}
async function exportLivingRoomSafety() {
  state.livingRoomSafety = normalizeLivingRoomSafety(state.livingRoomSafety);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.living-room-safety", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, livingRoomSafety: state.livingRoomSafety, boundary: "Safety settings are prototype metadata; hosted enforcement requires a future network layer." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.living-room-safety.v3.2.json`);
  log("Exported Living Room Safety JSON.");
}

function validateBbsLivingRoomBrowser(room, network, errors) {
  if (!room || typeof room !== "object" || Array.isArray(room)) { errors.push("bbsLivingRoom must be an object."); return; }
  const ids = new Set((room.modes || []).map(mode => mode.id));
  if (!Array.isArray(room.modes) || !room.modes.length) errors.push("bbsLivingRoom.modes must be a non-empty array.");
  if (room.activeModeId && !ids.has(room.activeModeId)) errors.push("bbsLivingRoom.activeModeId must reference a mode.");
  if (room.noChatDesign !== true) errors.push("bbsLivingRoom.noChatDesign should be true for this no-chat alpha.");
}
function validateCouchCoopSessionsBrowser(sessions, room, shelf, errors) {
  if (!sessions || typeof sessions !== "object" || Array.isArray(sessions)) { errors.push("couchCoopSessions must be an object."); return; }
  const ids = new Set((sessions.sessions || []).map(session => session.id));
  const modeIds = new Set((room?.modes || []).map(mode => mode.id));
  const gameIds = new Set((shelf?.entries || []).map(game => game.id));
  if (!Array.isArray(sessions.sessions) || !sessions.sessions.length) errors.push("couchCoopSessions.sessions must be a non-empty array.");
  if (sessions.activeSessionId && !ids.has(sessions.activeSessionId)) errors.push("couchCoopSessions.activeSessionId must reference a session.");
  (sessions.sessions || []).forEach((session, index) => { if (session.modeId && !modeIds.has(session.modeId)) errors.push(`couchCoopSessions.sessions[${index}].modeId references missing mode '${session.modeId}'.`); if (session.gameId && !gameIds.has(session.gameId)) errors.push(`couchCoopSessions.sessions[${index}].gameId references missing shelf game '${session.gameId}'.`); });
}
function validateSignalWheelBrowser(wheel, errors) {
  if (!wheel || typeof wheel !== "object" || Array.isArray(wheel)) { errors.push("signalWheel must be an object."); return; }
  const ids = new Set((wheel.signals || []).map(signal => signal.id));
  if (!Array.isArray(wheel.signals) || !wheel.signals.length) errors.push("signalWheel.signals must be a non-empty array.");
  if (wheel.activeSignalId && !ids.has(wheel.activeSignalId)) errors.push("signalWheel.activeSignalId must reference a signal.");
}
function validateLivingRoomSafetyBrowser(safety, errors) {
  if (!safety || typeof safety !== "object" || Array.isArray(safety)) { errors.push("livingRoomSafety must be an object."); return; }
  if (safety.noFreeTextChat !== true) errors.push("livingRoomSafety.noFreeTextChat must be true.");
  if (!Array.isArray(safety.policies) || !safety.policies.length) errors.push("livingRoomSafety.policies must be a non-empty array.");
}


function buildDemoRelayBlueprint() {
  return {
    activeRelayId: "relay_private_bbs",
    relayBoundary: "Live networking is not enabled in this static alpha. This blueprint defines the future relay contract for invite-only no-chat co-play.",
    relays: [
      { id: "relay_private_bbs", name: "Private BBS Relay", kind: "hosted-relay", status: "blueprint", transport: "websocket-or-server-sent-events", privacy: "invite-only room codes", notes: "Future Node/Netlify/Pages-compatible relay can pass session snapshots, signal pings, and score submissions only." },
      { id: "relay_webrtc_lan", name: "Friend Code WebRTC", kind: "peer-relay", status: "research", transport: "webrtc-datachannel", privacy: "friend-code handoff", notes: "Potential low-server option; requires TURN/STUN planning and safety testing." },
      { id: "relay_async_packet", name: "Async Packet Exchange", kind: "offline-export", status: "ready", transport: "json-import-export", privacy: "manual sharing", notes: "Works today through exported invite, score, replay, and snapshot packets." }
    ],
    handshakeSteps: [
      "Host creates invite-only room code.",
      "Guest imports or joins with room code.",
      "Relay confirms game id, release cut, rights status, and no-chat policy.",
      "Host sends initial session snapshot.",
      "Guests send signal-wheel pings and score packets only.",
      "Replay receipt closes the session."
    ],
    packetTypes: ["invite", "snapshot", "signal_ping", "score_packet", "host_handoff", "replay_receipt"],
    exportedBlueprints: []
  };
}

