function normalizeRelayBlueprint(blueprint = {}, room = state.bbsLivingRoom) {
  const fallback = buildDemoRelayBlueprint();
  const source = blueprint && typeof blueprint === "object" && !Array.isArray(blueprint) ? blueprint : fallback;
  const relays = (Array.isArray(source.relays) && source.relays.length ? source.relays : fallback.relays).map((relay, index) => ({
    id: String(relay.id || `relay_${index + 1}`), name: String(relay.name || `Relay ${index + 1}`), kind: String(relay.kind || "hosted-relay"), status: String(relay.status || "blueprint"), transport: String(relay.transport || "json-import-export"), privacy: String(relay.privacy || "invite-only"), notes: String(relay.notes || "")
  })).slice(0, 16);
  return {
    activeRelayId: relays.some(relay => relay.id === source.activeRelayId) ? String(source.activeRelayId) : relays[0]?.id || "",
    relayBoundary: String(source.relayBoundary || fallback.relayBoundary),
    relays,
    handshakeSteps: Array.isArray(source.handshakeSteps) ? source.handshakeSteps.map(String).filter(Boolean).slice(0, 24) : fallback.handshakeSteps,
    packetTypes: Array.isArray(source.packetTypes) ? source.packetTypes.map(String).filter(Boolean).slice(0, 24) : fallback.packetTypes,
    exportedBlueprints: Array.isArray(source.exportedBlueprints) ? source.exportedBlueprints.map((entry, index) => ({ id: String(entry.id || `relay_export_${index + 1}`), relayId: String(entry.relayId || ""), exportedAt: String(entry.exportedAt || "unknown") })).slice(-50) : []
  };
}

function normalizeSessionSync(sync = {}, sessions = state.couchCoopSessions, scenes = state.scenes) {
  const fallback = buildDemoSessionSync();
  const source = sync && typeof sync === "object" && !Array.isArray(sync) ? sync : fallback;
  const sessionIds = new Set((sessions?.sessions || []).map(session => session.id));
  const sceneIds = new Set((scenes || []).map(scene => scene.id));
  const snapshots = (Array.isArray(source.snapshots) && source.snapshots.length ? source.snapshots : fallback.snapshots).map((snap, index) => ({
    id: String(snap.id || `snapshot_${index + 1}`), sessionId: sessionIds.has(snap.sessionId) ? String(snap.sessionId) : ((sessions?.sessions || [])[0]?.id || ""), sceneId: sceneIds.has(snap.sceneId) ? String(snap.sceneId) : ((scenes || [])[0]?.id || ""),
    player: { x: Math.max(0, Math.min(MAP_W - 1, parseInt(snap.player?.x, 10) || 0)), y: Math.max(0, Math.min(MAP_H - 1, parseInt(snap.player?.y, 10) || 0)) },
    stats: { supplies: parseInt(snap.stats?.supplies, 10) || 0, morale: parseInt(snap.stats?.morale, 10) || 0, wonder: parseInt(snap.stats?.wonder, 10) || 0, coherence: parseInt(snap.stats?.coherence, 10) || 0 },
    signalQueue: Array.isArray(snap.signalQueue) ? snap.signalQueue.map(String).slice(-12) : [], status: String(snap.status || "draft"), checksumNote: String(snap.checksumNote || "")
  })).slice(-40);
  return {
    activeSnapshotId: snapshots.some(snap => snap.id === source.activeSnapshotId) ? String(source.activeSnapshotId) : snapshots[0]?.id || "",
    syncMode: String(source.syncMode || fallback.syncMode),
    tickPolicy: String(source.tickPolicy || fallback.tickPolicy),
    snapshots,
    allowedMessages: Array.isArray(source.allowedMessages) ? source.allowedMessages.map((msg, index) => ({ type: String(msg.type || `message_${index + 1}`), direction: String(msg.direction || "host-to-guest"), payload: String(msg.payload || "packet"), safety: String(msg.safety || "bounded") })).slice(0, 32) : fallback.allowedMessages,
    conflictRules: Array.isArray(source.conflictRules) ? source.conflictRules.map(String).filter(Boolean).slice(0, 24) : fallback.conflictRules,
    exportedSnapshots: Array.isArray(source.exportedSnapshots) ? source.exportedSnapshots.map((entry, index) => ({ id: String(entry.id || `snapshot_export_${index + 1}`), snapshotId: String(entry.snapshotId || ""), exportedAt: String(entry.exportedAt || "unknown") })).slice(-50) : []
  };
}

function normalizeHostHandoff(handoff = {}, sessions = state.couchCoopSessions) {
  const fallback = buildDemoHostHandoff();
  const source = handoff && typeof handoff === "object" && !Array.isArray(handoff) ? handoff : fallback;
  const sessionIds = new Set((sessions?.sessions || []).map(session => session.id));
  const handoffs = (Array.isArray(source.handoffs) && source.handoffs.length ? source.handoffs : fallback.handoffs).map((item, index) => ({
    id: String(item.id || `handoff_${index + 1}`), sessionId: sessionIds.has(item.sessionId) ? String(item.sessionId) : ((sessions?.sessions || [])[0]?.id || ""), fromHost: String(item.fromHost || "Host"), toHost: String(item.toHost || "Backup Host"), status: String(item.status || "draft"), requiredSignals: Array.isArray(item.requiredSignals) ? item.requiredSignals.map(String).slice(0, 8) : [], authority: String(item.authority || "room-control only"), note: String(item.note || "")
  })).slice(0, 32);
  return { activeHandoffId: handoffs.some(item => item.id === source.activeHandoffId) ? String(source.activeHandoffId) : handoffs[0]?.id || "", policy: String(source.policy || fallback.policy), handoffs, authorityRules: Array.isArray(source.authorityRules) ? source.authorityRules.map(String).filter(Boolean).slice(0, 24) : fallback.authorityRules };
}

function normalizeReplayReceipts(replay = {}, sessions = state.couchCoopSessions, scenes = state.scenes) {
  const fallback = buildDemoReplayReceipts();
  const source = replay && typeof replay === "object" && !Array.isArray(replay) ? replay : fallback;
  const sessionIds = new Set((sessions?.sessions || []).map(session => session.id));
  const sceneIds = new Set((scenes || []).map(scene => scene.id));
  const receipts = (Array.isArray(source.receipts) && source.receipts.length ? source.receipts : fallback.receipts).map((receipt, index) => ({ id: String(receipt.id || `replay_${index + 1}`), sessionId: sessionIds.has(receipt.sessionId) ? String(receipt.sessionId) : ((sessions?.sessions || [])[0]?.id || ""), gameId: String(receipt.gameId || ""), sceneId: sceneIds.has(receipt.sceneId) ? String(receipt.sceneId) : ((scenes || [])[0]?.id || ""), routeName: String(receipt.routeName || `Replay ${index + 1}`), status: String(receipt.status || "draft"), score: parseInt(receipt.score, 10) || 0, duration: String(receipt.duration || "00:00:00"), badges: Array.isArray(receipt.badges) ? receipt.badges.map(String).slice(0, 12) : [], summary: String(receipt.summary || "") })).slice(-50);
  const receiptIds = new Set(receipts.map(r => r.id));
  return { activeReceiptId: receipts.some(r => r.id === source.activeReceiptId) ? String(source.activeReceiptId) : receipts[0]?.id || "", receiptType: String(source.receiptType || fallback.receiptType), receipts, timelineEvents: Array.isArray(source.timelineEvents) ? source.timelineEvents.map((event, index) => ({ id: String(event.id || `replay_event_${index + 1}`), receiptId: receiptIds.has(event.receiptId) ? String(event.receiptId) : receipts[0]?.id || "", at: String(event.at || "00:00:00"), kind: String(event.kind || "note"), text: String(event.text || "") })).slice(-80) : fallback.timelineEvents, exportPolicy: String(source.exportPolicy || fallback.exportPolicy) };
}

function activeRelayBlueprint() { state.relayBlueprint = normalizeRelayBlueprint(state.relayBlueprint, state.bbsLivingRoom); return state.relayBlueprint.relays.find(relay => relay.id === state.relayBlueprint.activeRelayId) || state.relayBlueprint.relays[0]; }
function activeSessionSnapshot() { state.sessionSync = normalizeSessionSync(state.sessionSync, state.couchCoopSessions, state.scenes); return state.sessionSync.snapshots.find(snap => snap.id === state.sessionSync.activeSnapshotId) || state.sessionSync.snapshots[0]; }
function activeHostHandoff() { state.hostHandoff = normalizeHostHandoff(state.hostHandoff, state.couchCoopSessions); return state.hostHandoff.handoffs.find(item => item.id === state.hostHandoff.activeHandoffId) || state.hostHandoff.handoffs[0]; }
function activeReplayReceipt() { state.replayReceipts = normalizeReplayReceipts(state.replayReceipts, state.couchCoopSessions, state.scenes); return state.replayReceipts.receipts.find(item => item.id === state.replayReceipts.activeReceiptId) || state.replayReceipts.receipts[0]; }

function renderRelayBlueprintPanel() {
  if (!el.relayBlueprintPanel) return;
  state.relayBlueprint = normalizeRelayBlueprint(state.relayBlueprint, state.bbsLivingRoom);
  const active = activeRelayBlueprint();
  const relays = state.relayBlueprint.relays.map(relay => `<article class="suite-card ${relay.id === state.relayBlueprint.activeRelayId ? "active" : ""}"><small>${escapeHtml(relay.kind)} · ${escapeHtml(relay.status)} · ${escapeHtml(relay.transport)}</small><strong>${escapeHtml(relay.name)}</strong><p>${escapeHtml(relay.notes)}</p></article>`).join("");
  const packets = state.relayBlueprint.packetTypes.map(type => `<span class="mini-pill">${escapeHtml(type)}</span>`).join("");
  el.relayBlueprintPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(active?.privacy || "invite-only")}</small><strong>${escapeHtml(active?.name || "Relay Blueprint")}</strong><p>${escapeHtml(state.relayBlueprint.relayBoundary)}</p><div class="mini-pill-row">${packets}</div></article>${relays}`;
}

function renderSessionSyncPanel() {
  if (!el.sessionSyncPanel) return;
  state.sessionSync = normalizeSessionSync(state.sessionSync, state.couchCoopSessions, state.scenes);
  const snapshots = state.sessionSync.snapshots.map(snap => `<article class="suite-card ${snap.id === state.sessionSync.activeSnapshotId ? "active" : ""}"><small>${escapeHtml(snap.status)} · ${escapeHtml(snap.sceneId)} · ${escapeHtml(snap.sessionId)}</small><strong>${escapeHtml(snap.id)}</strong><p>Player (${snap.player.x}, ${snap.player.y}) · Wonder ${snap.stats.wonder} · Signals ${snap.signalQueue.length}</p><p>${escapeHtml(snap.checksumNote)}</p></article>`).join("");
  const rules = state.sessionSync.conflictRules.map(rule => `<span class="mini-pill">${escapeHtml(rule)}</span>`).join("");
  el.sessionSyncPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.sessionSync.syncMode)}</small><strong>Session Sync Snapshots</strong><p>${escapeHtml(state.sessionSync.tickPolicy)}</p><div class="mini-pill-row">${rules}</div></article>${snapshots}`;
}

function renderHostHandoffPanel() {
  if (!el.hostHandoffPanel) return;
  state.hostHandoff = normalizeHostHandoff(state.hostHandoff, state.couchCoopSessions);
  const rules = state.hostHandoff.authorityRules.map(rule => `<span class="mini-pill">${escapeHtml(rule)}</span>`).join("");
  const cards = state.hostHandoff.handoffs.map(item => `<article class="suite-card ${item.id === state.hostHandoff.activeHandoffId ? "active" : ""}"><small>${escapeHtml(item.status)} · ${escapeHtml(item.sessionId)}</small><strong>${escapeHtml(item.fromHost)} → ${escapeHtml(item.toHost)}</strong><p>${escapeHtml(item.authority)}</p><p>${escapeHtml(item.note)}</p></article>`).join("");
  el.hostHandoffPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.hostHandoff.policy)}</small><strong>Host Handoff Authority</strong><p>Transfers room-control authority without transferring save ownership.</p><div class="mini-pill-row">${rules}</div></article>${cards}`;
}

function renderReplayReceiptPanel() {
  if (!el.replayReceiptPanel) return;
  state.replayReceipts = normalizeReplayReceipts(state.replayReceipts, state.couchCoopSessions, state.scenes);
  const receipts = state.replayReceipts.receipts.map(receipt => `<article class="suite-card ${receipt.id === state.replayReceipts.activeReceiptId ? "active" : ""}"><small>${escapeHtml(receipt.status)} · score ${receipt.score} · ${escapeHtml(receipt.duration)}</small><strong>${escapeHtml(receipt.routeName)}</strong><p>${escapeHtml(receipt.summary)}</p><div class="mini-pill-row">${receipt.badges.map(b => `<span class="mini-pill">${escapeHtml(b)}</span>`).join("")}</div></article>`).join("");
  const timeline = state.replayReceipts.timelineEvents.slice(-5).map(event => `<span class="mini-pill">${escapeHtml(event.at)} ${escapeHtml(event.kind)}</span>`).join("");
  el.replayReceiptPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.replayReceipts.receiptType)}</small><strong>Replay Receipts</strong><p>${escapeHtml(state.replayReceipts.exportPolicy)}</p><div class="mini-pill-row">${timeline}</div></article>${receipts}`;
}

async function exportRelayBlueprint() {
  state.relayBlueprint = normalizeRelayBlueprint(state.relayBlueprint, state.bbsLivingRoom);
  const relay = activeRelayBlueprint();
  state.relayBlueprint.exportedBlueprints.push({ id: uniqueId("relay_export", state.relayBlueprint.exportedBlueprints.map(x => x.id)), relayId: relay?.id || "", exportedAt: new Date().toISOString() });
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.live-relay-blueprint", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, relayBlueprint: state.relayBlueprint, noChatPolicy: state.livingRoomSafety?.noFreeTextChat === true, boundary: "Blueprint only. Live online co-play still requires a hosted relay, WebRTC layer, or private BBS server." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.live-relay-blueprint.v3.2.json`);
  renderAll("Exported Live Relay Blueprint JSON.");
}

function captureSessionSnapshot() {
  pushUndo();
  state.sessionSync = normalizeSessionSync(state.sessionSync, state.couchCoopSessions, state.scenes);
  const session = activeCouchSession();
  const scene = activeScene();
  const id = uniqueId("snapshot", state.sessionSync.snapshots.map(s => s.id));
  state.sessionSync.snapshots.unshift({ id, sessionId: session?.id || "", sceneId: scene?.id || state.activeSceneId, player: { x: state.player.x, y: state.player.y }, stats: { ...state.journey.stats }, signalQueue: (state.signalWheel?.recentPings || []).slice(-6).map(p => p.signalId), status: "captured", checksumNote: "Captured locally for future relay sync testing." });
  state.sessionSync.activeSnapshotId = id;
  renderAll("Captured a session sync snapshot.");
}

async function exportSessionSync() {
  state.sessionSync = normalizeSessionSync(state.sessionSync, state.couchCoopSessions, state.scenes);
  const snapshot = activeSessionSnapshot();
  if (snapshot) state.sessionSync.exportedSnapshots.push({ id: uniqueId("snapshot_export", state.sessionSync.exportedSnapshots.map(x => x.id)), snapshotId: snapshot.id, exportedAt: new Date().toISOString() });
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.session-sync", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, sessionSync: state.sessionSync, boundary: "Session sync snapshots are local manifests. They are not a real-time network transport yet." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.session-sync.v3.2.json`);
  renderAll("Exported Session Sync JSON.");
}

function createHostHandoff() {
  pushUndo();
  state.hostHandoff = normalizeHostHandoff(state.hostHandoff, state.couchCoopSessions);
  const session = activeCouchSession();
  const id = uniqueId("handoff", state.hostHandoff.handoffs.map(h => h.id));
  state.hostHandoff.handoffs.unshift({ id, sessionId: session?.id || "", fromHost: session?.host || "Host", toHost: "Backup Host", status: "draft", requiredSignals: ["sig_pause", "sig_ready"], authority: "room-control only; no save ownership transfer", note: "New host handoff draft created from the active couch session." });
  state.hostHandoff.activeHandoffId = id;
  renderAll("Created a host handoff draft.");
}

async function exportHostHandoff() {
  state.hostHandoff = normalizeHostHandoff(state.hostHandoff, state.couchCoopSessions);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.host-handoff", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, hostHandoff: state.hostHandoff, boundary: "Host handoff is authority metadata only until a live relay implements enforcement." };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.host-handoff.v3.2.json`);
  log("Exported Host Handoff JSON.");
}

function recordReplayReceipt() {
  pushUndo();
  state.replayReceipts = normalizeReplayReceipts(state.replayReceipts, state.couchCoopSessions, state.scenes);
  const session = activeCouchSession();
  const scene = activeScene();
  const id = uniqueId("replay", state.replayReceipts.receipts.map(r => r.id));
  const score = (state.journey.stats.wonder * 100) + (state.journey.stats.morale * 10) + state.inventory.length;
  state.replayReceipts.receipts.unshift({ id, sessionId: session?.id || "", gameId: session?.gameId || state.gameShelf?.activeGameId || "", sceneId: scene?.id || state.activeSceneId, routeName: `${scene?.name || "Route"} Replay`, status: "draft", score, duration: "00:10:00", badges: ["local-replay", "no-chat"], summary: "Local replay receipt captured from current project stats, scene, and active couch session." });
  state.replayReceipts.activeReceiptId = id;
  state.replayReceipts.timelineEvents.push({ id: uniqueId("replay_evt", state.replayReceipts.timelineEvents.map(e => e.id)), receiptId: id, at: new Date().toISOString(), kind: "capture", text: `Replay receipt captured for ${scene?.name || "active scene"}.` });
  renderAll("Recorded a replay receipt.");
}

async function exportReplayReceipts() {
  state.replayReceipts = normalizeReplayReceipts(state.replayReceipts, state.couchCoopSessions, state.scenes);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.replay-receipts", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, replayReceipts: state.replayReceipts, noChatReceipt: true };
  downloadBlob(new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" }), `${slugify(state.meta.title)}.replay-receipts.v3.2.json`);
  log("Exported Replay Receipts JSON.");
}

function validateRelayBlueprintBrowser(blueprint, errors) {
  if (!blueprint || typeof blueprint !== "object" || Array.isArray(blueprint)) { errors.push("relayBlueprint must be an object."); return; }
  const ids = new Set((blueprint.relays || []).map(relay => relay.id));
  if (!Array.isArray(blueprint.relays) || !blueprint.relays.length) errors.push("relayBlueprint.relays must be a non-empty array.");
  if (blueprint.activeRelayId && !ids.has(blueprint.activeRelayId)) errors.push("relayBlueprint.activeRelayId must reference a relay.");
  if (!Array.isArray(blueprint.packetTypes) || !blueprint.packetTypes.includes("signal_ping")) errors.push("relayBlueprint.packetTypes must include signal_ping.");
}
function validateSessionSyncBrowser(sync, sessions, scenes, errors) {
  if (!sync || typeof sync !== "object" || Array.isArray(sync)) { errors.push("sessionSync must be an object."); return; }
  const ids = new Set((sync.snapshots || []).map(snap => snap.id));
  const sessionIds = new Set((sessions?.sessions || []).map(session => session.id));
  const sceneIds = new Set((scenes || []).map(scene => scene.id));
  if (!Array.isArray(sync.snapshots) || !sync.snapshots.length) errors.push("sessionSync.snapshots must be a non-empty array.");
  if (sync.activeSnapshotId && !ids.has(sync.activeSnapshotId)) errors.push("sessionSync.activeSnapshotId must reference a snapshot.");
  (sync.snapshots || []).forEach((snap, index) => { if (snap.sessionId && !sessionIds.has(snap.sessionId)) errors.push(`sessionSync.snapshots[${index}].sessionId references missing session '${snap.sessionId}'.`); if (snap.sceneId && !sceneIds.has(snap.sceneId)) errors.push(`sessionSync.snapshots[${index}].sceneId references missing scene '${snap.sceneId}'.`); });
}
function validateHostHandoffBrowser(handoff, sessions, errors) {
  if (!handoff || typeof handoff !== "object" || Array.isArray(handoff)) { errors.push("hostHandoff must be an object."); return; }
  const ids = new Set((handoff.handoffs || []).map(item => item.id));
  const sessionIds = new Set((sessions?.sessions || []).map(session => session.id));
  if (!Array.isArray(handoff.handoffs) || !handoff.handoffs.length) errors.push("hostHandoff.handoffs must be a non-empty array.");
  if (handoff.activeHandoffId && !ids.has(handoff.activeHandoffId)) errors.push("hostHandoff.activeHandoffId must reference a handoff.");
  (handoff.handoffs || []).forEach((item, index) => { if (item.sessionId && !sessionIds.has(item.sessionId)) errors.push(`hostHandoff.handoffs[${index}].sessionId references missing session '${item.sessionId}'.`); });
}
function validateReplayReceiptsBrowser(replay, sessions, scenes, errors) {
  if (!replay || typeof replay !== "object" || Array.isArray(replay)) { errors.push("replayReceipts must be an object."); return; }
  const ids = new Set((replay.receipts || []).map(item => item.id));
  const sessionIds = new Set((sessions?.sessions || []).map(session => session.id));
  const sceneIds = new Set((scenes || []).map(scene => scene.id));
  if (!Array.isArray(replay.receipts) || !replay.receipts.length) errors.push("replayReceipts.receipts must be a non-empty array.");
  if (replay.activeReceiptId && !ids.has(replay.activeReceiptId)) errors.push("replayReceipts.activeReceiptId must reference a receipt.");
  (replay.receipts || []).forEach((item, index) => { if (item.sessionId && !sessionIds.has(item.sessionId)) errors.push(`replayReceipts.receipts[${index}].sessionId references missing session '${item.sessionId}'.`); if (item.sceneId && !sceneIds.has(item.sceneId)) errors.push(`replayReceipts.receipts[${index}].sceneId references missing scene '${item.sceneId}'.`); });
}

