  state.relayDeploymentGuide = normalizeRelayDeploymentGuide(state.relayDeploymentGuide);
  const projectHash = await sha256(stableStringify(state));
  const payload = { exportType: "pixelforge.private-relay-deployment-guide", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, relayDeploymentGuide: state.relayDeploymentGuide, boundary: "Deployment guide only; no hosted relay is launched by this static build." };
