function normalizeJamPromptDeck(deck = {}) { const fallback = buildDemoJamPromptDeck(); const source = deck && typeof deck === "object" && !Array.isArray(deck) ? deck : fallback; const list=Array.isArray(source.prompts) && source.prompts.length ? source.prompts : fallback.prompts; const prompts=list.map((p,i)=>({ id:String(p.id||`jam_prompt_${i}`), theme:String(p.theme||"A strange tiny game prompt"), vibe:String(p.vibe||"quirky"), constraints:Array.isArray(p.constraints)?p.constraints.map(String):[], seedLine:String(p.seedLine||"") })); const ids=prompts.map(p=>p.id); return { ...fallback, ...source, prompts, activePromptId:ids.includes(source.activePromptId)?source.activePromptId:prompts[0]?.id||"", drawHistory:Array.isArray(source.drawHistory)?source.drawHistory.map(String):[] }; }
