function renderTinyGameJamPanel() { if (!el.tinyGameJamPanel) return; state.tinyGameJam=normalizeTinyGameJam(state.tinyGameJam); const active=state.tinyGameJam.jams.find(j=>j.id===state.tinyGameJam.activeJamId)||state.tinyGameJam.jams[0]; el.tinyGameJamPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(active?.status||"ready")} · ${state.tinyGameJam.currentTimerMinutes} min</small><strong>${escapeHtml(active?.title||"Tiny Game Jam")}</strong><p>${escapeHtml(active?.theme||"")}</p><div class="mini-pill-row">${(active?.requiredOutputs||[]).map(o=>`<span class="mini-pill">${escapeHtml(o)}</span>`).join("")}</div></article>` + state.tinyGameJam.jams.map(j=>`<article class="suite-card ${j.id===state.tinyGameJam.activeJamId?'active':''}"><small>${escapeHtml(j.status)} · ${j.durationMinutes} min</small><strong>${escapeHtml(j.title)}</strong><p>${escapeHtml(j.theme)}</p><div class="pack-tags"><span>${escapeHtml(j.rewardBadge)}</span></div></article>`).join(""); }
function renderCartridgeTradePanel() { if (!el.cartridgeTradePanel) return; state.cartridgeTradeBoard=normalizeCartridgeTradeBoard(state.cartridgeTradeBoard, state.gameShelf); const b=state.cartridgeTradeBoard; el.cartridgeTradePanel.innerHTML = `<article class="suite-card active"><small>${b.noMoneyPolicy?'no-money trade board':'review policy'}</small><strong>Cartridge Trade Board</strong><p>Trade cartridge packs, asset packs, receipts, and devlog bundles with rights metadata attached.</p><div class="mini-pill-row">${b.tradeRules.map(r=>`<span class="mini-pill">${escapeHtml(r)}</span>`).join("")}</div></article>` + b.trades.map(t=>`<article class="suite-card ${t.id===b.activeTradeId?'active':''}"><small>${escapeHtml(t.status)} · ${escapeHtml(t.kind)}</small><strong>${escapeHtml(t.title)}</strong><p>${escapeHtml(t.note)}</p><div class="pack-tags">${t.includes.map(i=>`<span>${escapeHtml(i)}</span>`).join("")}</div></article>`).join(""); }
function renderJamPromptDeckPanel() { if (!el.jamPromptDeckPanel) return; state.jamPromptDeck=normalizeJamPromptDeck(state.jamPromptDeck); const d=state.jamPromptDeck; const active=d.prompts.find(p=>p.id===d.activePromptId)||d.prompts[0]; el.jamPromptDeckPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(active?.vibe||"jam prompt")}</small><strong>${escapeHtml(active?.theme||"Jam Prompt")}</strong><p>${escapeHtml(active?.seedLine||"")}</p><div class="mini-pill-row">${(active?.constraints||[]).map(c=>`<span class="mini-pill">${escapeHtml(c)}</span>`).join("")}</div></article>` + d.prompts.map(p=>`<article class="suite-card ${p.id===d.activePromptId?'active':''}"><small>${escapeHtml(p.vibe)}</small><strong>${escapeHtml(p.theme)}</strong><p>${escapeHtml(p.seedLine)}</p></article>`).join(""); }
function renderShareReadinessPanel() { if (!el.shareReadinessPanel) return; state.shareReadiness=normalizeShareReadiness(state.shareReadiness, state.cartridgeTradeBoard); const s=state.shareReadiness; el.shareReadinessPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(s.overallStatus)} · score ${s.shareScore}/100</small><strong>Share Readiness</strong><p>Recommended path: ${escapeHtml(s.recommendedSharePath)}</p></article>` + s.checks.map(c=>`<article class="suite-card ${c.passed?'':'active'}"><small>${escapeHtml(c.severity)} · ${c.passed?'passed':'needs review'}</small><strong>${escapeHtml(c.label)}</strong><p>${escapeHtml(c.note)}</p></article>`).join(""); }
function startTinyGameJam() { pushUndo(); state.tinyGameJam=normalizeTinyGameJam(state.tinyGameJam); state.jamPromptDeck=normalizeJamPromptDeck(state.jamPromptDeck); const jam=state.tinyGameJam.jams.find(j=>j.id===state.tinyGameJam.activeJamId)||state.tinyGameJam.jams[0]; jam.status="running"; state.tinyGameJam.currentTimerMinutes=jam.durationMinutes; state.tinyGameJam.jamScore += 36; state.tinyGameJam.lastRunSummary = `Started ${jam.title}: ${jam.theme}`; logPlaytest("tiny-game-jam", state.activeSceneId, state.tinyGameJam.lastRunSummary); renderAll(`Tiny Game Jam started: ${jam.title}.`); }
function prepareCartridgeTradePack() { pushUndo(); state.cartridgeTradeBoard=normalizeCartridgeTradeBoard(state.cartridgeTradeBoard, state.gameShelf); const trade=state.cartridgeTradeBoard.trades.find(t=>t.id===state.cartridgeTradeBoard.activeTradeId)||state.cartridgeTradeBoard.trades[0]; if (trade) { trade.status="ready"; if (!state.cartridgeTradeBoard.exportsPrepared.includes(trade.id)) state.cartridgeTradeBoard.exportsPrepared.push(trade.id); } renderAll(`Prepared trade pack: ${trade?.title || "Cartridge Trade"}.`); }
function drawJamPrompt() { pushUndo(); state.jamPromptDeck=normalizeJamPromptDeck(state.jamPromptDeck); const ids=state.jamPromptDeck.prompts.map(p=>p.id); const i=Math.max(0,ids.indexOf(state.jamPromptDeck.activePromptId)); state.jamPromptDeck.activePromptId=ids[(i+1)%ids.length]||""; const active=state.jamPromptDeck.prompts.find(p=>p.id===state.jamPromptDeck.activePromptId); if (active) state.jamPromptDeck.drawHistory.unshift(active.id); renderAll(`Jam prompt drawn: ${active?.theme || "Prompt"}.`); }
function refreshShareReadiness() { pushUndo(); state.shareReadiness=normalizeShareReadiness(state.shareReadiness, state.cartridgeTradeBoard); state.shareReadiness.lastRefreshed = new Date().toISOString(); renderAll(`Share readiness refreshed: ${state.shareReadiness.overallStatus}.`); }
