function validateJamTradeExperienceBrowser(project, errors) { if (!project?.tinyGameJam?.jams?.length) errors.push("tinyGameJam.jams must be a non-empty array."); if (!project?.cartridgeTradeBoard?.trades?.length) errors.push("cartridgeTradeBoard.trades must be a non-empty array."); if (project?.cartridgeTradeBoard && project.cartridgeTradeBoard.noMoneyPolicy !== true) errors.push("cartridgeTradeBoard.noMoneyPolicy must stay true for v3.2."); if (!project?.jamPromptDeck?.prompts?.length) errors.push("jamPromptDeck.prompts must be a non-empty array."); if (!project?.shareReadiness?.checks?.length) errors.push("shareReadiness.checks must be a non-empty array."); }

function activeWizardStep() { state.startNewCartridgeWizard = normalizeStartNewCartridgeWizard(state.startNewCartridgeWizard); return state.startNewCartridgeWizard.steps.find(step => step.id === state.startNewCartridgeWizard.activeStepId) || state.startNewCartridgeWizard.steps[0]; }
function advanceCartridgeWizard() { state.startNewCartridgeWizard = normalizeStartNewCartridgeWizard(state.startNewCartridgeWizard); const steps = state.startNewCartridgeWizard.steps; const i = Math.max(0, steps.findIndex(step => step.id === state.startNewCartridgeWizard.activeStepId)); steps[i].status = "complete"; const next = steps[(i+1)%steps.length]; next.status = "active"; state.startNewCartridgeWizard.activeStepId = next.id; renderAll(`Cartridge Wizard advanced: ${next.title}.`); }
function generateStarterCartridge() { state.startNewCartridgeWizard = normalizeStartNewCartridgeWizard(state.startNewCartridgeWizard); state.creatorMissions = normalizeCreatorMissions(state.creatorMissions); state.firstCartridgeFlow = normalizeFirstCartridgeFlow(state.firstCartridgeFlow); const mission = state.creatorMissions.missions.find(m => m.id === "mission_first_cartridge"); if (mission) mission.status = "complete"; const flow = state.firstCartridgeFlow.steps.find(s => s.id === "flow_generate_seed"); if (flow) flow.status = "complete"; state.startNewCartridgeWizard.lastGeneratedCartridgeId = "game_journey_parallax"; logPlaytest("cozy-creator", state.activeSceneId, "Generated a cozy starter cartridge kit: scene, NPC, quest, music cue, shelf entry, and AI playtest plan."); renderAll("Starter cartridge kit generated for Journey to the Parallax Institute."); }
function advanceCreatorMission() { state.creatorMissions = normalizeCreatorMissions(state.creatorMissions); const list=state.creatorMissions.missions; const i=Math.max(0, list.findIndex(m=>m.id===state.creatorMissions.activeMissionId)); list[i].status = list[i].status === "complete" ? "complete" : "complete"; const next=list[(i+1)%list.length]; if (next.status !== "complete") next.status = "active"; state.creatorMissions.activeMissionId=next.id; if (!state.creatorMissions.badgesEarned.includes(list[i].rewardBadge)) state.creatorMissions.badgesEarned.push(list[i].rewardBadge); state.creatorMissions.missionScore += 36; renderAll(`Creator Mission completed: ${list[i].title}.`); }
function cycleAiCompanionProfile() { state.aiCompanionProfiles = normalizeAiCompanionProfiles(state.aiCompanionProfiles, state.aiPlayerBench); const ids=state.aiCompanionProfiles.companions.map(c=>c.id); const i=Math.max(0, ids.indexOf(state.aiCompanionProfiles.activeCompanionId)); state.aiCompanionProfiles.activeCompanionId=ids[(i+1)%ids.length]||""; renderAll(`AI companion selected: ${(state.aiCompanionProfiles.companions.find(c=>c.id===state.aiCompanionProfiles.activeCompanionId)||{}).displayName || "Companion"}.`); }
function runPlaytestTheater() { state.playtestTheater = normalizePlaytestTheater(state.playtestTheater, state.aiPlayerBench, state.couchCoopSessions, state.gameShelf); const session = state.playtestTheater.sessions.find(s=>s.id===state.playtestTheater.activeSessionId) || state.playtestTheater.sessions[0]; session.status = "complete"; const id = uniqueId("receipt_theater", state.playtestTheater.receipts.map(r=>r.id)); const receipt = { id, summary: `${session.title} completed with ${session.players.length} players and ${session.spectators.length} spectators.`, findings: ["One cozy route completed", "No free-text chat needed", "Export receipt ready"], createdAt: new Date().toISOString() }; state.playtestTheater.receipts.unshift(receipt); logPlaytest("playtest-theater", state.activeSceneId, receipt.summary); renderAll(`Playtest Theater receipt captured: ${id}.`); }
function refreshCozyHomeDashboard() { state.cozyHomeDashboard = normalizeCozyHomeDashboard(state.cozyHomeDashboard); state.cozyHomeDashboard.activePrompt = "Your shelf lights up. A couch companion is ready. One mission wants love."; state.cozyHomeDashboard.warmthScore = clamp((state.cozyHomeDashboard.warmthScore || 0) + 3, 0, 100); renderAll("Cozy Home Dashboard refreshed."); }
function advanceFirstCartridgeFlow() { state.firstCartridgeFlow = normalizeFirstCartridgeFlow(state.firstCartridgeFlow); const steps=state.firstCartridgeFlow.steps; const i=Math.max(0, steps.findIndex(s=>s.id===state.firstCartridgeFlow.activeStepId)); steps[i].status="complete"; const next=steps[(i+1)%steps.length]; if (next.status !== "complete") next.status="active"; state.firstCartridgeFlow.activeStepId=next.id; renderAll(`First Cartridge Flow advanced: ${next.title}.`); }
