  el.aiMemoryLedgerPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.aiMemoryLedger.ledgerType)}</small><strong>${state.aiMemoryLedger.entries.length} local memory receipt(s)</strong><p>${escapeHtml(state.aiMemoryLedger.retentionPolicy)}</p><div class="mini-pill-row">${boundaries}</div></article>${entries}`;
