function validateAiPlayerBenchBrowser(bench, errors) {
  if (!bench || typeof bench !== "object" || Array.isArray(bench)) { errors.push("aiPlayerBench must be an object."); return; }
  const ids = new Set((bench.players || []).map(player => player.id));
  if (bench.noChatPolicy !== true) errors.push("aiPlayerBench.noChatPolicy must be true.");
  if (!Array.isArray(bench.players) || !bench.players.length) errors.push("aiPlayerBench.players must be a non-empty array.");
  if (bench.activePlayerId && !ids.has(bench.activePlayerId)) errors.push("aiPlayerBench.activePlayerId must reference a player.");
}
function validateAiMatchLabBrowser(lab, bench, shelf, errors) {
  if (!lab || typeof lab !== "object" || Array.isArray(lab)) { errors.push("aiMatchLab must be an object."); return; }
  const playerIds = new Set((bench?.players || []).map(player => player.id));
  const matchIds = new Set((lab.matches || []).map(match => match.id));
  if (!Array.isArray(lab.matches) || !lab.matches.length) errors.push("aiMatchLab.matches must be a non-empty array.");
  if (lab.activeMatchId && !matchIds.has(lab.activeMatchId)) errors.push("aiMatchLab.activeMatchId must reference a match.");
  (lab.matches || []).forEach((match, index) => (match.players || []).forEach(playerId => { if (!playerIds.has(playerId)) errors.push(`aiMatchLab.matches[${index}] references missing AI player '${playerId}'.`); }));
}
function validateAiMemoryLedgerBrowser(ledger, bench, errors) {
  if (!ledger || typeof ledger !== "object" || Array.isArray(ledger)) { errors.push("aiMemoryLedger must be an object."); return; }
  const playerIds = new Set((bench?.players || []).map(player => player.id));
  if (!Array.isArray(ledger.entries) || !ledger.entries.length) errors.push("aiMemoryLedger.entries must be a non-empty array.");
  (ledger.entries || []).forEach((entry, index) => { if (!playerIds.has(entry.playerId)) errors.push(`aiMemoryLedger.entries[${index}] references missing AI player '${entry.playerId}'.`); if (!entry.summary) errors.push(`aiMemoryLedger.entries[${index}].summary is required.`); });
}
function validateAiPlaytestArenaBrowser(arena, bench, scenes, errors) {
  if (!arena || typeof arena !== "object" || Array.isArray(arena)) { errors.push("aiPlaytestArena must be an object."); return; }
  const playerIds = new Set((bench?.players || []).map(player => player.id));
  const sceneIds = new Set((scenes || []).map(scene => scene.id));
  const scenarioIds = new Set((arena.scenarios || []).map(scenario => scenario.id));
  if (!Array.isArray(arena.scenarios) || !arena.scenarios.length) errors.push("aiPlaytestArena.scenarios must be a non-empty array.");
  if (arena.activeScenarioId && !scenarioIds.has(arena.activeScenarioId)) errors.push("aiPlaytestArena.activeScenarioId must reference a scenario.");
  (arena.scenarios || []).forEach((scenario, index) => { if (scenario.sceneId && !sceneIds.has(scenario.sceneId)) errors.push(`aiPlaytestArena.scenarios[${index}] references missing scene '${scenario.sceneId}'.`); (scenario.playerIds || []).forEach(playerId => { if (!playerIds.has(playerId)) errors.push(`aiPlaytestArena.scenarios[${index}] references missing AI player '${playerId}'.`); }); });
}

function validatePrivateRelayBrowser(relay, sessions, errors) {
  if (!relay || typeof relay !== "object" || Array.isArray(relay)) { errors.push("privateRelayPrototype must be an object."); return; }
  const roomIds = new Set((relay.rooms || []).map(room => room.id));
  const sessionIds = new Set((sessions?.sessions || []).map(session => session.id));
  if (relay.noChatRequired !== true) errors.push("privateRelayPrototype.noChatRequired must be true.");
  if (!Array.isArray(relay.rooms) || !relay.rooms.length) errors.push("privateRelayPrototype.rooms must be a non-empty array.");
  if (relay.activeRoomId && !roomIds.has(relay.activeRoomId)) errors.push("privateRelayPrototype.activeRoomId must reference a room.");
  (relay.rooms || []).forEach((room, index) => { if (room.sessionId && !sessionIds.has(room.sessionId)) errors.push(`privateRelayPrototype.rooms[${index}].sessionId references missing session '${room.sessionId}'.`); });
  if (!Array.isArray(relay.endpointProfiles) || !relay.endpointProfiles.length) errors.push("privateRelayPrototype.endpointProfiles must be a non-empty array.");
}
function validateRelayPacketLabBrowser(lab, relay, sessions, errors) {
  if (!lab || typeof lab !== "object" || Array.isArray(lab)) { errors.push("relayPacketLab must be an object."); return; }
  const packetIds = new Set((lab.packets || []).map(packet => packet.id));
  const roomIds = new Set((relay?.rooms || []).map(room => room.id));
  const sessionIds = new Set((sessions?.sessions || []).map(session => session.id));
  if (!Array.isArray(lab.packetTypes) || !lab.packetTypes.includes("signal_ping")) errors.push("relayPacketLab.packetTypes must include signal_ping.");
  if (!Array.isArray(lab.packets) || !lab.packets.length) errors.push("relayPacketLab.packets must be a non-empty array.");
  if (lab.activePacketId && !packetIds.has(lab.activePacketId)) errors.push("relayPacketLab.activePacketId must reference a packet.");
  (lab.packets || []).forEach((packet, index) => { if (packet.noChatPayload !== true) errors.push(`relayPacketLab.packets[${index}].noChatPayload must be true.`); if (packet.roomId && !roomIds.has(packet.roomId)) errors.push(`relayPacketLab.packets[${index}].roomId references missing relay room '${packet.roomId}'.`); if (packet.sessionId && !sessionIds.has(packet.sessionId)) errors.push(`relayPacketLab.packets[${index}].sessionId references missing session '${packet.sessionId}'.`); });
}
function validateRoomDirectoryBrowser(directory, relay, shelf, errors) {
  if (!directory || typeof directory !== "object" || Array.isArray(directory)) { errors.push("roomDirectory must be an object."); return; }
  const roomIds = new Set((relay?.rooms || []).map(room => room.id));
  const gameIds = new Set((shelf?.entries || []).map(game => game.id));
  if (!Array.isArray(directory.rooms) || !directory.rooms.length) errors.push("roomDirectory.rooms must be a non-empty array.");
  if (directory.activeRoomId && !roomIds.has(directory.activeRoomId)) errors.push("roomDirectory.activeRoomId must reference a relay room.");
  (directory.rooms || []).forEach((room, index) => { if (room.roomId && !roomIds.has(room.roomId)) errors.push(`roomDirectory.rooms[${index}].roomId references missing relay room '${room.roomId}'.`); if (room.gameId && !gameIds.has(room.gameId)) errors.push(`roomDirectory.rooms[${index}].gameId references missing game '${room.gameId}'.`); });
}
function validateRelayDeploymentGuideBrowser(guide, errors) {
  if (!guide || typeof guide !== "object" || Array.isArray(guide)) { errors.push("relayDeploymentGuide must be an object."); return; }
  const ids = new Set((guide.profiles || []).map(profile => profile.id));
  if (!Array.isArray(guide.profiles) || !guide.profiles.length) errors.push("relayDeploymentGuide.profiles must be a non-empty array.");
  if (guide.activeProfileId && !ids.has(guide.activeProfileId)) errors.push("relayDeploymentGuide.activeProfileId must reference a profile.");
  if (!Array.isArray(guide.checklist) || !guide.checklist.length) errors.push("relayDeploymentGuide.checklist must be a non-empty array.");
}


