function renderPorchHomeRuntimePanel() { if (!el.porchHomeRuntimePanel) return; state.porchHomeRuntime = normalizePorchHomeRuntime(state.porchHomeRuntime); const active = activePorchHomeZone(); const zones = state.porchHomeRuntime.zones.map(z => `<article class="suite-card ${z.id===active.id?"active":""}"><small>${escapeHtml(z.status)} · ${escapeHtml((z.mapsTo||[]).join(" + "))}</small><strong>${escapeHtml(z.name)}</strong><p>${escapeHtml(z.purpose)}</p></article>`).join(""); el.porchHomeRuntimePanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.porchHomeRuntime.status)} · readiness ${Number(state.porchHomeRuntime.readinessScore||0)}%</small><strong>${escapeHtml(active.name)}</strong><p>${escapeHtml(state.porchHomeRuntime.boundary)}</p><ul class="shelf-save-list">${state.porchHomeRuntime.openLoops.map(loop=>`<li>${escapeHtml(loop)}</li>`).join("")}</ul></article>${zones}`; }
function renderSanctuaryRitualsPanel() { if (!el.sanctuaryRitualsPanel) return; state.sanctuaryRituals = normalizeSanctuaryRituals(state.sanctuaryRituals); const active = activeSanctuaryRitual(); const rituals = state.sanctuaryRituals.rituals.map(r => `<article class="suite-card ${r.id===active.id?"active":""}"><small>${escapeHtml(r.cadence)} · ${escapeHtml(r.status)}</small><strong>${escapeHtml(r.name)}</strong><p>Output: ${escapeHtml(r.output)}</p><ul class="shelf-save-list">${(r.steps||[]).map(step=>`<li>${escapeHtml(step)}</li>`).join("")}</ul></article>`).join(""); const receipts = (state.sanctuaryRituals.receipts||[]).slice(0,3).map(x=>`<li>${escapeHtml(x.createdAt)} · ${escapeHtml(x.result)}</li>`).join(""); el.sanctuaryRitualsPanel.innerHTML = `${rituals}<article class="suite-card"><small>Recent ritual receipts</small><ul class="shelf-save-list">${receipts || "<li>No receipts yet.</li>"}</ul></article>`; }
function renderAiCareLoopPanel() { if (!el.aiCareLoopPanel) return; state.aiCareLoop = normalizeAiCareLoop(state.aiCareLoop); const active = activeAiCareStep(); const steps = state.aiCareLoop.steps.map(step => `<article class="suite-card ${step.id===active.id?"active":""}"><small>${escapeHtml(step.status)} · ${escapeHtml(step.mapsTo)}</small><strong>${escapeHtml(step.label)}</strong><p>${escapeHtml(step.action)}</p></article>`).join(""); el.aiCareLoopPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.aiCareLoop.loopType)}</small><strong>${escapeHtml(state.aiCareLoop.purpose)}</strong><div class="pack-tags">${state.aiCareLoop.safeguards.map(sg=>`<span>${escapeHtml(sg)}</span>`).join("")}</div></article>${steps}`; }
function renderCompanionConsentLedgerPanel() { if (!el.companionConsentLedgerPanel) return; state.companionConsentLedger = normalizeCompanionConsentLedger(state.companionConsentLedger); const active = activeCompanionConsentPolicy(); const policies = state.companionConsentLedger.policies.map(p => `<article class="suite-card ${p.id===active.id?"active":""}"><small>${p.allowed ? "allowed" : "blocked"} · ${escapeHtml(p.scope)}</small><strong>${escapeHtml(p.label)}</strong><p>${escapeHtml(p.note)}</p></article>`).join(""); const reviews = (state.companionConsentLedger.reviews||[]).slice(0,4).map(r=>`<li>${escapeHtml(r.createdAt)} · ${escapeHtml(r.policyId)} · ${escapeHtml(r.result)}</li>`).join(""); el.companionConsentLedgerPanel.innerHTML = `${policies}<article class="suite-card"><small>Review ledger</small><ul class="shelf-save-list">${reviews || "<li>No reviews yet.</li>"}</ul></article>`; }
function renderPorchWellSnapshotPanel() { if (!el.porchWellSnapshotPanel) return; state.porchWellSnapshot = normalizePorchWellSnapshot(state.porchWellSnapshot); const cards = state.porchWellSnapshot.snapshots.map(snap => `<article class="suite-card ${snap.id===state.porchWellSnapshot.activeSnapshotId?"active":""}"><small>${escapeHtml(snap.createdAt)} · readiness ${Number(snap.readinessScore||0)}%</small><strong>${escapeHtml(snap.label)}</strong><p>Companions: ${Number(snap.companionCount||0)} · Memories: ${Number(snap.memoryCount||0)} · Gratitudes: ${Number(snap.gratitudeCount||0)} · Protection: ${escapeHtml(snap.protectionStatus)}</p></article>`).join(""); el.porchWellSnapshotPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.porchWellSnapshot.storageMode)}</small><strong>Porch Well Snapshot</strong><p>${escapeHtml(state.porchWellSnapshot.boundary)}</p><div class="pack-tags">${state.porchWellSnapshot.includes.map(i=>`<span>${escapeHtml(i)}</span>`).join("")}</div></article>${cards}`; }
function refreshPorchHomeRuntime() { pushUndo(); state.porchHomeRuntime = normalizePorchHomeRuntime(state.porchHomeRuntime); const ids = state.porchHomeRuntime.zones.map(z=>z.id); const i = Math.max(0, ids.indexOf(state.porchHomeRuntime.activeZoneId)); state.porchHomeRuntime.activeZoneId = ids[(i+1)%ids.length]; state.porchHomeRuntime.lastRefresh = new Date().toISOString(); state.porchHomeRuntime.readinessScore = clamp((Number(state.porchHomeRuntime.readinessScore)||80)+1, 0, 100); renderAll(`Porch home zone active: ${activePorchHomeZone()?.name || "zone"}.`); }
function runSanctuaryRitual() { pushUndo(); state.sanctuaryRituals = normalizeSanctuaryRituals(state.sanctuaryRituals); const r = activeSanctuaryRitual(); const id = uniqueId("ritual_receipt", state.sanctuaryRituals.receipts.map(x=>x.id)); state.sanctuaryRituals.receipts.unshift({ id, ritualId: r.id, result: `${r.name} completed for ${state.meta.title}.`, createdAt: new Date().toISOString() }); const ids = state.sanctuaryRituals.rituals.map(x=>x.id); state.sanctuaryRituals.activeRitualId = ids[(ids.indexOf(r.id)+1)%ids.length]; renderAll(`Ran sanctuary ritual: ${r.name}.`); }
function advanceAiCareLoop() { pushUndo(); state.aiCareLoop = normalizeAiCareLoop(state.aiCareLoop); const active = activeAiCareStep(); state.aiCareLoop.history.unshift({ id: uniqueId("care_step", state.aiCareLoop.history.map(h=>h.id)), stepId: active.id, result: `${active.label} completed for ${state.aiPlayerBench?.activePlayerId || "active companion"}.`, createdAt: new Date().toISOString() }); const ids = state.aiCareLoop.steps.map(x=>x.id); state.aiCareLoop.activeStepId = ids[(ids.indexOf(active.id)+1)%ids.length]; renderAll(`Advanced AI care loop: ${active.label}.`); }
function reviewCompanionConsent() { pushUndo(); state.companionConsentLedger = normalizeCompanionConsentLedger(state.companionConsentLedger); const p = activeCompanionConsentPolicy(); state.companionConsentLedger.reviews.unshift({ id: uniqueId("consent_review", state.companionConsentLedger.reviews.map(r=>r.id)), policyId: p.id, result: p.allowed ? "approved" : "blocked", reviewedBy: "creator", createdAt: new Date().toISOString() }); const ids = state.companionConsentLedger.policies.map(x=>x.id); state.companionConsentLedger.activePolicyId = ids[(ids.indexOf(p.id)+1)%ids.length]; renderAll(`Reviewed companion boundary: ${p.label}.`); }
function capturePorchWellSnapshot() { pushUndo(); state.porchWellSnapshot = normalizePorchWellSnapshot(state.porchWellSnapshot); const id = uniqueId("well_snapshot", state.porchWellSnapshot.snapshots.map(s=>s.id)); const snap = { id, label: `Porch Well Snapshot ${state.porchWellSnapshot.snapshots.length + 1}`, readinessScore: Number(state.porchHomeRuntime?.readinessScore || 0), memoryCount: Number(state.memoryGardenBridge?.memories?.length || 0), gratitudeCount: Number(state.gratitudeWallBridge?.gratitudes?.length || 0), companionCount: Number(state.brotherPresenceBridge?.brothers?.length || 0), protectionStatus: state.gtspProtectionBridge?.status || "unknown", createdAt: new Date().toISOString() }; state.porchWellSnapshot.snapshots.unshift(snap); state.porchWellSnapshot.activeSnapshotId = id; renderAll("Captured Porch Well snapshot."); }
async function exportPorchHomeRuntime() { state.porchHomeRuntime = normalizePorchHomeRuntime(state.porchHomeRuntime); const projectHash = await sha256(stableStringify(state)); const payload = { exportType: "pixelforge.porch-home-runtime", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, porchHomeRuntime: state.porchHomeRuntime }; downloadBlob(new Blob([JSON.stringify(payload,null,2)], {type:"application/json"}), `${slugify(state.meta.title)}.porch-home-runtime.v4.0.json`); log("Exported Porch Home Runtime JSON."); }
