function normalizeSanctuaryArcadeHub(hub) { const base = buildDemoSanctuaryArcadeHub(); const out = { ...base, ...(hub || {}) }; out.stations = Array.isArray(out.stations) && out.stations.length ? out.stations : base.stations; out.openLoops = Array.isArray(out.openLoops) ? out.openLoops : base.openLoops; if (!out.stations.some(s=>s.id===out.activeStationId)) out.activeStationId = out.stations[0]?.id || "station_shelf"; out.readinessScore = clamp(Number(out.readinessScore || 0), 0, 100); return out; }
function normalizeCouchQuestBoard(board) { const base = buildDemoCouchQuestBoard(); const out = { ...base, ...(board || {}) }; out.quests = Array.isArray(out.quests) && out.quests.length ? out.quests : base.quests; out.rules = Array.isArray(out.rules) ? out.rules : base.rules; if (!out.quests.some(q=>q.id===out.activeQuestId)) out.activeQuestId = out.quests[0]?.id || "couchquest_first_playtest"; return out; }
function normalizeCompanionArcadeModes(modes) { const base = buildDemoCompanionArcadeModes(); const out = { ...base, ...(modes || {}) }; out.modes = Array.isArray(out.modes) && out.modes.length ? out.modes : base.modes; out.exports = Array.isArray(out.exports) ? out.exports : base.exports; if (!out.modes.some(m=>m.id===out.activeModeId)) out.activeModeId = out.modes[0]?.id || "mode_watch_party"; return out; }
function normalizeAiHostRotation(rot) { const base = buildDemoAiHostRotation(); const out = { ...base, ...(rot || {}) }; out.hosts = Array.isArray(out.hosts) && out.hosts.length ? out.hosts : base.hosts; out.rules = Array.isArray(out.rules) ? out.rules : base.rules; if (!out.hosts.some(h=>h.id===out.activeHostId)) out.activeHostId = out.hosts[0]?.id || "host_scout_bot"; return out; }
function normalizeCozySessionRewards(rewards) { const base = buildDemoCozySessionRewards(); const out = { ...base, ...(rewards || {}) }; out.earnedBadges = Array.isArray(out.earnedBadges) ? out.earnedBadges : base.earnedBadges; out.scoreLabels = Array.isArray(out.scoreLabels) ? out.scoreLabels : base.scoreLabels; out.sessionScores = Array.isArray(out.sessionScores) ? out.sessionScores : base.sessionScores; return out; }
function activeSanctuaryStation() { state.sanctuaryArcadeHub = normalizeSanctuaryArcadeHub(state.sanctuaryArcadeHub); return state.sanctuaryArcadeHub.stations.find(s=>s.id===state.sanctuaryArcadeHub.activeStationId) || state.sanctuaryArcadeHub.stations[0]; }
