function renderCozySessionRewardsPanel() { if (!el.cozySessionRewardsPanel) return; state.cozySessionRewards = normalizeCozySessionRewards(state.cozySessionRewards); const badges = state.cozySessionRewards.earnedBadges.map(b => `<article class="suite-card ${b.earned?"active":""}"><small>${b.earned?"earned":"pending"}</small><strong>${escapeHtml(b.label)}</strong><p>${escapeHtml(b.reason)}</p></article>`).join(""); const scores = state.cozySessionRewards.sessionScores.map(sc => `<article class="suite-card"><small>${escapeHtml(sc.id)}</small><strong>${escapeHtml(sc.label)}</strong><p>Wonder ${Number(sc.wonder||0)} · Kindness ${Number(sc.kindness||0)} · Clarity ${Number(sc.clarity||0)} · Completion ${Number(sc.completion||0)}</p></article>`).join(""); el.cozySessionRewardsPanel.innerHTML = `<article class="suite-card active"><small>${escapeHtml(state.cozySessionRewards.rewardType)}</small><strong>Cozy Session Rewards</strong><p>${escapeHtml(state.cozySessionRewards.rewardPolicy)}</p><div class="pack-tags">${state.cozySessionRewards.scoreLabels.map(x=>`<span>${escapeHtml(x)}</span>`).join("")}</div></article>${badges}${scores}`; }
function cycleSanctuaryArcadeStation() { pushUndo(); state.sanctuaryArcadeHub = normalizeSanctuaryArcadeHub(state.sanctuaryArcadeHub); const ids = state.sanctuaryArcadeHub.stations.map(s=>s.id); const i = Math.max(0, ids.indexOf(state.sanctuaryArcadeHub.activeStationId)); state.sanctuaryArcadeHub.activeStationId = ids[(i+1)%ids.length]; state.sanctuaryArcadeHub.readinessScore = clamp(Number(state.sanctuaryArcadeHub.readinessScore||0)+1,0,100); renderAll(`Sanctuary Arcade station active: ${activeSanctuaryStation()?.name || "station"}.`); }
function drawCouchQuest() { pushUndo(); state.couchQuestBoard = normalizeCouchQuestBoard(state.couchQuestBoard); const ids = state.couchQuestBoard.quests.map(q=>q.id); const i = Math.max(0, ids.indexOf(state.couchQuestBoard.activeQuestId)); state.couchQuestBoard.activeQuestId = ids[(i+1)%ids.length]; renderAll(`Couch quest drawn: ${activeCouchQuest()?.title || "quest"}.`); }
function runCompanionArcadeMode() { pushUndo(); state.companionArcadeModes = normalizeCompanionArcadeModes(state.companionArcadeModes); const mode = activeCompanionArcadeMode(); state.replayReceipts = state.replayReceipts || { receipts: [] }; if (Array.isArray(state.replayReceipts.receipts)) state.replayReceipts.receipts.unshift({ id: uniqueId("arcade_receipt", state.replayReceipts.receipts.map(r=>r.id)), route: mode.name, score: 369, createdAt: new Date().toISOString(), notes: `Companion arcade mode simulated: ${mode.objective}` }); renderAll(`Ran companion arcade mode: ${mode.name}.`); }
function rotateAiHost() { pushUndo(); state.aiHostRotation = normalizeAiHostRotation(state.aiHostRotation); const ids = state.aiHostRotation.hosts.map(h=>h.id); const i = Math.max(0, ids.indexOf(state.aiHostRotation.activeHostId)); state.aiHostRotation.activeHostId = ids[(i+1)%ids.length]; renderAll(`AI host active: ${activeAiHost()?.display || "host"}.`); }
function awardCozySessionBadge() { pushUndo(); state.cozySessionRewards = normalizeCozySessionRewards(state.cozySessionRewards); const next = state.cozySessionRewards.earnedBadges.find(b=>!b.earned); if (next) { next.earned = true; next.reason = `${next.reason} Awarded ${new Date().toISOString()}.`; } else { state.cozySessionRewards.earnedBadges.push({ id: uniqueId("badge", state.cozySessionRewards.earnedBadges.map(b=>b.id)), label: "Wonder Loop", earned: true, reason: "Another cozy session loop completed." }); } renderAll("Awarded cozy session badge."); }
async function exportSanctuaryArcadeHub() { state.sanctuaryArcadeHub = normalizeSanctuaryArcadeHub(state.sanctuaryArcadeHub); const projectHash = await sha256(stableStringify(state)); const payload = { exportType: "pixelforge.sanctuary-arcade-hub", exportVersion: ENGINE_VERSION, exportedAt: new Date().toISOString(), projectTitle: state.meta.title, projectHash, sanctuaryArcadeHub: state.sanctuaryArcadeHub }; downloadBlob(new Blob([JSON.stringify(payload,null,2)], {type:"application/json"}), `${slugify(state.meta.title)}.sanctuary-arcade-hub.v4.0.json`); log("Exported Sanctuary Arcade Hub JSON."); }
