function normalizeWorldBuilderArcade(hub) { const base = buildDemoWorldBuilderArcade(); const out = { ...base, ...(hub || {}) }; out.stations = Array.isArray(out.stations) && out.stations.length ? out.stations : base.stations; out.openLoops = Array.isArray(out.openLoops) ? out.openLoops : base.openLoops; if (!out.stations.some(s=>s.id===out.activeStationId)) out.activeStationId = out.stations[0]?.id || "world_station_seed_forge"; out.readinessScore = clamp(Number(out.readinessScore || 0), 0, 100); return out; }
function normalizeWorldSeedForge(forge) { const base = buildDemoWorldSeedForge(); const out = { ...base, ...(forge || {}) }; out.seeds = Array.isArray(out.seeds) && out.seeds.length ? out.seeds : base.seeds; out.rules = Array.isArray(out.rules) ? out.rules : base.rules; if (!out.seeds.some(seed=>seed.id===out.activeSeedId)) out.activeSeedId = out.seeds[0]?.id || "seed_shasta_vending_oracle"; return out; }
function normalizeRouteWeaver(weaver) { const base = buildDemoRouteWeaver(); const out = { ...base, ...(weaver || {}) }; out.routes = Array.isArray(out.routes) && out.routes.length ? out.routes : base.routes; out.exportTargets = Array.isArray(out.exportTargets) ? out.exportTargets : base.exportTargets; if (!out.routes.some(route=>route.id===out.activeRouteId)) out.activeRouteId = out.routes[0]?.id || "route_shasta_first_pilgrimage"; return out; }
function normalizeRegionCardRack(rack) { const base = buildDemoRegionCardRack(); const out = { ...base, ...(rack || {}) }; out.regions = Array.isArray(out.regions) && out.regions.length ? out.regions : base.regions; out.readinessLabels = Array.isArray(out.readinessLabels) ? out.readinessLabels : base.readinessLabels; if (!out.regions.some(region=>region.id===out.activeRegionId)) out.activeRegionId = out.regions[0]?.id || "region_shasta_roadside"; return out; }
function normalizeQuestlineComposer(comp) { const base = buildDemoQuestlineComposer(); const out = { ...base, ...(comp || {}) }; out.questlines = Array.isArray(out.questlines) && out.questlines.length ? out.questlines : base.questlines; out.rules = Array.isArray(out.rules) ? out.rules : base.rules; if (!out.questlines.some(q=>q.id===out.activeQuestlineId)) out.activeQuestlineId = out.questlines[0]?.id || "questline_oracle_coffee_gate"; return out; }
function normalizeWorldBible(bible) { const base = buildDemoWorldBible(); const out = { ...base, ...(bible || {}) }; out.canonRules = Array.isArray(out.canonRules) && out.canonRules.length ? out.canonRules : base.canonRules; out.sequelHooks = Array.isArray(out.sequelHooks) ? out.sequelHooks : base.sequelHooks; out.memoryLinks = Array.isArray(out.memoryLinks) ? out.memoryLinks : base.memoryLinks; if (!out.canonRules.some(rule=>rule.id===out.activeCanonId)) out.activeCanonId = out.canonRules[0]?.id || "canon_parallax_road_rules"; return out; }
function activeWorldBuilderStation() { state.worldBuilderArcade = normalizeWorldBuilderArcade(state.worldBuilderArcade); return state.worldBuilderArcade.stations.find(s=>s.id===state.worldBuilderArcade.activeStationId) || state.worldBuilderArcade.stations[0]; }
