function forgeWorldSeed() { pushUndo(); state.worldSeedForge = normalizeWorldSeedForge(state.worldSeedForge); const ids = state.worldSeedForge.seeds.map(seed=>seed.id); const i = Math.max(0, ids.indexOf(state.worldSeedForge.activeSeedId)); state.worldSeedForge.activeSeedId = ids[(i+1)%ids.length]; state.worldBuilderArcade = normalizeWorldBuilderArcade(state.worldBuilderArcade); state.worldBuilderArcade.readinessScore = clamp(Number(state.worldBuilderArcade.readinessScore||0)+1,0,100); renderAll(`World seed forged: ${activeWorldSeed()?.title || "seed"}.`); }
function weaveRoute() { pushUndo(); state.routeWeaver = normalizeRouteWeaver(state.routeWeaver); const ids = state.routeWeaver.routes.map(route=>route.id); const i = Math.max(0, ids.indexOf(state.routeWeaver.activeRouteId)); state.routeWeaver.activeRouteId = ids[(i+1)%ids.length]; state.demoWalkthrough = state.demoWalkthrough || { steps: [] }; renderAll(`Route woven: ${activeRouteWeaverRoute()?.title || "route"}.`); }
