function acceptWorldBibleRule() { pushUndo(); state.worldBible = normalizeWorldBible(state.worldBible); const active = activeCanonRule(); if (active) active.status = "accepted"; renderAll(`Accepted World Bible rule: ${active?.id || "canon"}.`); }
