function normalizeStarterCartridgeBuilder(v) { const base=buildDemoStarterCartridgeBuilder(); const out={...base, ...(v||{})}; out.kits=Array.isArray(out.kits)&&out.kits.length?out.kits:base.kits; out.rules=Array.isArray(out.rules)?out.rules:base.rules; if(!out.kits.some(k=>k.id===out.activeKitId)) out.activeKitId=out.kits[0]?.id || "starter_shasta_first_route"; return out; }
function normalizeRouteMapPreview(v) { const base=buildDemoRouteMapPreview(); const out={...base, ...(v||{})}; out.routeMaps=Array.isArray(out.routeMaps)&&out.routeMaps.length?out.routeMaps:base.routeMaps; if(!out.routeMaps.some(r=>r.routeId===out.activeRouteId)) out.activeRouteId=out.routeMaps[0]?.routeId || "route_shasta_first_pilgrimage"; return out; }
function normalizeRegionQaPass(v) { const base=buildDemoRegionQaPass(); const out={...base, ...(v||{})}; out.checks=Array.isArray(out.checks)&&out.checks.length?out.checks:base.checks; out.rules=Array.isArray(out.rules)?out.rules:base.rules; if(!out.checks.some(c=>c.id===out.activeCheckId)) out.activeCheckId=out.checks[0]?.id || "qa_roadside_first_objective"; return out; }
function normalizeWorldLaunchChecklist(v) { const base=buildDemoWorldLaunchChecklist(); const out={...base, ...(v||{})}; out.items=Array.isArray(out.items)&&out.items.length?out.items:base.items; out.releaseStates=Array.isArray(out.releaseStates)?out.releaseStates:base.releaseStates; return out; }
function normalizeAiWorldScout(v) { const base=buildDemoAiWorldScout(); const out={...base, ...(v||{})}; out.reports=Array.isArray(out.reports)&&out.reports.length?out.reports:base.reports; if(!out.reports.some(r=>r.id===out.activeReportId)) out.activeReportId=out.reports[0]?.id || "scout_shasta_first_route_001"; return out; }
function activeStarterCartridgeKit() { state.starterCartridgeBuilder=normalizeStarterCartridgeBuilder(state.starterCartridgeBuilder); return state.starterCartridgeBuilder.kits.find(k=>k.id===state.starterCartridgeBuilder.activeKitId)||state.starterCartridgeBuilder.kits[0]; }
function activeRouteMap() { state.routeMapPreview=normalizeRouteMapPreview(state.routeMapPreview); return state.routeMapPreview.routeMaps.find(r=>r.routeId===state.routeMapPreview.activeRouteId)||state.routeMapPreview.routeMaps[0]; }
function activeRegionQaCheck() { state.regionQaPass=normalizeRegionQaPass(state.regionQaPass); return state.regionQaPass.checks.find(c=>c.id===state.regionQaPass.activeCheckId)||state.regionQaPass.checks[0]; }
function activeAiWorldScoutReport() { state.aiWorldScout=normalizeAiWorldScout(state.aiWorldScout); return state.aiWorldScout.reports.find(r=>r.id===state.aiWorldScout.activeReportId)||state.aiWorldScout.reports[0]; }
function renderStarterCartridgeBuilderPanel() { if(!el.starterCartridgeBuilderPanel) return; state.starterCartridgeBuilder=normalizeStarterCartridgeBuilder(state.starterCartridgeBuilder); const active=activeStarterCartridgeKit(); const cards=state.starterCartridgeBuilder.kits.map(k=>`<article class="suite-card ${k.id===active.id?"active":""}"><small>readiness ${Number(k.readiness||0)}% · ${escapeHtml(k.routeId)}</small><strong>${escapeHtml(k.title)}</strong><p>${escapeHtml(k.notes||"")}</p><div class="pack-tags">${(k.requiredExports||[]).map(x=>`<span>${escapeHtml(x)}</span>`).join("")}</div></article>`).join(""); el.starterCartridgeBuilderPanel.innerHTML=`<article class="suite-card active"><small>${escapeHtml(state.starterCartridgeBuilder.status)} · ${escapeHtml(state.starterCartridgeBuilder.builderType)}</small><strong>${escapeHtml(active.title)}</strong><p>Scenes: ${(active.sceneIds||[]).map(sceneNameById).map(escapeHtml).join(" → ")}</p><div class="pack-tags">${state.starterCartridgeBuilder.rules.map(r=>`<span>${escapeHtml(r)}</span>`).join("")}</div></article>${cards}`; }
function renderRouteMapPreviewPanel() { if(!el.routeMapPreviewPanel) return; state.routeMapPreview=normalizeRouteMapPreview(state.routeMapPreview); const active=activeRouteMap(); const nodes=(active.nodes||[]).map(n=>`<li><strong>${escapeHtml(sceneNameById(n.sceneId))}</strong>: ${escapeHtml(n.label)} <small>gate: ${escapeHtml(n.gate)} · ${escapeHtml(n.emotion)}</small></li>`).join(""); const cards=state.routeMapPreview.routeMaps.map(r=>`<article class="suite-card ${r.routeId===active.routeId?"active":""}"><small>${escapeHtml(r.status)} · ${(r.nodes||[]).length} nodes</small><strong>${escapeHtml(r.title)}</strong><p>Risks: ${(r.riskFlags||[]).map(escapeHtml).join(" · ")}</p></article>`).join(""); el.routeMapPreviewPanel.innerHTML=`<article class="suite-card active"><small>${escapeHtml(state.routeMapPreview.displayMode)}</small><strong>${escapeHtml(active.title)}</strong><ul class="shelf-save-list">${nodes}</ul></article>${cards}`; }
function renderRegionQaPassPanel() { if(!el.regionQaPassPanel) return; state.regionQaPass=normalizeRegionQaPass(state.regionQaPass); const active=activeRegionQaCheck(); const cards=state.regionQaPass.checks.map(c=>`<article class="suite-card ${c.id===active.id?"active":""}"><small>${escapeHtml(c.status)} · ${escapeHtml(c.severity)} · ${escapeHtml(c.owner)}</small><strong>${escapeHtml(c.label)}</strong><p>${escapeHtml(c.finding)}</p></article>`).join(""); el.regionQaPassPanel.innerHTML=`<article class="suite-card active"><small>${escapeHtml(state.regionQaPass.qaType)}</small><strong>${escapeHtml(active.label)}</strong><p>${escapeHtml(active.finding)}</p><div class="pack-tags">${state.regionQaPass.rules.map(r=>`<span>${escapeHtml(r)}</span>`).join("")}</div></article>${cards}`; }
function renderWorldLaunchChecklistPanel() { if(!el.worldLaunchChecklistPanel) return; state.worldLaunchChecklist=normalizeWorldLaunchChecklist(state.worldLaunchChecklist); const required=state.worldLaunchChecklist.items.filter(i=>i.required); const passed=required.filter(i=>i.passed).length; const items=state.worldLaunchChecklist.items.map(i=>`<li>${i.passed?"✅":"⬜"} ${escapeHtml(i.label)} ${i.required?"<small>required</small>":""}</li>`).join(""); el.worldLaunchChecklistPanel.innerHTML=`<article class="suite-card active"><small>${escapeHtml(state.worldLaunchChecklist.currentState)} · ${passed}/${required.length} required passed</small><strong>World Launch Checklist</strong><ul class="shelf-save-list">${items}</ul><div class="pack-tags">${state.worldLaunchChecklist.releaseStates.map(s=>`<span>${escapeHtml(s)}</span>`).join("")}</div></article>`; }
function renderAiWorldScoutPanel() { if(!el.aiWorldScoutPanel) return; state.aiWorldScout=normalizeAiWorldScout(state.aiWorldScout); const active=activeAiWorldScoutReport(); const cards=state.aiWorldScout.reports.map(r=>`<article class="suite-card ${r.id===active.id?"active":""}"><small>${escapeHtml(r.aiId)} · ${escapeHtml(r.status)}</small><strong>${escapeHtml(r.id)}</strong><p>${escapeHtml(r.summary)}</p></article>`).join(""); el.aiWorldScoutPanel.innerHTML=`<article class="suite-card active"><small>${escapeHtml(state.aiWorldScout.scoutType)}</small><strong>${escapeHtml(active.summary)}</strong><ul class="shelf-save-list">${(active.findings||[]).map(f=>`<li>${escapeHtml(f)}</li>`).join("")}</ul><p>${escapeHtml(state.aiWorldScout.memoryPolicy)}</p></article>${cards}`; }
function buildStarterCartridge() { pushUndo(); state.starterCartridgeBuilder=normalizeStarterCartridgeBuilder(state.starterCartridgeBuilder); const ids=state.starterCartridgeBuilder.kits.map(k=>k.id); const i=Math.max(0,ids.indexOf(state.starterCartridgeBuilder.activeKitId)); state.starterCartridgeBuilder.activeKitId=ids[(i+1)%ids.length]; renderAll(`Starter cartridge active: ${activeStarterCartridgeKit()?.title || "kit"}.`); }
function cycleRouteMapPreview() { pushUndo(); state.routeMapPreview=normalizeRouteMapPreview(state.routeMapPreview); const ids=state.routeMapPreview.routeMaps.map(r=>r.routeId); const i=Math.max(0,ids.indexOf(state.routeMapPreview.activeRouteId)); state.routeMapPreview.activeRouteId=ids[(i+1)%ids.length]; renderAll(`Route map active: ${activeRouteMap()?.title || "route"}.`); }
function advanceRegionQaPass() { pushUndo(); state.regionQaPass=normalizeRegionQaPass(state.regionQaPass); const active=activeRegionQaCheck(); if(active) active.status = active.status === "open" ? "review" : active.status === "review" ? "resolved" : "open"; renderAll(`Region QA status: ${active?.label || "check"} → ${active?.status || "updated"}.`); }
function refreshWorldLaunchChecklist() { pushUndo(); state.worldLaunchChecklist=normalizeWorldLaunchChecklist(state.worldLaunchChecklist); const hasOpenHigh=(state.regionQaPass?.checks||[]).some(c=>c.severity==="high" && c.status!=="resolved"); state.worldLaunchChecklist.items.forEach(item=>{ if(item.id==="launch_region_qa_open") item.passed=!hasOpenHigh; if(item.id==="launch_ai_scout_receipt") item.passed=(state.aiWorldScout?.reports||[]).length>0; }); renderAll("World Launch Checklist refreshed from current QA/scout state."); }
function runAiWorldScout() { pushUndo(); state.aiWorldScout=normalizeAiWorldScout(state.aiWorldScout); const report={ id:`scout_${Date.now()}`, aiId:"scout_bot", routeId:state.routeMapPreview?.activeRouteId||"route_shasta_first_pilgrimage", status:"needs-human-review", summary:"Fresh scout pass recorded a playable route check for the active starter cartridge.", findings:["Confirm gate blockedText.","Check one music cue per region.","Make sure first objective remains visible."] }; state.aiWorldScout.reports.unshift(report); state.aiWorldScout.activeReportId=report.id; renderAll("AI World Scout report captured."); }
async function exportStarterCartridgeBuilder() { state.starterCartridgeBuilder=normalizeStarterCartridgeBuilder(state.starterCartridgeBuilder); const projectHash=await sha256(stableStringify(state)); const payload={exportType:"pixelforge.starter-cartridge-builder", exportVersion:ENGINE_VERSION, exportedAt:new Date().toISOString(), projectTitle:state.meta.title, projectHash, starterCartridgeBuilder:state.starterCartridgeBuilder}; downloadBlob(new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}), `${slugify(state.meta.title)}.starter-cartridge-builder.v4.0.json`); log("Exported Starter Cartridge Builder JSON."); }
