function validatePlayableWorldLaunchpadBrowser(project, errors) {
  if (!project?.starterCartridgeBuilder || !Array.isArray(project.starterCartridgeBuilder.kits) || project.starterCartridgeBuilder.kits.length < 3) errors.push("starterCartridgeBuilder.kits must include at least three starter kits.");
  if (project?.starterCartridgeBuilder && !project.starterCartridgeBuilder.kits?.some(k => k.id === project.starterCartridgeBuilder.activeKitId)) errors.push("starterCartridgeBuilder.activeKitId must reference an existing kit.");
  if (!project?.routeMapPreview || !Array.isArray(project.routeMapPreview.routeMaps) || project.routeMapPreview.routeMaps.length < 2) errors.push("routeMapPreview.routeMaps must include at least two route maps.");
  if (!project?.regionQaPass || !Array.isArray(project.regionQaPass.checks) || project.regionQaPass.checks.length < 4) errors.push("regionQaPass.checks must include at least four region checks.");
  if (!project?.worldLaunchChecklist || !Array.isArray(project.worldLaunchChecklist.items) || project.worldLaunchChecklist.items.filter(i=>i.required).length < 4) errors.push("worldLaunchChecklist.items must include required launch checks.");
  if (!project?.aiWorldScout || !Array.isArray(project.aiWorldScout.reports) || project.aiWorldScout.reports.length < 3) errors.push("aiWorldScout.reports must include at least three scout reports.");
  if (project?.aiWorldScout && !String(project.aiWorldScout.memoryPolicy || "").includes("no hidden profiling")) errors.push("aiWorldScout.memoryPolicy must block hidden profiling.");
}

function linesToChoices(text) {
  return String(text || "").split("\n").map(line => line.trim()).filter(Boolean).map((line, index) => {
    const [main, ...parts] = line.split("|").map(part => part.trim());
    const [labelRaw, responseRaw] = main.split("=>").map(part => part?.trim());
    const choice = { label: labelRaw || `Choice ${index + 1}`, response: responseRaw || "...", delta: {} };
    parts.forEach(part => {
      if (part.startsWith("reveal:")) choice.revealQuestId = part.slice(7).trim();
      else if (part.startsWith("flag:")) choice.setFlag = part.slice(5).trim();
      else part.split(",").forEach(pair => {
        const m = pair.trim().match(/^([a-zA-Z_][\w-]*)\s*[:=]\s*(-?\d+)$/);
        if (m && statKeys.includes(m[1])) choice.delta[m[1]] = clamp(parseInt(m[2], 10), -99, 99);
      });
    });
    if (!Object.keys(choice.delta).length) delete choice.delta;
    if (!choice.revealQuestId) delete choice.revealQuestId;
    if (!choice.setFlag) delete choice.setFlag;
    return choice;
  });
}
function linesToDelta(text) { const delta={}; String(text||"").split("\n").forEach(line=>{ const m=line.trim().match(/^([a-zA-Z_][\w-]*)\s*[:=]\s*(-?\d+)$/); if(m) delta[m[1]]=parseInt(m[2],10); }); return normalizeDelta(delta); }
function normalizeDelta(delta) { const out={}; Object.entries(delta||{}).forEach(([key,value])=>{ if(statKeys.includes(key)) out[key]=clamp(parseInt(value,10)||0,-99,99); }); return out; }
function sceneNameById(id) { return state.scenes.find(s=>s.id===id)?.name || id || "missing scene"; }
function itemNameById(id) { return state.scenes.flatMap(s => s.items || []).find(item => item.id === id)?.name || id || "missing item"; }
function questTitleById(id) { return state.quests.find(q => q.id === id)?.title || id || "missing quest"; }
function uniqueId(prefix, existing) { const used=new Set(existing); let base=slugify(prefix).replace(/-/g,"_") || "id"; let id=base; let i=2; while(used.has(id)) id=`${base}_${i++}`; return id; }
function log(message) { const p=document.createElement("p"); p.textContent=`› ${message}`; el.log.prepend(p); while(el.log.children.length>30) el.log.lastChild.remove(); }
function clamp(value,min,max) { return Math.min(max, Math.max(min, value)); }
function slugify(text) { return String(text).toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"") || "pixelforge-project"; }
function escapeHtml(text) { return String(text).replace(/[&<>"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c])); }
function escapeAttr(text) { return escapeHtml(text).replace(/'/g,"&#039;"); }
function structuredCloneSafe(obj) { return JSON.parse(JSON.stringify(obj)); }

