function computeBetaReadinessScorecard(){ pushUndo(); state.betaReadinessScorecard=normalizeBetaReadinessScorecard(state.betaReadinessScorecard); const avg=Math.round(state.betaReadinessScorecard.categories.reduce((a,c)=>a+c.score,0)/Math.max(1,state.betaReadinessScorecard.categories.length)); state.betaReadinessScorecard.overallScore=avg; state.betaReadinessScorecard.status=avg>=85?"green":avg>=60?"amber":"red"; renderAll("Computed beta readiness scorecard."); }
