function buildDemoV5PolishQueue(){ return { queueType:"pixelforge.v5-polish-queue", activeTaskId:"polish_first_run_script", tasks:[ {id:"polish_first_run_script",title:"Write first-run tutorial script",priority:"high",status:"active",acceptance:"New creator can reach first playtest without reading the manual."}, {id:"polish_export_labels",title:"Clarify all export buttons",priority:"high",status:"open",acceptance:"Each export explains who it is for and whether it is safe to share."}, {id:"polish_access_keyboard",title:"Audit keyboard-only workflow",priority:"high",status:"open",acceptance:"Creator can navigate core stations without mouse dependence."}, {id:"polish_shelf_glow",title:"Make Shelf feel like home base",priority:"medium",status:"planned",acceptance:"Shelf shows last edited, next action, beta status, and AI couch readiness."}, {id:"polish_microcopy",title:"Warm up technical copy",priority:"medium",status:"planned",acceptance:"Advanced systems have plain-language helper copy."} ], v5Gate:["no critical UX blockers","accessibility required checks reviewed","trusted playtest receipts attached","rights metadata green","private relay remains opt-in"] }; }
function normalizeV5PolishQueue(input={}){ const f=buildDemoV5PolishQueue(); const s=input&&typeof input==="object"&&!Array.isArray(input)?input:f; const tasks=(Array.isArray(s.tasks)&&s.tasks.length?s.tasks:f.tasks).map((t,i)=>({ id:String(t.id||`polish_${i+1}`), title:String(t.title||`Polish Task ${i+1}`), priority:["low","medium","high","blocker"].includes(t.priority)?t.priority:"medium", status:["planned","open","active","review","done"].includes(t.status)?t.status:"open", acceptance:String(t.acceptance||"") })).slice(0,64); const ids=new Set(tasks.map(t=>t.id)); return { queueType:String(s.queueType||f.queueType), activeTaskId:ids.has(s.activeTaskId)?String(s.activeTaskId):(tasks[0]?.id||""), tasks, v5Gate:Array.isArray(s.v5Gate)?s.v5Gate.map(String).slice(0,16):f.v5Gate }; }
