function advanceV5PolishTask(){ pushUndo(); state.v5PolishQueue=normalizeV5PolishQueue(state.v5PolishQueue); const order=["planned","open","active","review","done"]; const task=state.v5PolishQueue.tasks.find(t=>t.id===state.v5PolishQueue.activeTaskId)||state.v5PolishQueue.tasks[0]; if(task){ const idx=Math.max(0,order.indexOf(task.status)); task.status=order[Math.min(order.length-1,idx+1)]; } state.v5PolishQueue.activeTaskId=(state.v5PolishQueue.tasks.find(t=>t.status!=="done")||task)?.id||""; renderAll("Advanced v5 polish task."); }
