function validateCreatorPolishBrowser(project, errors){ if(!project?.creatorPolishDashboard||!Array.isArray(project.creatorPolishDashboard.passes)||project.creatorPolishDashboard.passes.length<3) errors.push("creatorPolishDashboard.passes must include at least three passes."); const passIds=new Set((project?.creatorPolishDashboard?.passes||[]).map(p=>p.id)); if(project?.creatorPolishDashboard?.activePassId&&!passIds.has(project.creatorPolishDashboard.activePassId)) errors.push("creatorPolishDashboard.activePassId must reference a pass."); if(!project?.firstRunTutorialFlow||!Array.isArray(project.firstRunTutorialFlow.steps)||project.firstRunTutorialFlow.steps.length<4) errors.push("firstRunTutorialFlow.steps must include at least four tutorial steps."); if(!String(project?.firstRunTutorialFlow?.boundary||"").includes("without forcing sharing")) errors.push("firstRunTutorialFlow.boundary must avoid forced sharing."); if(!project?.uxPolishBoard||!Array.isArray(project.uxPolishBoard.items)||project.uxPolishBoard.items.length<3) errors.push("uxPolishBoard.items must include polish items."); if(!project?.accessibilityPass||!Array.isArray(project.accessibilityPass.checks)||project.accessibilityPass.checks.filter(c=>c.required).length<3) errors.push("accessibilityPass.checks must include required checks."); if(!String(project?.accessibilityPass?.policy||"").includes("v5 gate")) errors.push("accessibilityPass.policy must mention v5 gate."); if(!project?.betaReadinessScorecard||!Array.isArray(project.betaReadinessScorecard.categories)||project.betaReadinessScorecard.categories.length<4) errors.push("betaReadinessScorecard.categories must include readiness categories."); if(!project?.v5PolishQueue||!Array.isArray(project.v5PolishQueue.tasks)||project.v5PolishQueue.tasks.length<4) errors.push("v5PolishQueue.tasks must include polish tasks."); if(!Array.isArray(project?.v5PolishQueue?.v5Gate)||!project.v5PolishQueue.v5Gate.some(g=>String(g).includes("rights metadata"))) errors.push("v5PolishQueue.v5Gate must preserve rights metadata gate."); }

function validatePrivateRelayPackBridgeBrowser(project, errors){ const relay=project?.privateRelayBridge; if(!relay || typeof relay!=="object" || Array.isArray(relay)){ errors.push("privateRelayBridge must be an object."); return; } if(!Array.isArray(relay.profiles)||relay.profiles.length<2) errors.push("privateRelayBridge.profiles must include at least two profiles."); const profileIds=new Set((relay.profiles||[]).map(p=>p.id)); if(relay.activeProfileId&&!profileIds.has(relay.activeProfileId)) errors.push("privateRelayBridge.activeProfileId must reference a profile."); if(!Array.isArray(relay.boundaries)||!relay.boundaries.some(b=>String(b).includes("no free-text chat"))) errors.push("privateRelayBridge.boundaries must preserve no free-text chat."); if(!Array.isArray(relay.packetContract)||!relay.packetContract.some(pkt=>pkt.type==="signal_ping")) errors.push("privateRelayBridge.packetContract must include signal_ping."); const pack=project?.signedPackBridge; if(!pack||!Array.isArray(pack.packs)||pack.packs.length<2) errors.push("signedPackBridge.packs must include at least two packs."); const packIds=new Set((pack?.packs||[]).map(p=>p.id)); if(pack?.activePackId&&!packIds.has(pack.activePackId)) errors.push("signedPackBridge.activePackId must reference a pack."); (pack?.packs||[]).forEach((p,index)=>{ if(!p.rightsStatus) errors.push(`signedPackBridge.packs[${index}].rightsStatus required.`); if(!p.hashMode) errors.push(`signedPackBridge.packs[${index}].hashMode required.`); }); const router=project?.trustCircleRouter; if(!router||!Array.isArray(router.circles)||router.circles.length<2) errors.push("trustCircleRouter.circles must include at least two circles."); const circleIds=new Set((router?.circles||[]).map(c=>c.id)); if(router?.activeCircleId&&!circleIds.has(router.activeCircleId)) errors.push("trustCircleRouter.activeCircleId must reference a circle."); (router?.routes||[]).forEach((route,index)=>{ if(!packIds.has(route.from)) errors.push(`trustCircleRouter.routes[${index}].from references missing pack.`); if(!circleIds.has(route.to)) errors.push(`trustCircleRouter.routes[${index}].to references missing circle.`); }); const lab=project?.syncDryRunLab; if(!lab||!Array.isArray(lab.runs)||lab.runs.length<1) errors.push("syncDryRunLab.runs must include at least one run."); (lab?.runs||[]).forEach((run,index)=>{ if(!profileIds.has(run.profileId)) errors.push(`syncDryRunLab.runs[${index}].profileId references missing relay profile.`); if(!packIds.has(run.packId)) errors.push(`syncDryRunLab.runs[${index}].packId references missing pack.`); }); if(!Array.isArray(lab?.blockedPayloads)||!lab.blockedPayloads.includes("chatText")) errors.push("syncDryRunLab.blockedPayloads must include chatText."); const beta=project?.betaGatePreflight; if(!beta||!Array.isArray(beta.checks)||beta.checks.length<4) errors.push("betaGatePreflight.checks must include beta readiness checks."); if(beta&&!beta.checks.some(c=>c.id==="gate_no_chat"&&c.status==="pass")) errors.push("betaGatePreflight must include passing gate_no_chat check."); }


